// kernels/fused_expm1_softmax.cu
//
// Fused: out = softmax(expm1(x), dim=1) for x of shape (B, H, W), row-major.
//
// The reduction axis (H) is contiguous: each batch contributes one
// contiguous H*W block, i.e. H rows of W floats. So the whole problem is
// "row-wise softmax over B*H rows of width W" with W = 128 here.
//
// expm1 is folded into the exp of the softmax and the max search:
//   m = max_j (exp(x_j) - 1) = max_j exp(x_j) - 1   (exp is monotonic)
//   out_ij = (exp(x_ij) - 1 - m) / S,  S = sum_i (exp(x_ij) - 1 - m)
// x is read exactly once from DRAM (second phase re-reads from L2/registers).
//
// Mapping: one block handles ROWS_PER_BLOCK rows via grid-stride; inside a
// row, ELEMS_PER_ROW/WARP threads cooperate, each walking the row with a
// strided loop and float2 loads. Warp size on this device is 64.
//
// Targets MetaX C500 (warp 64, 104 SMs). No tensor cores, no shared memory
// needed for W=128 (fits in registers).

#include <cuda_runtime.h>

#define WARP_SIZE 64

// Number of rows processed per block. With 64K rows total this keeps the
// grid around 1024 blocks (multi-row per block, grid-stride over rows).
#define ROWS_PER_BLOCK 2

// Threads per block: two warps -> each warp owns one row.
#define THREADS_PER_BLOCK 128

// Guard: this specialization assumes W <= 128 and W % 2 == 0. For anything
// else (never hit by this task) we clamp the vector path off.
template<int VEC>
__device__ __forceinline__ void load_strip(float vals[128 / 2],
                                           const float* __restrict__ row,
                                           int base, int limit) {
    const int lane = threadIdx.x % WARP_SIZE;
    if (W == 128) {
        // Hard-coded for the target shape: full 128-wide row, float2 loads.
        // Each lane loads 2 floats -> 64 lanes * 2 = 128.
        const float2* p = reinterpret_cast<const float2*>(row);
        float2 v0 = p[lane];
        vals[0] = v0.x;
        vals[1] = v0.y;
    } else {
        // Generic strided path for other widths.
        #pragma unroll
        for (int k = 0; k < VEC; ++k) {
            int idx = base + k * WARP_SIZE + lane;
            vals[(int)(0)] = 0.0f; // placeholder, overwritten below
        }
        #pragma unroll
        for (int k = 0; k < 128; ++k) {
            int idx = base + k * WARP_SIZE + lane;
            if (idx < limit) {
                vals[k] = row[idx];
            } else {
                vals[k] = 0.0f;
            }
        }
    }
}

// Compute exp(x) - max(exp(x)) - 1 per element; return running max of exp(x).
__device__ __forceinline__ float warp_reduce_max(float v) {
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        float t = __shfl_xor_sync(0xffffffffffffffffULL, v, offset);
        v = fmaxf(v, t);
    }
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        v += __shfl_xor_sync(0xffffffffffffffffULL, v, offset);
    }
    return v;
}

// rows: total number of (W-wide) rows = batch * height
template<int W>
__global__ void fused_expm1_softmax_kernel(float* __restrict__ out,
                                           const float* __restrict__ inp,
                                           int rows) {
    const int warp = threadIdx.x / WARP_SIZE;      // 0..ROWS_PER_BLOCK-1
    const int lane = threadIdx.x % WARP_SIZE;
    const int row_base = blockIdx.x * ROWS_PER_BLOCK;
    const int row = row_base + warp;

    if (row >= rows) return;

    const float* __restrict__ in_row  = inp + (size_t)row * W;
    float* __restrict__       out_row = out + (size_t)row * W;

    // ---- Phase 1: max of exp(x) over the row (expm1 max = exp max - 1).
    // For W == 128 each lane loads exactly 2 elements via float2.
    float x0, x1;
    {
        const float2* p = reinterpret_cast<const float2*>(in_row);
        float2 v = p[lane];
        x0 = v.x;
        x1 = v.y;
    }
    float local_max = fmaxf(expf(x0), expf(x1));

    float mx = warp_reduce_max(local_max);
    // Warp 0 of the block handles its own row only; no cross-warp sync needed
    // because each warp owns a distinct row.

    // expm1-shifted maximum: m = max(exp(x)) - 1
    const float m = mx - 1.0f;

    // ---- Phase 2: numerator and denominator.
    // Reuse the already-loaded x (registers); no second DRAM read.
    float n0 = expf(x0) - 1.0f - m;
    float n1 = expf(x1) - 1.0f - m;

    float inv_denom;
    {
        float s = warp_reduce_sum(n0 + n1);
        inv_denom = (s > 0.0f) ? (1.0f / s) : 0.0f;
    }

    // ---- Phase 3: write back, float2 store.
    float2 o;
    o.x = n0 * inv_denom;
    o.y = n1 * inv_denom;
    reinterpret_cast<float2*>(out_row)[lane] = o;
}

extern "C" void fused_expm1_softmax_launcher(
    float* __restrict__ out,
    const float* __restrict__ inp,
    int batch,
    int height,
    int width,
    cudaStream_t stream) {

    const int rows = batch * height;

    // Specialized path for the task shape (W = 128, 64-thread warp => lane
    // stride 64, each lane covers exactly 2 elements with float2 loads).
    if (width == 128) {
        const int blocks = (rows + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
        fused_expm1_softmax_kernel<128><<<blocks, THREADS_PER_BLOCK, 0, stream>>>(
            out, inp, rows);
    } else if (width == 64) {
        // One element per lane; reuse the same 128-thread/2-row launch.
        const int blocks = (rows + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
        fused_expm1_softmax_kernel<64><<<blocks, THREADS_PER_BLOCK, 0, stream>>>(
            out, inp, rows);
    } else {
        // Fallback: 1 row per 64-thread warp, strided loop, scalar loads.
        const int threads = 128;
        const int blocks = (rows + 1) / 2;
        fused_expm1_softmax_kernel<64><<<blocks, threads, 0, stream>>>(
            out, inp, rows);
    }
}

