import torch
import torch.nn as nn

import cuda_extension


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x):
        # Fused single-pass: expm1 + softmax(dim=1).
        # Only the custom op is used; no torch ops on the activation path.
        return cuda_extension.fused_expm1_softmax_forward(x)


# Original task constants (kept for parity with model.py; not modified there).
batch_size = 64
width = 128
height = 1024


def get_inputs():
    x = torch.randn(batch_size, height, width)
    return [x]


def get_init_inputs():
    # No learnable parameters.
    return []

