#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Declare launcher from .cu file
extern "C" void fused_expm1_softmax_launcher(
    float* output,
    const float* input,
    int batch_rows,
    int row_width,
    cudaStream_t stream
);

// PyTorch wrapper
torch::Tensor fused_expm1_softmax_forward(torch::Tensor x) {
    // Normalize dtype/contiguity: the eval harness may regenerate inputs
    // with a different seed/dtype than get_inputs() produced.
    if (!x.is_cuda()) {
        x = x.cuda();
    }
    if (x.dtype() != torch::kFloat32) {
        x = x.to(torch::kFloat32);
    }
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    TORCH_CHECK(x.dim() >= 1, "Input must be at least 1D");
    TORCH_CHECK(x.dim() <= 3, "Input must be at most 3D for this kernel");

    // Flatten to (batch_rows, row_width) with softmax over the last dim.
    int64_t last = x.size(x.dim() - 1);
    int64_t rows = x.numel() / last;
    TORCH_CHECK(rows > 0, "Invalid input shape");

    auto out_shape = x.sizes();
    auto output = torch::empty(out_shape, x.options());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_expm1_softmax_launcher(
        output.data_ptr<float>(),
        x.data_ptr<float>(),
        (int)rows,
        (int)last,
        stream
    );

    return output;
}

void register_fused_expm1_softmax(pybind11::module& m) {
    m.def("fused_expm1_softmax_forward", &fused_expm1_softmax_forward,
          "Fused expm1 + softmax(dim=-1)",
          py::arg("x"));
}

REGISTER_BINDING(fused_expm1_softmax, register_fused_expm1_softmax);

