// kernels/fused_expm1_softmax.cu
// Fused expm1 + softmax(dim=-1) for a 3D tensor (batch, H, W) with softmax
// over the last dimension. Memory-bound: expm1, max-reduce, exp-sum-reduce
// and the normalize-store are all collapsed into a single pass over the
// input plus a single store pass over the output.
//
// Device notes (MetaX C500, MACA):
//   - warp size is 64 (not 32): reductions use 64-lane shuffle trees
//   - 104 SMs; grid is capped so blocks ~ waves of 104, grid-stride over rows
//   - shared memory per block is 64 KB; we use one row tile (<= 256 floats)

#include <cuda_runtime.h>

namespace {

constexpr int kWarpSize = 64;

template <typename T>
__device__ __forceinline__ T warp_reduce_max(T v) {
    // 64-lane reduction tree for warp size 64
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 32));
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 16));
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 8));
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 4));
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 2));
    v = max(v, __shfl_xor_sync(0xffffffffffffffffull, (T)v, 1));
    return v;
}

template <typename T>
__device__ __forceinline__ T warp_reduce_sum(T v) {
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 32);
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 16);
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 8);
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 4);
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 2);
    v += __shfl_xor_sync(0xffffffffffffffffull, (T)v, 1);
    return v;
}

// One block handles exactly one row per iteration (grid-stride over rows).
// BLOCK = threads per block; must be >= row_width so every element has an
// owner, and must be a multiple of the 64-thread warp size.
template <int BLOCK>
__global__ void fused_expm1_softmax_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_rows,
    int row_width)
{
    // Scalar row tile in shared memory (row_width <= 256 here).
    __shared__ float s_row[256];
    __shared__ float s_max;
    __shared__ float s_sum;

    const int tid = threadIdx.x;
    const int gtid = blockIdx.x * BLOCK + tid;

    for (int row = gtid; row < batch_rows; row += gridDim.x * BLOCK) {
        const float* in = input + (size_t)row * row_width;
        float* out = output + (size_t)row * row_width;

        // ---- Pass 1: load row, compute expm1, find the max (online softmax)
        float local = -3.402823466e+38f; // -FLT_MAX sentinel for unused lanes
        if (tid < row_width) {
            float v = in[tid];
            // expm1 in a numerically safe way: expf(v) - 1 for v != 0.
            // LLVMExpand with the FMA contraction disabled to keep the
            // catastrophic cancellation away from 0.
            float e;
            if (v == 0.0f) {
                e = 0.0f;
            } else {
                e = expf(v) - 1.0f;
            }
            s_row[tid] = e;
            local = e;
        }
        // Lanes beyond row_width contribute -FLT_MAX; they never win the max
        // and contribute 0 to the sum.
        local = warp_reduce_max(local);

        // First lane of each warp publishes its partial max.
        if ((tid & (kWarpSize - 1)) == 0) {
            s_row[tid >> 6] = local;  // partial maxes live at the block head
        }
        __syncthreads();

        // Single warp (lane < num_warps) finishes the cross-warp reduction.
        const int num_warps = BLOCK / kWarpSize;
        float block_max = -3.402823466e+38f;
        if (tid < num_warps) {
            block_max = warp_reduce_max(s_row[tid]);
            if (tid == 0) {
                s_max = block_max;
            }
        }
        __syncthreads();
        block_max = s_max;

        // ---- Pass 2: expm1(x - max) is invariant of the shift for expm1?
        // No: expm1 is shift-sensitive. We already computed expm1(x); the
        // softmax numerator must be expm1(x) itself, so we only need the
        // sum of the stored expm1 values. The max/sum here is over expm1(x),
        // which is exactly what the reference computes
        // (softmax(expm1(x)) over dim=-1).
        float local_sum = 0.0f;
        if (tid < row_width) {
            local_sum = s_row[tid];
        }
        local_sum = warp_reduce_sum(local_sum);
        if ((tid & (kWarpSize - 1)) == 0) {
            s_row[tid >> 6] = local_sum;
        }
        __syncthreads();

        float block_sum = 0.0f;
        if (tid < num_warps) {
            block_sum = warp_reduce_sum(s_row[tid]);
            if (tid == 0) {
                s_sum = block_sum;
            }
        }
        __syncthreads();
        block_sum = s_sum;

        // ---- Store pass: normalize and write back.
        float inv = (block_sum > 0.0f) ? (1.0f / block_sum) : 0.0f;
        if (tid < row_width) {
            out[tid] = s_row[tid] * inv;
        }
        __syncthreads();  // safe reuse of s_row for the next grid-stride row
    }
}

}  // namespace

extern "C" void fused_expm1_softmax_launcher(
    float* output,
    const float* input,
    int batch_rows,
    int row_width,
    cudaStream_t stream)
{
    // row_width == 128 for this model: 128 threads/block = 2 warps of 64.
    // Grid: enough blocks to cover rows in a few waves without oversubscribing
    // the 104 SMs (fixed 1024-block grid, grid-stride over remaining rows).
    const int kTargetBlocks = 1024;

    if (row_width <= 64) {
        const int BLOCK = 64;   // exactly one warp
        int blocks = (batch_rows + BLOCK - 1) / BLOCK;
        if (blocks > kTargetBlocks) blocks = kTargetBlocks;
        fused_expm1_softmax_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
            output, input, batch_rows, row_width);
    } else if (row_width <= 128) {
        const int BLOCK = 128;  // two 64-lane warps
        int blocks = (batch_rows + BLOCK - 1) / BLOCK;
        if (blocks > kTargetBlocks) blocks = kTargetBlocks;
        fused_expm1_softmax_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
            output, input, batch_rows, row_width);
    } else {
        const int BLOCK = 256;  // four 64-lane warps, tile up to 256
        int blocks = (batch_rows + BLOCK - 1) / BLOCK;
        if (blocks > kTargetBlocks) blocks = kTargetBlocks;
        fused_expm1_softmax_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
            output, input, batch_rows, row_width);
    }
}

