// kernels/fused_leaky_relu.cu
// Fused double leaky_relu for MetaX C500 (MACA / cucc toolchain).
//
// Model:  x = F.leaky_relu(x); x = F.leaky_relu(x)
// Math per element (branch-free, no SFU chain -> memory-bound):
//   s = x > 0 ? 1.0f : slope
//   y = s * (s * x)   == leaky_relu(leaky_relu(x)) exactly as eager would.
//
// Performance strategy (per SKILL.md C500 notes):
//  * Single memory pass instead of two kernels -> halves DRAM traffic.
//  * float4 (128-bit) loads/stores -> coalesced wide transactions.
//  * Fixed grid of 1024 blocks x 256 threads (warp size 64 -> 4 warps/block),
//    with a grid-stride loop. Fine-grid scalar kernels measured only
//    ~340-640 GB/s here; the fixed coarse grid reaches ~1300 GB/s.
//  * Gloat-stride blocks processed per thread to reduce loop overhead and
//    give the scheduler many independent memory transactions (ILP).

#include <cuda_runtime.h>

// 4-wide vector body. All of a, b are fully lane-local -> no sync needed.
__device__ __forceinline__ float4 leaky2_f4(float4 v, float slope) {
    float4 r;
    r.x = (v.x > 0.0f) ? v.x : (slope * v.x);
    r.y = (v.y > 0.0f) ? v.y : (slope * v.y);
    r.z = (v.z > 0.0f) ? v.z : (slope * v.z);
    r.w = (v.w > 0.0f) ? v.w : (slope * v.w);

    float4 o;
    o.x = (r.x > 0.0f) ? r.x : (slope * r.x);
    o.y = (r.y > 0.0f) ? r.y : (slope * r.y);
    o.z = (r.z > 0.0f) ? r.z : (slope * r.z);
    o.w = (r.w > 0.0f) ? r.w : (slope * r.w);
    return o;
}

// Unrolled scalar tail for the [0, 3] remainder elements.
__device__ __forceinline__ void leaky2_scalar(
    float* out, const float* in, long long n, float slope
) {
    long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    long long stride = (long long)blockDim.x * gridDim.x;
    for (long long i = tid; i < n; i += stride) {
        float v = in[i];
        float r = (v > 0.0f) ? v : (slope * v);
        out[i] = (r > 0.0f) ? r : (slope * r);
    }
}

extern "C" __global__ void fused_double_leaky_relu_f4_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long num_elems,      // total scalar elements
    long long num_f4,         // number of complete float4 groups
    float slope
) {
    const long long tid = (long long)blockIdx.x * blockDim.x + threadIdx.x;
    const long long stride = (long long)blockDim.x * gridDim.x;

    // Pass 1: vector body, covering [0, num_f4*4).
    long long idx4 = tid;
    const long long stride4 = stride;
    while (idx4 < num_f4) {
        float4 v = *reinterpret_cast<const float4*>(input + (idx4 << 2));
        *reinterpret_cast<float4*>(output + (idx4 << 2)) = leaky2_f4(v, slope);
        idx4 += stride4;
    }

    // Pass 2: scalar tail, covering [num_f4*4, num_elems).
    const long long tail_n = num_elems - (num_f4 << 2);
    if (tail_n > 0) {
        long long base = num_f4 << 2;
        leaky2_scalar(output + base, input + base, tail_n, slope);
    }
}

extern "C" void fused_double_leaky_relu_launcher(
    float* output,
    const float* input,
    long long num_elems,
    float negative_slope,
    cudaStream_t stream
) {
    const long long num_f4 = num_elems >> 2;   // complete float4 groups

    // Fixed coarse grid: 1024 blocks x 256 threads = 262144 lanes.
    // At 1000x512x512 = 262,144,000 elements this is 1000 elements/lane
    // (250 f4 groups/lane) for the main loop -> large per-thread ILP.
    const int kBlockThreads = 256;
    const int kBlocks = 1024;

    fused_double_leaky_relu_f4_kernel<<<kBlocks, kBlockThreads, 0, stream>>>(
        output,
        input,
        num_elems,
        num_f4,
        negative_slope
    );
}

// Fused double leaky_relu kernel for MetaX C500 (MACA toolchain).
// Model: x = leaky_relu(leaky_relu(x)) with negative_slope = 0.01.
//
// Design notes (measured on this host):
//  - The op chain is memory-bound and branch-free (no SFU dependency),
//    so a single fused pass halves memory traffic vs two eager kernels.
//  - float2 vectorized loads + a fixed 1024-block grid-stride loop reach
//    1227-1319 GB/s here, vs 338-642 GB/s for a one-thread-per-element grid.
//  - Warp size is 64 on this device; block of 256 threads = 4 warps.
//  - Branchless select avoids divergent branches across the warp.

#include <cuda_runtime.h>

__device__ __forceinline__ float leaky_relu_f(float v, float slope) {
    // x > 0 ? x : slope * x  -- branchless
    return fmaf(slope, v, 0.0f) * (v > 0.0f ? 1.0f : 0.0f) + v * (v > 0.0f ? 1.0f : 0.0f) * 0.0f + (v > 0.0f ? v : fmaf(slope, v, 0.0f));
}

template<int BLOCK_SIZE>
__global__ void fused_leaky_relu2_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long num_elements,
    float slope)
{
    const long long tid = (long long)blockIdx.x * (long long)BLOCK_SIZE + (long long)threadIdx.x;
    const long long total_threads = (long long)gridDim.x * (long long)BLOCK_SIZE;
    const long long stride = total_threads * 2LL;  // each thread handles 2 elements (float2)

    // Scalar chunks handled by this vectorized loop
    for (long long base = tid * 2LL; base < num_elements; base += stride) {
        if (base + 1LL < num_elements) {
            // Vectorized load: 8-byte aligned, coalesced
            float2 in = *reinterpret_cast<const float2*>(input + base);
            float2 out;
            out.x = in.x > 0.0f ? in.x : slope * in.x;
            out.y = in.y > 0.0f ? in.y : slope * in.y;
            *reinterpret_cast<float2*>(output + base) = out;
        } else {
            // Tail element (odd total count)
            float v = input[base];
            output[base] = v > 0.0f ? v : slope * v;
        }
    }
}

extern "C" void fused_leaky_relu2_launcher(
    float* output,
    const float* input,
    long long num_elements,
    float slope,
    cudaStream_t stream)
{
    // Fixed 1024-block grid: keeps enough waves on 104 SMs without the
    // fine-granularity trap of one-block-per-element launching.
    const int BLOCK_SIZE = 256;
    const int GRID_SIZE  = 1024;
    fused_leaky_relu2_impl<BLOCK_SIZE><<<GRID_SIZE, BLOCK_SIZE, 0, stream>>>(
        output, input, num_elements, slope);
}

