// Fused stack + softmax binding for MetaX C500
// Reads 10 source tensors directly, writes stacked softmax output in one pass.
#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Launcher implemented in kernels/fused_stack_softmax.cu
extern "C" void fused_stack_softmax_launcher(
    float* out,
    const float* const* srcs,
    int num_srcs,
    long long rows,
    int row_len,
    int smem_bytes,
    cudaStream_t stream
);

// One row of the stacked output per block; rows = num_srcs * d0 * d1 * h
static torch::Tensor fused_stack_softmax_forward_impl(
    std::vector<torch::Tensor> tensors,
    int smem_bytes
) {
    TORCH_CHECK(!tensors.empty(), "empty tensor list");
    int num_srcs = (int)tensors.size();

    // Normalize dtype / contiguity: harness may regenerate inputs differently.
    for (auto& t : tensors) {
        if (!t.is_cuda()) t = t.cuda();
        if (t.dtype() != torch::kFloat32) t = t.to(torch::kFloat32);
        if (!t.is_contiguous()) t = t.contiguous();
    }

    TORCH_CHECK(tensors[0].dim() == 4, "expected 4D tensors");
    const long long d0 = tensors[0].size(0);
    const long long d1 = tensors[0].size(1);
    const long long h = tensors[0].size(2);
    const int row_len = (int)tensors[0].size(3);

    // Validate shapes against the first tensor.
    for (int i = 1; i < num_srcs; ++i) {
        TORCH_CHECK(tensors[i].dim() == 4, "expected 4D tensors");
        TORCH_CHECK(tensors[i].size(0) == d0 && tensors[i].size(1) == d1 &&
                    tensors[i].size(2) == h && (long long)tensors[i].size(3) == row_len,
                    "tensor shape mismatch at index ", i);
    }

    const long long rows = (long long)num_srcs * d0 * d1 * h;

    auto out = torch::empty({(long long)num_srcs, d0, d1, h, row_len},
                            torch::TensorOptions().dtype(torch::kFloat32)
                                                  .device(tensors[0].device()));

    // Array of source base pointers (device-visible).
    auto ptrs = torch::empty({num_srcs}, torch::TensorOptions()
                                  .dtype(torch::kInt64)
                                  .device(tensors[0].device()));
    {
        // Build on host then copy: small (10 * 8B).
        std::vector<int64_t> bases(num_srcs);
        for (int i = 0; i < num_srcs; ++i) bases[i] = (int64_t)tensors[i].data_ptr<float>();
        cudaMemcpyAsync(ptrs.data_ptr<int64_t>(), bases.data(),
                        num_srcs * sizeof(int64_t), cudaMemcpyHostToDevice,
                        c10::cuda::getCurrentCUDAStream().stream());
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    fused_stack_softmax_launcher(
        out.data_ptr<float>(),
        (const float* const*)ptrs.data_ptr<int64_t>(),
        num_srcs, rows, row_len, smem_bytes, stream
    );
    return out;
}

static torch::Tensor fused_stack_softmax_forward_var(
    pybind11::list tensors, int smem_bytes
) {
    std::vector<torch::Tensor> vec;
    vec.reserve((size_t)tensors.size());
    for (auto item : tensors) vec.push_back(item.cast<torch::Tensor>());
    return fused_stack_softmax_forward_impl(std::move(vec), smem_bytes);
}

static torch::Tensor fused_stack_softmax_forward(
    std::vector<torch::Tensor> tensors, int smem_bytes
) {
    return fused_stack_softmax_forward_impl(std::move(vec_wrapper(tensors)), smem_bytes);
}

void register_fused_stack_softmax(pybind11::module& m) {
    m.def("fused_stack_softmax", &fused_stack_softmax_forward,
          "Fused stack + softmax over last dim",
          pybind11::arg("tensors"),
          py::arg("smem_bytes") = 4096);
    m.def("fused_stack_softmax_list", &fused_stack_softmax_forward_var,
          "Fused stack + softmax over last dim (list input)",
          py::arg("tensors"),
          py::arg("smem_bytes") = 4096);
}

