// Fused stack + softmax for MetaX C500 (warp size 64, 104 SMs, 64KB SMEM).
//
// Replaces:   torch.stack(list, dim=0)  ->  nn.Softmax(dim=-1)
// with a single pass that reads the 10 source tensors directly and writes the
// stacked softmax output. Eliminates the full-size intermediate stack tensor,
// cutting memory traffic from 2 passes to 1 (reads 10x16x3x512x512x4B =
// 167.8MB, writes the same).
//
// Parallelization: one block per output row (row_len floats). With
// row_len=512 there are 10*16*3*512*512 = 393216 rows -> plenty of blocks to
// fill 104 SMs. Thread coarsening (ELEMS_PER_THREAD) amortizes the reduction
// tree; the row max/sum reductions use shared memory with one bank-conflict-
// free slot per thread.

#include <cuda_runtime.h>

typedef unsigned long long u64;

template <int TPB, int ELEMS_PER_THREAD>
__device__ __forceinline__ void load_row(
    float locals[ELEMS_PER_THREAD],
    const float* __restrict__ row_in,
    int row_len,
    int tid)
{
    const int stride = TPB;
    #pragma unroll
    for (int e = 0; e < ELEMS_PER_THREAD; ++e) {
        int idx = tid + e * stride;
        locals[e] = (idx < row_len) ? row_in[idx] : -INFINITY;
    }
}

// Sequential-access final scan of the ~TPB partials; TPB is small (64) so this
// is cheap and keeps shared memory usage at TPB*4 bytes.
template <int TPB>
__device__ __forceinline__ float reduce_smax(volatile float* smem, int tid) {
    if (tid == 0) {
        float m = smem[0];
        #pragma unroll
        for (int i = 1; i < TPB; ++i) {
            float v = smem[i];
            m = (v > m) ? v : m;
        }
        smem[0] = m;
    }
    __syncthreads();
    return smem[0];
}

template <int TPB>
__device__ __forceinline__ float reduce_ssum(volatile float* smem, int tid) {
    if (tid == 0) {
        float s = 0.f;
        #pragma unroll
        for (int i = 0; i < TPB; ++i) s += smem[i];
        smem[0] = s;
    }
    __syncthreads();
    return smem[0];
}

template <int TPB, int ELEMS_PER_THREAD>
__global__ void fused_stack_softmax_kernel(
    float* __restrict__ out,
    const float* const* __restrict__ srcs,
    const u64* __restrict__ row_offsets,   // precomputed byte offsets per src
    int num_srcs,
    long long rows,
    int row_len)
{
    // extern smem layout: [TPB floats for max][TPB floats for sum]
    extern __shared__ float smem_raw[];
    float* smem_max = smem_raw;
    float* smem_sum = smem_raw + TPB;

    const int tid = threadIdx.x;
    const int lane = tid & 63;

    for (long long r = (long long)blockIdx.x; r < rows; r += (long long)gridDim.x) {
        int s = (int)(r / (long long)num_srcs);      // which source tensor
        long long local_row = r - (long long)s * (long long)num_srcs;  // WRONG placeholder, fixed below
        (void)local_row;

        // Each blockIdx.x handles row r. Derive source index and in-tensor row.
        // rows are indexed s-major: r = s * rows_per_src + local_row
        long long rows_per_src = rows / (long long)num_srcs;
        int src = (int)((long long)r / rows_per_src);
        long long lrow = (long long)r - (long long)src * rows_per_src;

        const float* row_in = (const float*)((const char*)srcs[src] + row_offsets[src])
                              + lrow * (long long)row_len;
        float* row_out = out + r * (long long)row_len;

        float locals[ELEMS_PER_THREAD];
        load_row<TPB, ELEMS_PER_THREAD>(locals, row_in, row_len, tid);

        // ---- Max reduction (with warp shuffles, then shared memory) ----
        float my_max = locals[0];
        #pragma unroll
        for (int e = 1; e < ELEMS_PER_THREAD; ++e) my_max = fmaxf(my_max, locals[e]);

        #pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            float t = __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_max, off);
            my_max = fmaxf(my_max, t);
        }
        // C500 warp size is 64: first shuffle within the lower 64 lanes.
        my_max = fmaxf(my_max, __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_max, 32));

        smem_max[tid] = my_max;
        __syncthreads();

        // Since TPB == 64 == warp size, the shuffle already finished the job
        // across all threads; smem broadcast keeps it uniform.
        if (tid == 0) smem_max[0] = my_max;
        __syncthreads();
        float row_max = smem_max[0];

        // ---- exp and sum reduction ----
        float my_sum = 0.f;
        #pragma unroll
        for (int e = 0; e < ELEMS_PER_THREAD; ++e) {
            locals[e] = expf(locals[e] - row_max);
            my_sum += locals[e];
        }

        #pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            my_sum += __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_sum, off);
        }
        my_sum += __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_sum, 32);

        smem_sum[tid] = my_sum;
        __syncthreads();
        if (tid == 0) smem_sum[0] = my_sum;
        __syncthreads();
        float row_sum = smem_sum[0];

        float inv = 1.f / row_sum;

        // ---- Store normalized ----
        const int stride = TPB;
        #pragma unroll
        for (int e = 0; e < ELEMS_PER_THREAD; ++e) {
            int idx = tid + e * stride;
            if (idx < row_len) row_out[idx] = locals[e] * inv;
        }
    }
}

// ---------------- Row-general kernel (works for any row_len) ----------------
// For row_len that is not a multiple of TPB*ELEMS_PER_THREAD, or small rows,
// use a plain loop with handled bounds. Kept as the safe default path.
template <int TPB>
__global__ void fused_stack_softmax_kernel_generic(
    float* __restrict__ out,
    const float* const* __restrict__ srcs,
    const u64* __restrict__ row_offsets,
    int num_srcs,
    long long rows,
    int row_len)
{
    extern __shared__ float smem_raw[];
    float* smem_max = smem_raw;
    float* smem_sum = smem_raw + TPB;

    const int tid = threadIdx.x;

    for (long long r = (long long)blockIdx.x; r < rows; r += (long long)gridDim.x) {
        long long rows_per_src = rows / (long long)num_srcs;
        int src = (int)((long long)r / rows_per_src);
        long long lrow = (long long)r - (long long)src * rows_per_src;

        const float* row_in = (const float*)((const char*)srcs[src] + row_offsets[src])
                              + lrow * (long long)row_len;
        float* row_out = out + r * (long long)row_len;

        float my_max = -INFINITY;
        for (int i = tid; i < row_len; i += TPB) {
            float v = row_in[i];
            my_max = fmaxf(my_max, v);
        }

        #pragma unroll
        for (int off = 32; off > 0; off >>= 1)
            my_max = fmaxf(my_max, __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_max, off));
        my_max = fmaxf(my_max, __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_max, 32));

        smem_max[tid] = my_max;
        __syncthreads();
        if (tid == 0) smem_max[0] = my_max;
        __syncthreads();
        float row_max = smem_max[0];

        float my_sum = 0.f;
        for (int i = tid; i < row_len; i += TPB) my_sum += expf(row_in[i] - row_max);

        #pragma unroll
        for (int off = 32; off > 0; off >>= 1)
            my_sum += __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_sum, off);
        my_sum += __shfl_down_sync(0xFFFFFFFFFFFFFFFFULL, my_sum, 32);

        smem_sum[tid] = my_sum;
        __syncthreads();
        if (tid == 0) smem_sum[0] = my_sum;
        __syncthreads();
        float inv = 1.f / smem_sum[0];

        for (int i = tid; i < row_len; i += TPB) row_out[i] = expf(row_in[i] - row_max) * inv;
    }
}

// ---------------- Host launcher (no torch headers here) ----------------
extern "C" void fused_stack_softmax_launcher(
    float* out,
    const float* const* srcs,
    int num_srcs,
    long long rows,
    int row_len,
    int smem_bytes,
    cudaStream_t stream)
{
    // srcs currently points at an array of base pointers; offsets are all 0.
    // Build an all-zero offset table on the host stack and pass it via a
    // small device allocation is avoided: instead we reinterpret the same
    // array as offsets == 0 by passing a zero table.
    (void)smem_bytes;
    (void)srcs;

    // Determine grid: cap blocks so we don't oversubscribe; each block handles
    // one row, grid-stride over rows.
    int blocks = 2048;
    if ((long long)blocks > rows) blocks = (int)rows;
    if (blocks < 1) blocks = 1;

    // Generic path (TPB=64) handles row_len=512 with 8 elems/thread implied.
    int smem = 2 * 64 * (int)sizeof(float);
    fused_stack_softmax_kernel_generic<64>
        <<<blocks, 64, smem, stream>>>(out, (const float* const*)srcs_ptr_holder,
                                       zero_offsets_holder, num_srcs, rows, row_len);
}

