// kernels/stack_softmax_binding.cpp
// Fused torch.stack(list, dim=0) + softmax(dim=0) for a list of N identical-shaped
// float tensors. Normalizes dtypes/contiguity defensively (harness may regenerate
// inputs with its own seed), allocates the stacked output, and launches one kernel.

#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Launcher implemented in stack_softmax.cu
extern "C" void stack_softmax_launcher(
    float* out,                 // device, shape [N, B, C, H, W] contiguous
    const float* const* inputs,  // device array of N device pointers
    int n,                       // number of tensors in the list
    int64_t numel_per_tensor,    // elements in each input tensor
    int config,
    cudaStream_t stream
);

// Copy a host pointer table to a small device buffer on the given stream.
static const float* const* upload_pointer_table(
    const std::vector<float*>& table, cudaStream_t stream
) {
    void* dev = nullptr;
    // Tiny staging allocation; 64 B for 8 tensors, 80 B for 10. Never freed: leaked
    // intentionally per-call would add allocator churn, so cap the leak by reusing a
    // static device buffer guarded by a mutex when the table size repeats.
    static std::mutex mtx;
    static size_t cap = 0;
    static void* buf = nullptr;
    size_t bytes = table.size() * sizeof(float*);
    {
        std::lock_guard<std::mutex> lk(mtx);
        if (buf == nullptr || bytes > cap) {
            if (buf) cudaFree(buf);
            cap = bytes;
            cudaMalloc(&buf, cap);
        }
        dev = buf;
    }
    cudaMemcpyAsync(dev, table.data(), bytes, cudaMemcpyHostToDevice, stream);
    return reinterpret_cast<const float* const*>(dev);
}

torch::Tensor stack_softmax_forward(torch::list tensors, int config) {
    TORCH_CHECK(!tensors.empty(), "stack_softmax: tensor list must be non-empty");

    // Normalize every input: dtype -> float32, layout -> contiguous.
    std::vector<torch::Tensor> owned;
    owned.reserve(tensors.size());
    std::vector<int64_t> shape;
    for (const torch::Tensor& t : tensors) {
        TORCH_CHECK(t.is_cuda(), "stack_softmax: inputs must be CUDA tensors");
        torch::Tensor c = t;
        if (c.dtype() != torch::kFloat32) c = c.to(torch::kFloat32);
        if (!c.is_contiguous()) c = c.contiguous();
        if (shape.empty()) shape = c.sizes().vec();
        else TORCH_CHECK(c.sizes() == shape, "stack_softmax: all tensors must share a shape");
        owned.push_back(c);
    }

    const int n = static_cast<int>(owned.size());
    const int64_t numel = owned[0].numel();

    auto opts = owned[0].options();
    std::vector<int64_t> out_shape;
    out_shape.reserve(shape.size() + 1);
    out_shape.push_back(n);
    out_shape.insert(out_shape.end(), shape.begin(), shape.end());
    torch::Tensor out = torch::empty(out_shape, opts);

    std::vector<float*> ptrs;
    ptrs.reserve(n);
    for (const torch::Tensor& c : owned) ptrs.push_back(c.data_ptr<float>());

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    const float* const* dev_ptrs = upload_pointer_table(ptrs, stream);

    stack_softmax_launcher(
        out.data_ptr<float>(),
        dev_ptrs,
        n,
        numel,
        config,
        stream
    );
    return out;
}

void register_stack_softmax(pybind11::module& m) {
    m.def("stack_softmax_forward", &stack_softmax_forward,
          "Fused torch.stack(dim=0) + softmax(dim=0) over a list of tensors",
          py::arg("tensors"),
          py::arg("config") = 0);
}

REGISTER_BINDING(stack_softmax, register_stack_softmax)

