#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include "../binding_registry.h"

// Launchers implemented in kernels/softmin_fused.cu
extern "C" void softmin_fused_run(
    float* out, const float* x,
    float* pm, float* ps, float* row_m, float* row_s,
    long long B, long long L, long long F,
    long long CHUNKS, long long CHUNK_ELEMS,
    int config, cudaStream_t stream);

extern "C" void softmin_fused_workspace(
    long long B, long long L, long long F,
    long long* chunk_elems, long long* chunks,
    long long* partials, long long* rows);

static torch::Tensor g_pm, g_ps, g_rm, g_rs;  // persistent scratch

static void ensure_scratch(long long partials, long long rows) {
    if (!g_pm.defined() || g_pm.numel() < partials) {
        g_pm = torch::empty({partials}, torch::TensorOptions().device(torch::kCUDA).dtype(torch::kFloat32));
        g_ps = torch::empty({partials}, torch::TensorOptions().device(torch::kCUDA).dtype(torch::kFloat32));
    }
    if (!g_rm.defined() || g_rm.numel() < rows) {
        g_rm = torch::empty({rows}, torch::TensorOptions().device(torch::kCUDA).dtype(torch::kFloat32));
        g_rs = torch::empty({rows}, torch::TensorOptions().device(torch::kCUDA).dtype(torch::kFloat32));
    }
}

torch::Tensor softmin_fused_forward(torch::Tensor input, int dim, int config) {
    if (!input.is_cuda()) input = input.to(torch::kCUDA);;
    if (input.dtype() != torch::kFloat32) input = input.to(torch::kFloat32);
    if (!input.is_contiguous()) input = input.contiguous();

    TORCH_CHECK(input.dim() == 3, "expected a 3D tensor");
    TORCH_CHECK(dim == 1 || dim == -2,
                "custom softmin supports dim=1 only");

    long long B = input.size(0);
    long long L = input.size(1);
    long long F = input.size(2);
    long long N = B * L * F;

    auto out = torch::empty({input.size(0), input.size(1), input.size(2)},
                            input.options());

    long long chunk_elems = 0, chunks = 0, partials = 0, rows = 0;
