// kernels/relu_softmax.cu — fused relu + softmax over the last dimension.
// Two-pass structure (max-shift for numerical stability):
//   pass A: row max of relu(x)  -> stored in scratch
//   pass B: exp(relu(x) - m), row sum (single contribution reduction), then scale
// The reduction is over `cols` elements per row; each block handles
// multiple rows via a grid-stride loop over the row index.
#include <cuda_runtime.h>

#define WARP_SIZE 64

template<int BLOCK>
__device__ __forceinline__ float warp_reduce_max(float v) {
#pragma unroll
    for (int off = WARP_SIZE >> 1; off > 0; off >>= 1) {
        float t = __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, v, off);
        v = fmaxf(v, t);
    }
    return v;
}

template<int BLOCK>
__device__ __forceinline__ float warp_reduce_sum(float v) {
#pragma unroll
    for (int off = WARP_SIZE >> 1; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, v, off);
    }
    return v;
}

template<int BLOCK>
__device__ __forceinline__ float block_reduce_max(float v, float* smem) {
    int tid = threadIdx.x;
    int lane = tid & (WARP_SIZE - 1);
    int warp = tid >> 6;  // warp index, warp size 64
    v = warp_reduce_max<BLOCK>(v);
    if (BLOCK > WARP_SIZE) {
        if (lane == 0) smem[warp] = v;
        __syncthreads();
        constexpr int NWARP = BLOCK >> 6;
        v = (tid < NWARP) ? smem[tid] : -INFINITY;
        if (tid < WARP_SIZE) v = warp_reduce_max<BLOCK>(v);
        __syncthreads();
    }
    return v;
}

template<int BLOCK>
__device__ __forceinline__ float block_reduce_sum(float v, float* smem) {
    int tid = threadIdx.x;
    int lane = tid & (WARP_SIZE - 1);
    int warp = tid >> 6;
    v = warp_reduce_sum<BLOCK>(v);
    if (BLOCK > WARP_SIZE) {
        if (lane == 0) smem[warp] = v;
        __syncthreads();
        constexpr int NWARP = BLOCK >> 6;
        v = (tid < NWARP) ? smem[tid] : 0.0f;
        if (tid < WARP_SIZE) v = warp_reduce_sum<BLOCK>(v);
        __syncthreads();
    }
    return v;
}

// One block per row group; handles `rowsPerBlock` rows sequentially? No —
// one block handles ONE row at a time, iterating over cols in a grid-stride
// fashion, then moves to the next row in its assigned stride of rows.
// For cols <= BLOCK a single iteration suffices and the row loop is the
// grid-stride over rows.

// Pass A: row max of relu(x)
template<int BLOCK>
__global__ void relu_max_kernel(float* gmax, const float* x, int rows, int cols) {
    extern __shared__ float smem[];
    int row = blockIdx.x;
    const float* xr = x + (int64_t)row * cols;
    float m = -INFINITY;
    for (int i = threadIdx.x; i < cols; i += BLOCK) {
        float v = xr[i];
        v = fmaxf(v, 0.0f);
        m = fmaxf(m, v);
    }
    m = block_reduce_max<BLOCK>(m, smem);
    if (threadIdx.x == 0) gmax[row] = m;
    (void)rows;
}

// Pass B: exp(relu(x)-m) sum, then second pass to scale.
// We fuse into two phases inside one kernel launch using a shared-memory
// buffer for the exponentials when they fit, otherwise a global scratch.
template<int BLOCK>
__global__ void relu_softmax_kernel(float* out, const float* x, const float* gmax, int rows, int cols, float* scratch) {
    extern __shared__ float smem[];
    int row = blockIdx.x;
    const float* xr = x + (int64_t)row * cols;
    float* or_ = out + (int64_t)row * cols;
    float m = gmax[row];

    // Phase 1: compute exponentials and the partial sums.
    // Use registers for the case cols <= BLOCK (fits in one iteration).
    float acc = 0.0f;
    if (cols <= BLOCK) {
        // Each thread holds at most 1 element (guarded).
        float v = -INFINITY;
        if (threadIdx.x < cols) {
            v = xr[threadIdx.x];
            v = fmaxf(v, 0.0f);
            v = expf(v - m);
            or_[threadIdx.x] = v;
        } else {
            v = 0.0f;
        }
        acc = block_reduce_sum<BLOCK>(v, smem);
        if (threadIdx.x == 0) scratch[row] = acc;
        return;
    }

    // General path: cols > BLOCK. Store exp into out first (unnormalized),
    // reduce sum, then re-read to normalize. Uses out as scratch so no extra
    // global traffic for the exponentials.
    for (int i = threadIdx.x; i < cols; i += BLOCK) {
        float v = xr[i];
        v = fmaxf(v, 0.0f);
        v = expf(v - m);
        or_[i] = v;
        acc += v;
    }
    acc = block_reduce_sum<BLOCK>(acc, smem);
    if (threadIdx.x == 0) scratch[row] = acc;
}

template<int BLOCK>
__global__ void scale_kernel(float* out, const float* ssum, int rows, int cols) {
    int row = blockIdx.x;
    float* or_ = out + (int64_t)row * cols;
    float inv = 1.0f / ssum[row];
    for (int i = threadIdx.x; i < cols; i += BLOCK) {
        or_[i] *= inv;
    }
    (void)rows;
}

// Single-pass variant for the common case cols <= BLOCK: computes max and
// sum with only one read of x and one write of out by caching exp in smem.
template<int BLOCK>
__global__ void relu_softmax_small_kernel(float* out, const float* x, int rows, int cols) {
    extern __shared__ float smem[];
    int row = blockIdx.x;
    const float* xr = x + (int64_t)row * cols;
    float* or_ = out + (int64_t)row * cols;

    float v = 0.0f;
    if (threadIdx.x < cols) {
        v = xr[threadIdx.x];
        v = fmaxf(v, 0.0f);
        smem[threadIdx.x] = v;
    } else {
        smem[threadIdx.x] = -INFINITY;
    }
    __syncthreads();

    float m = block_reduce_max<BLOCK>(smem[threadIdx.x], smem + BLOCK);
    float e = (threadIdx.x < cols) ? expf(smem[threadIdx.x] - m) : 0.0f;
    smem[threadIdx.x] = e;
    __syncthreads();
    float s = block_reduce_sum<BLOCK>(smem[threadIdx.x], smem + BLOCK);

    if (threadIdx.x < cols) {
        or_[threadIdx.x] = e / s;
    }
    (void)rows;
}

extern "C" void relu_softmax_launcher(
    float* output,
    const float* input,
    int rows,
    int cols,
    cudaStream_t stream
) {
    // scratch for per-row max / sum
    size_t scratch_bytes = (size_t)rows * sizeof(float);
    float* scratch = nullptr;
    cudaMallocAsync(&scratch, scratch_bytes, stream);

    if (cols <= 256) {
        // single-pass: one block per row, smem caches the row.
        int smem = 256 * sizeof(float) + 256 * sizeof(float);
        relu_softmax_small_kernel<256><<<rows, 256, smem, stream>>>(
            output, input, rows, cols);
    } else {
        int smem = 512 * sizeof(float);
        relu_max_kernel<512><<<rows, 512, smem, stream>>>(
            scratch, input, rows, cols);
        relu_softmax_kernel<512><<<rows, 512, smem, stream>>>(
            output, input, scratch, rows, cols, scratch);
        scale_kernel<512><<<rows, 512, 0, stream>>>(
            output, scratch, rows, cols);
    }

    cudaFreeAsync(scratch, stream);
}

