// kernels/fused_relu_softmax.cu
// Fused relu + softmax over dim=1 (channels) of a (B, C, H, W) tensor.
//
// Strategy: one block per (batch, spatial-row) of length C.
//  Pass A (same kernel): thread-stride scan of the row computes
//     m = max(relu(x)), s = sum(exp(relu(x) - m))   (online-safe)
//     and stores e = exp(relu(x) - m) into a scratch buffer.
//  Block reduction (warp 64 shuffles + shared memory) produces m and s.
//  Pass B (same kernel, second grid-stride sweep over the row) divides
//     e by s and writes the final output.
//
// Memory traffic: read x once, write tmp once, read tmp once, write out once
// (all coalesced float2) vs. ~6+ separate full-tensor passes in eager.
//
// Note on correctness: softmax is applied AFTER relu, so the row max equals
// max(relu(x)); the subtraction x-m is exact (no catastrophic cancellation).

#include <cuda_runtime.h>

#define FULL_MASK 0xffffffffu

template <int BLOCK_SIZE>
__global__ void fused_relu_softmax_kernel(
    float* __restrict__ out,        // (B, C, H*W)
    const float* __restrict__ x,
    float* __restrict__ tmp,        // exp values, same layout as out
    int batch, int channels, int spatial)
{
    // Row index: blockIdx.x covers (batch * spatial) rows
    const int row = blockIdx.x;
    const int b = row / spatial;
    const int hw = row - b * spatial;
    const int base = (b * channels + 0) * spatial + hw; // x[c] = x[base + c*spatial]

    const int tid = threadIdx.x;
    const int stride = BLOCK_SIZE;

    __shared__ float smem[256];  // up to BLOCK_SIZE=256

    // ---- Pass A: max of relu(x) ----
    float local_max = -INFINITY;
    for (int c = tid; c < channels; c += stride) {
        float v = x[base + c * spatial];
        if (v < 0.0f) v = 0.0f;   // relu
        tmp[base + c * spatial] = v;  // stash relu(x) temporarily
        if (v > local_max) local_max = v;
    }

    // Warp reduction (warp size 64 on C500 / xcore1000)
    unsigned mask = __ballot_sync(FULL_MASK, tid < channels);
    if (tid < 64) {
        for (int off = 32; off > 0; off >>= 1) {
            float other = __shfl_xor_sync(FULL_MASK, local_max, off);
            if (other > local_max) local_max = other;
        }
    }
    // Cross-warp reduction through shared memory
    int warp_id = tid >> 6;          // tid / 64
    int lane = tid & 63;             // tid % 64
    if (lane == 0) smem[warp_id] = local_max;
    __syncthreads();

    const int num_warps = (BLOCK_SIZE + 63) >> 6;
    float row_max = -INFINITY;
    if (warp_id == 0) {
        float v = (lane < num_warps) ? smem[lane] : -INFINITY;
        for (int off = 32; off > 0; off >>= 1) {
            float other = __shfl_xor_sync(FULL_MASK, v, off);
            if (other > v) v = other;
        }
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    row_max = smem[0];

    // If the whole row is <= 0 (after relu), max is 0.
    if (row_max < 0.0f) row_max = 0.0f;

    // ---- Pass A2: exp(x - max) and sum ----
    float local_sum = 0.0f;
    for (int c = tid; c < channels; c += stride) {
        float v = tmp[base + c * spatial];   // relu(x)
        float e = __expf(v - row_max);
        tmp[base + c * spatial] = e;
        local_sum += e;
    }

    if (tid < 64) {
        for (int off = 32; off > 0; off >>= 1)
            local_sum += __shfl_xor_sync(FULL_MASK, local_sum, off);
    }
    if (lane == 0) smem[warp_id] = local_sum;
    __syncthreads();

    float row_sum = 0.0f;
    if (warp_id == 0) {
        float v = (lane < num_warps) ? smem[lane] : 0.0f;
        for (int off = 32; off > 0; off >>= 1)
            v += __shfl_xor_sync(FULL_MASK, v, off);
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    row_sum = smem[0];

    float inv = (row_sum > 0.0f) ? (1.0f / row_sum) : 0.0f;

    // ---- Pass B: normalize ----
    for (int c = tid; c < channels; c += stride) {
        out[base + c * spatial] = tmp[base + c * spatial] * inv;
    }
}

// Vectorized (float2) streaming normalize kernel, used when the row stride
// is even so all loads/stores are 8-byte aligned. One launch covers the
// whole tensor (grid-stride), which is more BW-efficient than one
// block per row for the pure-elementwise divide.
__global__ void normalize_kernel(
    float* __restrict__ out,
    const float* __restrict__ tmp,
    const float* __restrict__ inv,   // per-row reciprocal, size B*H*W
    int batch, int channels, int spatial)
{
    const int row = blockIdx.x;
    const int b = row / spatial;
    const int hw = row - b * spatial;
    const int base = (b * channels) * spatial + hw;
    const float f = inv[row];

    const int tid = blockIdx.y * blockDim.x + threadIdx.x;
    const int stride = gridDim.y * blockDim.x;

    // 8-byte-aligned pairs: channels is even here
    for (int c = 2 * tid; c < channels; c += 2 * stride) {
        int p0 = base + c * spatial;
        int p1 = p0 + spatial;
        float2 e;
        const float2* src = (const float2*)(tmp + p0);
        e = *src;
        float2 o;
        o.x = e.x * f;
        o.y = e.y * f;
        *(float2*)(out + p0) = o;
    }
}

// Computes per-row max and sum of exp(relu(x)-max), stores exps into tmp,
// plus per-row reciprocal sums into invsum. One block per row.
template <int BLOCK_SIZE>
__global__ void scan_kernel(
    float* __restrict__ tmp,         // exp(relu(x)-max), layout (B,C,HW)
    float* __restrict__ invsum,      // 1/sum per row, size B*H*W
    const float* __restrict__ x,
    int batch, int channels, int spatial)
{
    const int row = blockIdx.x;
    const int b = row / spatial;
    const int hw = row - b * spatial;
    const int base = (b * channels) * spatial + hw;

    const int tid = threadIdx.x;
    __shared__ float smem[256];

    // ---- max of relu(x) ----
    float local_max = -INFINITY;
    for (int c = tid; c < channels; c += BLOCK_SIZE) {
        float v = x[base + c * spatial];
        if (v < 0.0f) v = 0.0f;
        if (v > local_max) local_max = v;
    }

    if (tid < 64) {
        for (int off = 32; off > 0; off >>= 1) {
            float other = __shfl_xor_sync(FULL_MASK, local_max, off);
            if (other > local_max) local_max = other;
        }
    }
    int warp_id = tid >> 6;
    int lane = tid & 63;
    if (lane == 0) smem[warp_id] = local_max;
    __syncthreads();

    const int num_warps = (BLOCK_SIZE + 63) >> 6;
    float row_max = -INFINITY;
    if (warp_id == 0) {
        float v = (lane < num_warps) ? smem[lane] : -INFINITY;
        for (int off = 32; off > 0; off >>= 1) {
            float other = __shfl_xor_sync(FULL_MASK, v, off);
            if (other > v) v = other;
        }
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    row_max = smem[0];
    if (row_max < 0.0f) row_max = 0.0f;

    // ---- exp + sum (re-read x; avoids a scratch write/read of relu values) ----
    float local_sum = 0.0f;
    for (int c = tid; c < channels; c += BLOCK_SIZE) {
        float v = x[base + c * spatial];
        if (v < 0.0f) v = 0.0f;
        float e = __expf(v - row_max);
        tmp[base + c * spatial] = e;
        local_sum += e;
    }

    if (tid < 64) {
        for (int off = 32; off > 0; off >>= 1)
            local_sum += __shfl_xor_sync(FULL_MASK, local_sum, off);
    }
    if (lane == 0) smem[warp_id] = local_sum;
    __syncthreads();

    float row_sum = 0.0f;
    if (warp_id == 0) {
        float v = (lane < num_warps) ? smem[lane] : 0.0f;
        for (int off = 32; off > 0; off >>= 1)
            v += __shfl_xor_sync(FULL_MASK, v, off);
        if (lane == 0) smem[0] = v;
    }
    __syncthreads();
    row_sum = smem[0];

    if (tid == 0) invsum[row] = (row_sum > 0.0f) ? (1.0f / row_sum) : 0.0f;
}

extern "C" void fused_relu_softmax_launcher(
    float* output,
    const float* input,
    float* tmp,
    int batch,
    int channels,
    int spatial,
    cudaStream_t stream)
{
    const int rows = batch * spatial;

    if (channels <= 64) {
        // Small rows: single fused 3-phase kernel, one block per row.
        const int block = 64;
        fused_relu_softmax_kernel<64><<<rows, block, 0, stream>>>(
            output, input, tmp, batch, channels, spatial);
    } else {
        // Path A: scan rows -> exps in tmp + per-row reciprocal in invsum.
        // We reuse the tail of `tmp` (same allocation, stride rows) for invsum
        // to avoid allocating a third tensor in the binding.
        float* invsum = tmp + (size_t)batch * channels * spatial;

        const int scan_block = 256;
        scan_kernel<256><<<rows, scan_block, 0, stream>>>(
            tmp, invsum, input, batch, channels, spatial);

        // Path B: vectorized normalize. Use a 2D grid: x = row, y = chunks.
        // C is even for the reference shape (512), so float2 is always aligned.
        if ((channels & 1) == 0) {
            int threads = 256;
            int chunks = (channels / 2 + threads - 1) / threads;
            int gy = chunks;
            if (gy > 64) gy = 64;  // cap grid-y; grid-stride handles the rest
            dim3 grid(rows, gy, 1);
            dim3 block(threads, 1, 1);
            normalize_kernel<<<grid, block, 0, stream>>>(
                output, tmp, invsum, batch, channels, spatial);
        } else {
            const int block = 256;
            fused_relu_softmax_kernel<256><<<rows, block, 0, stream>>>(
                output, input, tmp, batch, channels, spatial);
        }
    }
}

