// kernels/fused_hardswish_binding.cpp
#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Declared in kernels/fused_hardswish.cu
extern "C" void fused_hardswish_relu_scale_launcher(
    const float* __restrict__ input,
    float* __restrict__ output,
    size_t num_elements,
    cudaStream_t stream);

// Fuses: x = F.relu(x + 3) / 6 ; x = hardswish(x)
// hardswish(z) = z * relu6(z + 3) / 6 for z >= 0, and our z = relu(x+3)/6 >= 0.
// Combined: y = r * min(r + 18, 36) / 36, where r = relu(x+3).
// Single memory pass, branch-free arithmetic (no SFU chain).
torch::Tensor fused_hardswish_forward(torch::Tensor input) {
    // Normalize dtype/contiguity: the harness may regenerate inputs with
    // a different seed/dtype than get_inputs() produced.
    if (input.dtype() != torch::kFloat32) {
        input = input.to(torch::kFloat32);
    }
    if (!input.is_contiguous()) {
        input = input.contiguous();
    }

    auto output = torch::empty_like(input);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_hardswish_relu_scale_launcher(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        static_cast<size_t>(input.numel()),
        stream);

    return output;
}

void register_fused_hardswish(pybind11::module& m) {
    m.def("fused_hardswish_forward", &fused_hardswish_forward,
          "Fused relu(x+3)/6 -> hardswish, single pass",
          py::arg("input"));
}

