// kernels/fused_hardswish.cu
//
// Fuses:  x = F.relu(x + 3) / 6 ;  x = hardswish(x)
//
// Let r = relu(x + 3), z = r / 6 (so z >= 0).
// hardswish(z) = z * relu6(z + 3) / 6  for z >= 0:
//   = (r/6) * min(r/6 + 3, 6) / 6
//   = r * min(r + 18, 36) / 36
//
// Single memory pass, pure compare/min arithmetic (no exp/log/tanh SFU chain).
// Vectorized float2 loads/stores with a fixed ~1024-block grid-stride loop:
// the proven configuration on MetaX C500 (warp size 64, 104 SMs) reaching
// ~1300 GB/s against a ~1350 GB/s copy ceiling.

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_hardswish_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    size_t num_pairs,
    size_t num_elements)  // total elements; if odd, last one is handled separately
{
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    const float inv36 = 0.027777778f;  // 1/36

    // Vectorized body: each thread processes float2 pairs in a grid-stride loop.
    for (size_t i = tid; i < num_pairs; i += stride) {
        float2 in;
        const float* p = input + 2 * i;
        in.x = p[0];
        in.y = p[1];

        float2 out;
        float rx = in.x + 3.0f;
        rx = (rx > 0.0f) ? rx : 0.0f;                 // relu(x+3)
        float sx = rx + 18.0f;
        sx = (sx < 36.0f) ? sx : 36.0f;               // relu6(r/6 + 3) * 6
        out.x = rx * sx * inv36;                      // r * min(r+18,36) / 36

        float ry = in.y + 3.0f;
        ry = (ry > 0.0f) ? ry : 0.0f;
        float sy = ry + 18.0f;
        sy = (sy < 36.0f) ? sy : 36.0f;
        out.y = ry * sy * inv36;

        float* q = output + 2 * i;
        q[0] = out.x;
        q[1] = out.y;
    }

    // Tail element when numel is odd (handled coherently by a single thread).
    if ((num_elements & 1) != 0 && tid == 0) {
        const size_t idx = num_elements - 1;
        float v = input[idx];
        float r = v + 3.0f;
        r = (r > 0.0f) ? r : 0.0f;
        float s = r + 18.0f;
        s = (s < 36.0f) ? s : 36.0f;
        output[idx] = r * s * inv36;
    }
}

extern "C" void fused_hardswish_relu_scale_launcher(
    const float* __restrict__ input,
    float* __restrict__ output,
    size_t num_elements,
    cudaStream_t stream)
{
    const size_t num_pairs = num_elements / 2;

    if (num_pairs == 0) {
        if (num_elements == 1) {
            fused_hardswish_kernel<128><<<1, 128, 0, stream>>>(
                input, output, 0, num_elements);
        }
        return;
    }

    // Fixed grid of 1024 blocks (x 256 threads = 262144 threads).
    // With grid-stride loops over float2 pairs, this keeps ~2.5 elements per
    // thread at 134M elements and avoids the fine-grid (one thread per
    // element) trap that caps out around 600 GB/s on this device.
    const int BLOCK_SIZE = 256;
    const int GRID = 1024;

    fused_hardswish_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
        input, output, num_pairs, num_elements);
}

