#include <cuda_runtime.h>

// Fused: x -> (relu(x+3))/6 -> hardswish
// hardswish(y) = y * clamp(y+3, 0, 6) / 6
// Substituting y = relu(x+3)/6:
//   hardswish = (relu(x+3)/6) * clamp(relu(x+3)/6 + 3, 0, 6) / 6
//             = (relu(x+3)/6) * clamp(relu(x+3) + 18, 0, 36) / 36
//             = clamp(relu(x+3) + 18, 0, 36) / 36
// Single branch-free expression: no SFU chains, pure min/max arithmetic.
// Memory traffic: 1 read + 1 write instead of 4 passes.

__device__ __forceinline__ float fused_op(float v) {
    float t = fmaxf(v + 3.0f, 0.0f);         // relu(x+3)
    return fminf(fmaxf(t + 18.0f, 0.0f), 36.0f) * (1.0f / 36.0f);
}

template<int BLOCK_SIZE>
__global__ void fused_hardswish_chain_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Vectorized body: process 2 floats per thread via float2
    const int aligned = (size >> 1) << 1;
    int idx = tid;

    if (aligned >= 2) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        const int n2 = aligned >> 1;
        const int stride2 = stride >> 1;

        for (int i = idx; i < n2; i += stride2) {
            float2 v = in2[i];
            float2 r;
            r.x = fused_op(v.x);
            r.y = fused_op(v.y);
            out2[i] = r;
        }
        idx = tid + n2 * 2;  // not used for tail; handled below
    }

    // Tail: scalar handling of any remaining odd element(s)
    // Threads with (aligned + k) < size handle the tail; use lane 0.. of grid stride
    {
        const int tail_start = aligned;
        const int tail = size - tail_start;
        if (tail > 0) {
            // Use first `tail` threads of the grid (each block covers stride ticks)
            int gtid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
            if (gtid < tail) {
                output[tail_start + gtid] = fused_op(input[tail_start + gtid]);
            }
            // If grid is smaller than tail (won't happen: grid >= 1024 blocks),
            // fall back with a stride loop.
            for (int i = gtid + (BLOCK_SIZE * gridDim.x); i < tail;
                 i += BLOCK_SIZE * gridDim.x) {
                output[tail_start + i] = fused_op(input[tail_start + i]);
            }
        }
    }
}

extern "C" void fused_hardswish_chain_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    // Fixed coarse grid (~1024 blocks) with grid-stride loop:
    // measured far better than one-block-per-element grids on this device.
    const int BLOCK_SIZE = 256;
    const int target_blocks = 1024;

    int blocks = target_blocks;
    const int elems_per_block = BLOCK_SIZE * 2;  // float2 -> 2 elems/thread
    const int max_blocks = (size + elems_per_block - 1) / elems_per_block;
    if (blocks > max_blocks) blocks = max_blocks;
    if (blocks < 1) blocks = 1;

    fused_hardswish_chain_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

