#include <cuda_runtime.h>

// Fused: x = relu(x+3)/6 ; y = hardswish(x) = x * relu6(x+3) / 6
// For x >= 0 (guaranteed by the inner relu): relu6(x+3) = min(x+3, 6).
// So the whole chain is a branch-free expression per element:
//   t = fminf(fmaxf(v, 0.0f) + 3.0f, 6.0f);   // relu6(relu(v+3) + 3) with the
// inner clamp handled once -> equivalently min(max(v,0)+3, 6)
//   out = (max(v,0)/6) * (t/6) ... but we keep the two factors separate so the
//   compiler keeps it branch-free and SFU-light (only multiplies/clamps).
// Actually closed form: let u = max(v,0). out = u * min(u+3,6) * (1/6 * 1/6).
// One fused multiply chain, no exp/log -> fully hidden behind memory traffic.
template<int BLOCK_SIZE>
__global__ void fused_hardswish_chain_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size)
{
    const unsigned long long tid = (unsigned long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride = (unsigned long long)BLOCK_SIZE * gridDim.x;

    const float inv36 = 1.0f / 36.0f;

    // Grid-stride loop with float2 vectorized loads/stores.
    // Fixed ~1024-block grid: avoids the fine-grid (1 thread/element) trap on C500.
    unsigned long long i = tid * 2ULL;
    while (i + 1ULL < size) {
        float2 v = *reinterpret_cast<const float2*>(input + i);
        float2 o;
        float u0 = fmaxf(v.x, 0.0f);
        float u1 = fmaxf(v.y, 0.0f);
        // relu(x+3)/6 then hardswish: u * min(u+3, 6) / 36
        o.x = u0 * fminf(u0 + 3.0f, 6.0f) * inv36;
        o.y = u1 * fminf(u1 + 3.0f, 6.0f) * inv36;
        *reinterpret_cast<float2*>(output + i) = o;
        i += stride * 2ULL;
    }
    // Tail element
    if (i < size) {
        float v = input[i];
        float u = fmaxf(v, 0.0f);
        output[i] = u * fminf(u + 3.0f, 6.0f) * inv36;
    }
}

extern "C" void fused_hardswish_chain_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream)
{
    const int BLOCK_SIZE = 256;
    // Fixed grid of 1024 blocks; grid-stride loop covers any size.
    // 1024 * 256 = 262144 threads, each handling 2 elements per stride step.
    int grid = 1024;
    fused_hardswish_chain_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

