// kernels/stack_maximum_fused.cu
// Fused replacement for:
//   stacked = torch.stack([x1, x2])        -> (2, dim1, dim2)
//   out    = torch.maximum(stacked, x1)    -> broadcast over the stack dim
//
// Semantics: stacked[i] == x1 when i == 0 and x2 when i == 1, and the second
// operand of maximum is always x1. So out.flatten() == max(x1, x2) flat.
// This removes the 2x intermediate write + the re-read of both inputs:
//   eager traffic:  write 2N (stack) + read 2N + write N (maximum) = 5N
//   fused traffic:  read 2N + write N                            = 3N
//
// Memory-bound elementwise op (branch-free fmaxf), so we use a persistent
// grid-stride kernel with float4 vectorized loads/stores. Warp size on the
// MetaX C500 is 64; a fixed 1024-block grid avoids the fine-grid trap
// (768K blocks measured only ~340-640 GB/s here).

#include <cuda_runtime.h>

// One thread per float4 element, grid-stride over the vectorized array.
// Handles the scalar tail (elements not filling a full float4) with a
// separate pass so the vector body has no per-tuple branches.
template<int BLOCK_SIZE, int RESERVE_BYTES>
__global__ void stack_maximum_fused_vec4_kernel(
    float* __restrict__ output,
    const float* __restrict__ x1,
    const float* __restrict__ x2,
    int64_t num_vec4   // number of complete float4 tuples
) {
    const int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;

    const float4* x1v = reinterpret_cast<const float4*>(x1);
    const float4* x2v = reinterpret_cast<const float4*>(x2);
    float4* outv = reinterpret_cast<float4*>(output);

    for (int64_t i = tid; i < num_vec4; i += stride) {
        float4 a = x1v[i];
        float4 b = x2v[i];
        float4 r;
        r.x = fmaxf(a.x, b.x);
        r.y = fmaxf(a.y, b.y);
        r.z = fmaxf(a.z, b.z);
        r.w = fmaxf(a.w, b.w);
        outv[i] = r;
    }
}

// Scalar tail for elements past the last complete float4 tuple.
__global__ void stack_maximum_fused_tail_kernel(
    float* __restrict__ output,
    const float* __restrict__ x1,
    const float* __restrict__ x2,
    int64_t tail_base,  // first element index in the tail
    int64_t size
) {
    const int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;

    for (int64_t i = tail_base + tid; i < size; i += stride) {
        output[i] = fmaxf(x1[i], x2[i]);
    }
}

// C-interface launcher (no PyTorch dependencies).
extern "C" void stack_maximum_fused_launcher(
    float* output,
    const float* x1,
    const float* x2,
    int64_t size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int64_t num_vec4 = size / 4;
    const int64_t tail_start = num_vec4 * 4;

    // Fixed 1024-block grid with 256 threads: 256K threads total, plenty of
    // independent work per SM while keeping launches coarse.
    const int blocks = 1024;
    const int threads = 256;

    if (num_vec4 > 0) {
        // The 8192x8192 case is exactly aligned, so the tail is empty, but
        // guard anyway for arbitrary shapes the harness may produce.
        const bool aligned = ((reinterpret_cast<uintptr_t>(output) |
                               reinterpret_cast<uintptr_t>(x1) |
                               reinterpret_cast<uintptr_t>(x2)) & 0xF) == 0;
        if (aligned) {
            switch (config) {
                case 0:
                    stack_maximum_fused_vec4_kernel<256, 0>
                        <<<blocks, threads, 0, stream>>>(output, x1, x2, num_vec4);
                    break;
                case 1: // smaller block, same grid (occupancy variant)
                    stack_maximum_fused_vec4_kernel<128, 0>
                        <<<blocks, 128, 0, stream>>>(output, x1, x2, num_vec4);
                    break;
                default:
                    stack_maximum_fused_vec4_kernel<256, 0>
                        <<<blocks, threads, 0, stream>>>(output, x1, x2, num_vec4);
            }
        } else {
            // Unaligned base pointers: fall back to scalar for correctness.
            for (int64_t i = 0; i < size; i += 0) { break; }
            tail_start_const_hack:
            stack_maximum_fused_tail_kernel<<<blocks, threads, 0, stream>>>(
                output, x1, x2, (int64_t)0, size);
            goto done;
        }
