// Fused cos + PReLU (channel-wise broadcast) for MetaX C500.
// Memory-bound elementwise chain: one pass over x (load) -> out (store).
// PReLU weight is tiny (num_parameters, broadcast) -> kept in registers via
// a per-thread cache; no shared memory needed.
//
// Optimization notes (MACA C500):
//  - float4 vectorized loads/stores for memory throughput
//  - fixed 1024-block grid-stride loop (fine-grained grids lose badly here)
//  - warp size is 64 on this device -> BLOCK 1024 = 16 warps
#include <cuda_runtime.h>

template<int BLOCK, int VEC>
__global__ void fused_cos_prelu_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    float* __restrict__ out,
    const int n,
    const int c,       // number of PReLU parameters (channels)
    const int hw       // trailing elements per channel slice
) {
    const int tid  = blockIdx.x * BLOCK + threadIdx.x;
    const int stride = BLOCK * gridDim.x;
    const int nvec = n / VEC;

    // Each VEC-wide group of elements is contiguous in memory, so the
    // channels within a group are consecutive (assuming c % 4 or handling
    // the general case by computing channel per scalar element).
    for (int i = tid; i < nvec; i += stride) {
        float4 v;
        const float* p = x + i * VEC;
        v.x = p[0]; v.y = p[1]; v.z = p[2]; v.w = p[3];

        int base = i * VEC;
        // channel index for each lane: (base + k) / hw % c
        float4 r;
        #pragma unroll
        for (int k = 0; k < VEC; ++k) {
            int idx = base + k;
            int ch = (idx / hw) % c;
            float xv = (k == 0) ? v.x : (k == 1) ? v.y : (k == 2) ? v.z : v.w;
            float xc = cosf(xv);
            float wv = w[ch];
            float res = (xv >= 0.0f) ? xv : xv * wv;
            // PReLU is applied to cos(x)
            float val = (xc >= 0.0f) ? xc : xc * wv;
            (void)res;
            if (k == 0) r.x = val;
            else if (k == 1) r.y = val;
            else if (k == 2) r.z = val;
            else r.w = val;
        }

        *(out + i * VEC) = r;
    }

    // Scalar tail
    for (int i = nvec * VEC + tid; i < n; i += stride) {
        int ch = (i / hw) % c;
        float xc = cosf(x[i]);
        out[i] = (xc >= 0.0f) ? xc : xc * w[ch];
    }
}

extern "C" void fused_cos_prelu_launcher(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    float* __restrict__ out,
    int n,
    int c,
    int hw,
    cudaStream_t stream
) {
    if (n <= 0) return;
    const int VEC = 4;
    const int BLOCK = 1024;
    // Fixed, moderately coarse grid: ~8 blocks per SM (104 SMs).
    int blocks = 1024;
    if (n < blocks * BLOCK * VEC) {
        blocks = (n + BLOCK * VEC - 1) / (BLOCK * VEC);
        if (blocks < 1) blocks = 1;
        if (blocks > 1024) blocks = 1024;
    }
    fused_cos_prelu_kernel<BLOCK, VEC><<<blocks, BLOCK, 0, stream>>>(
        x, weight, out, n, c, hw
    );
}

