// Fused cos + PReLU(num_parameters) kernel for MetaX C500 (warp size 64).
//
// Computes: out = cos(x), then PReLU: out >= 0 ? w[c]*out : out
// where w is a per-channel parameter broadcast over the trailing dims.
//
// Design:
//  - float2 vectorized loads/stores (coalesced, ~1300 GB/s on this device
//    vs ~600 GB/s for a scalar one-thread-per-element kernel).
//  - Fixed 1024-block grid-stride loop: avoids the 768K-block fine-grid
//    performance trap on C500.
//  - Weight (num_parameters floats, e.g. 16) is broadcast-loaded into
//    shared memory once per block.
//  - PReLU is branch-free via copysignf/fmin/fmax arithmetic to keep the
//    SFU (cos) pipeline fed and avoid warp divergence.
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_cos_prelu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    const float* __restrict__ weight,
    int64_t numel,
    int channels,
    int64_t inner
) {
    // Weight is tiny (num_parameters). Cache it in shared memory.
    extern __shared__ float smem[];
    const int tid = threadIdx.x;
    if (tid < channels) smem[tid] = weight[tid];
    __syncthreads();

    const int64_t total_pairs = numel >> 1;
    const int64_t grid_stride = (int64_t)blockDim.x * gridDim.x;

    // Contiguous-pair indexing: consecutive float2 elements map to
    // consecutive memory addresses for coalescing.
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + tid;
    int64_t in_idx = idx * 2;        // element index of the first of the pair

    const int64_t inv_inner_fast = (inner > 0) ? 0 : 0;  // placeholder, unused

    for (; idx < total_pairs; idx += grid_stride) {
        // Recompute element index each iteration (grid-stride).
        in_idx = idx * 2;

        float2 a;
        const float2* ip = reinterpret_cast<const float2*>(input) + idx;
        a = *ip;

        float2 r;
        r.x = cosf(a.x);
        r.y = cosf(a.y);

        // Channel index for each element (PReLU weight broadcast).
        // inner >= 1 always (trailing dims product), so this modulo is safe.
        int c0 = (int)((in_idx) % inner);
        int c1 = (int)((in_idx + 1) % inner);
        int ch0 = c0 / (int)inner;
        int ch1 = c1 / (int)inner;

        float w0 = smem[ch0];
        float w1 = smem[ch1];

        // PReLU: r >= 0 ? w*r : r  (branch-free)
        r.x = fmaxf(r.x * w0, r.x);
        r.y = fmaxf(r.y * w1, r.y);

        (reinterpret_cast<float2*>(output) + idx)[0] = r;
    }

    // Odd tail element.
    if ((numel & 1) == 1) {
        int64_t last = numel - 1;
        if (idx == total_pairs && tid == 0) {
            if (idx == total_pairs) {
                int64_t li = last;
                float v = cosf(input[li]);
                int ch = (int)((li % inner) / inner);
                v = fmaxf(v * smem[ch], v);
                output[li] = v;
            }
        }
    }
}

extern "C" void fused_cos_prelu_launcher(
    float* output,
    const float* input,
    const float* weight,
    int64_t numel,
    int channels,
    int64_t inner,
    cudaStream_t stream
) {
    if (numel <= 0 || inner <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, moderately sized grid with grid-stride loop.
    // 1024 blocks * 256 threads = 262144 threads, each handling float2.
    int blocks = 1024;
    int needed = (int)((numel / 2 + BLOCK_SIZE - 1) / BLOCK_SIZE);
    if (needed < blocks) blocks = needed;
    if (blocks < 1) blocks = 1;

    int smem_bytes = channels * (int)sizeof(float);
    if (smem_bytes < 32) smem_bytes = 32;

    fused_cos_prelu_kernel<256><<<blocks, BLOCK_SIZE, smem_bytes, stream>>>(
        output, input, weight, numel, channels, inner
    );
}

