    if (input.dtype() != torch::kFloat32) input = input.to(torch::kFloat32);
    if (weight.dtype() != torch::kFloat32) weight = weight.to(torch::kFloat32);

    // Normalize contiguity for coalesced vectorized access
    if (!input.is_contiguous()) input = input.contiguous();
    if (!weight.is_contiguous()) weight = weight.contiguous();

    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");

