// kernels/fused_abs_prelu.cu
// Fused |x| followed by PReLU:  out = w_c * |x|  (per-channel weight, c = channel index)
// Since |x| >= 0 and PReLU(num_parameters=64, use_relu=False) computes
//   prelu(z) = max(0,z)*w_c + min(0,z)*a_c  with a_c == w_c when use_relu=False
//   prelu(z) = w_c * z  for all z,
// the composition is exactly  w_{c} * |x|  -- a single memory-bound elementwise pass.
//
// Vectorized float2 grid-stride kernel tuned for MetaX C500 (warp 64, 104 SMs).

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_abs_prelu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    const float* __restrict__ weight,
    int size,
    int width,
    int channels)
{
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // Fast path: weight is a single scalar (channels == 1) -> no channel lookup
    if (channels == 1) {
        const float w = weight[0];
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        int n2 = size >> 1;
        for (int i = tid; i < n2; i += stride) {
            float2 v = in2[i];
            v.x = w * fabsf(v.x);
            v.y = w * fabsf(v.y);
            out2[i] = v;
        }
        // Tail element (odd size)
        int tail = n2 * 2 + tid;
        if (tail < size) {
            output[tail] = w * fabsf(input[tail]);
        }
        return;
    }

    // Per-channel path. Channel index of a linear offset o (row-major NCHW):
    //   c = (o / width) % channels
    // Load weights into a register cache: each thread holds a strided subset.
    // With 64 channels and a 256-thread block, each thread caches 1 weight
    // and channel lookups resolve via __ldg (L1-cached, read-only).
    const int log2_width = (width <= 1) ? 0 : (32 - __clz(width - 1));
    const bool pow2_width = (width > 1) && ((width & (width - 1)) == 0);

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);
    int n2 = size >> 1;

    for (int i = tid; i < n2; i += stride) {
        int base = i << 1;
        int row, c0, c1;
        if (pow2_width) {
            row = base >> log2_width;
            c0 = row % channels;
            row = (base + 1) >> log2_width;
            c1 = row % channels;
        } else {
            row = base / width;
            c0 = row % channels;
            row = (base + 1) / width;
            c1 = row % channels;
        }
        float w0 = __ldg(weight + c0);
        float w1 = __ldg(weight + c1);

        float2 v = in2[i];
        v.x = w0 * fabsf(v.x);
        v.y = w1 * fabsf(v.y);
        out2[i] = v;
    }

    // Tail element (odd size)
    int tail = n2 * 2 + tid;
    if (tail < size) {
        int row = pow2_width ? (tail >> log2_width) : (tail / width);
        int c = row % channels;
        output[tail] = __ldg(weight + c) * fabsf(input[tail]);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_abs_prelu_launcher(
    float* output,
    const float* input,
    const float* weight,
    int size,
    int width,
    int channels,
    cudaStream_t stream)
{
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, moderately-sized grid with grid-stride loop: avoids the
    // fine-grained-grid performance trap observed on this device.
    int n2 = (size + 1) >> 1;
    int blocks = (n2 + BLOCK_SIZE - 1) / BLOCK_SIZE;
    const int MAX_BLOCKS = 1024;
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;

    fused_abs_prelu_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, weight, size, width, channels);
}

