// kernels/fused_abs_prelu.cu
// Fused: out = weight[(i / HW) % C] * |x|    (PReLU after abs; x >= 0 everywhere)
//
// Memory-bound elementwise fusion: abs + PReLU becomes one pass.
// float2 vectorized loads with a fixed grid-stride loop (per C500 guidance:
// fine-grained one-thread-per-element grids top out at ~600 GB/s here).
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_abs_prelu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    const float* __restrict__ weight,
    int size,
    int channels,
    int hw
) {
    // Weight table is tiny (channels <= a few hundred): cache in shared mem.
    __shared__ float smem_w[1024];
    int lc = threadIdx.x;
    if (lc < channels && lc < 1024) {
        smem_w[lc] = weight[lc];
    }
    __syncthreads();

    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Vectorized body: consecutive float2 pairs stay within one channel
    // because HW is even for all realistic sizes; guarded tail below.
    const int v_size = size >> 1;
    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    for (int i = tid; i < v_size; i += stride) {
        float2 v = in2[i];
        int c = (i / hw) % channels;   // both lanes share the channel
        float w = smem_w[c];
        v.x = w * fabsf(v.x);
        v.y = w * fabsf(v.y);
        out2[i] = v;
    }

    // Odd tail element (only when size is odd AND this thread owns it)
    if ((size & 1) && tid == 0) {
        int i = size - 1;
        int c = (i / hw) % channels;
        output[i] = smem_w[c] * fabsf(input[i]);
    }
}

extern "C" void fused_abs_prelu_launcher(
    float* output,
    const float* input,
    const float* weight,
    int size,
    int channels,
    int hw,
    int config,
    cudaStream_t stream
) {
    // Fixed ~1024-block grid: keeps waves coarse on the 104-SM C500.
    const int BLOCK = 256;
    int blocks = (size / 2 + BLOCK - 1) / BLOCK;
    if (blocks < 1) blocks = 1;
    if (blocks > 1024) blocks = 1024;

    switch (config) {
        case 0:
            fused_abs_prelu_kernel<256><<<blocks, BLOCK, 0, stream>>>(
                output, input, weight, size, channels, hw);
            break;
        case 1:
            fused_abs_prelu_kernel<128><<<blocks * 2 > 1024 ? 1024 : blocks * 2, 128, 0, stream>>>(
                output, input, weight, size, channels, hw);
            break;
        case 2:
            fused_abs_prelu_kernel<512><<<blocks / 2 < 1 ? 1 : blocks / 2, 512, 0, stream>>>(
                output, input, weight, size, channels, hw);
            break;
        default:
            fused_abs_prelu_kernel<256><<<blocks, BLOCK, 0, stream>>>(
                output, input, weight, size, channels, hw);
    }
}

