// Fused exp + PReLU binding (MetaX C500 / MACA)
#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Launcher implemented in kernels/fused_exp_prelu.cu
extern "C" void fused_exp_prelu_launcher(
    float* output,
    const float* input,
    const float* weight,
    long long num_elements,
    long long channel_stride,   // elements per (batch, channel) block = H*W
    int num_channels,           // C (PReLU weight count)
    float alpha,                // PReLU inplace learnable slope effect (unused if pure PReLU)
    cudaStream_t stream
);

// forward(x, weight): x is any shape [N, C, ...] (C = weight.numel()), contiguous.
// PReLU applied per-channel: out = max(0, exp(x)) + w[c] * min(0, exp(x))
torch::Tensor fused_exp_prelu_forward(torch::Tensor x, torch::Tensor weight) {
    // Normalize dtype/contiguity: the harness regenerates inputs with its own seed,
    // so what arrives here may not match get_inputs() exactly.
    if (!x.is_cuda()) {
        x = x.cuda();
    }
    if (x.dtype() != torch::kFloat32) {
        x = x.to(torch::kFloat32);
    }
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }
    if (!weight.is_cuda()) {
        weight = weight.cuda();
    }
    if (weight.dtype() != torch::kFloat32) {
        weight = weight.to(torch::kFloat32);
    }
    if (!weight.is_contiguous()) {
        weight = weight.contiguous();
    }

    const long long numel = x.numel();
    auto output = torch::empty_like(x);

    // PReLU broadcasts weight over the trailing dims of x: x is [N, C, ...].
    int num_channels = 1;
    if (weight.numel() == 1) {
        num_channels = 1;                      // num_parameters=1 -> shared slope
    } else {
        num_channels = (int)weight.numel();
    }

    long long channel_stride = 1;
    if (num_channels > 1) {
        // Product of all dims after the channel dim: numel / (N * C)
        long long outer = numel / num_channels;        // N broadcast + trailing? no: N*C groups
        // trailing volume = numel / (N * C); but we don't know N separately.
        // For [512,16,128,128]: numel/(512*16) = 16384. Use x.sizes() directly.
        channel_stride = 1;
        for (int d = (int)x.dim() - 1; d >= 1; --d) {
            channel_stride *= x.size(d);
        }
    }

    // Weight is tiny (<= 16 floats); keep it resident for broadcast.
    const float* wptr = weight.data_ptr<float>();
    (void)outer_unused_helper(numel, num_channels);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    fused_exp_prelu_launcher(
        output.data_ptr<float>(),
        x.data_ptr<float>(),
        wptr,
        numel,
        channel_stride,
        num_channels,
        0.0f,
        stream
    );

    return output;
}

static inline long long outer_unused_helper(long long numel, int nc) {
    return numel / (nc > 0 ? nc : 1);
}

void register_fused_exp_prelu(pybind11::module& m) {
    m.def("fused_exp_prelu_forward", &fused_exp_prelu_forward,
          "Fused exp + PReLU (per-channel) forward",
          py::arg("x"),
          py::arg("weight"));
}

REGISTER_BINDING(fused_exp_prelu, register_fused_exp_prelu);

