    if (input.dtype() != torch::kFloat32) input = input.to(torch::kFloat32);
    if (!input.is_contiguous()) input = input.contiguous();
    if (prelu_weight.dtype() != torch::kFloat32) prelu_weight = prelu_weight.to(torch::kFloat32);
    if (!prelu_weight.is_contiguous()) prelu_weight = prelu_weight.contiguous();

