#include <cuda_runtime.h>

// Fused |x| -> LogSoftmax(last dim).
//
// Numerical restatement: log(softmax) = (v - m) - log(sum(exp(v - m))),
// where v = |x| and m = max(v). The max-subtraction is free here (it cancels
// in the normalization), so no division is needed at all -- only exp, a block
// sum, and a log.
//
// One block handles ROWS_PER_BLOCK rows. Rows are independent, so blocks
// never need to synchronize with each other; a fixed grid of ~2048 blocks
// grid-strides over the row set (avoids the fine-grid trap on C500).
//
// Each row of 512 floats is processed by one warp (64 threads, 8 elems each)
// using float4 loads. A second row is interleaved per block for ILP.

template<int BLOCK_SIZE, int ROWS_PER_BLOCK>
__global__ void fused_abs_logsoftmax_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_rows,
    int row_len)
{
    // Shared memory: ROWS_PER_BLOCK rows of partial reductions, 2 stages
    // (max stage + sum stage). Dynamic shared memory sized at launch as
    // ROWS_PER_BLOCK * 2 * BLOCK_SIZE * sizeof(float).
    extern __shared__ float smem[];
    const int warp = blockIdx.x * ROWS_PER_BLOCK + (threadIdx.y * 2);
    const int tid = threadIdx.y * blockDim.x + threadIdx.x;

    // Layout: stage[color][row_slot][BLOCK_SIZE]
    // color 0 = max stage, color 1 = sum stage.
    const int sz = BLOCK_SIZE;

    #pragma unroll
    for (int r = 0; r < 2; ++r) {
        const int row = warp + r;
        if (row >= batch_rows) break;

        const float4* in4 = (const float4*)(input + (size_t)row * row_len);
        float4* out4 = (float4*)(output + (size_t)row * row_len);
        const int n4 = row_len >> 2;   // float4 count

        // ---- Stage 1: max of |x| ----
        float local_max = -INFINITY;
        const int lane = threadIdx.x;
        if (lane < n4) {
            float4 v = in4[lane];
            float a = fmaxf(fabsf(v.x), fabsf(v.y));
            float b = fmaxf(fabsf(v.z), fabsf(v.w));
            local_max = fmaxf(a, b);
        }
        // Warp reduction (warp size 64)
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 32));
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 16));
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 8));
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 4));
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 2));
        local_max = fmaxf(local_max, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_max, 1));

        float* row_smem = smem + (threadIdx.y * 2 + r) * 2 * sz + 0 * sz;
        row_smem[tid] = local_max;
        __syncthreads();

        // Cross-warp reduction in shared memory
        if (tid < 32) {
            // gather from warp slots within this row's sub-block
            float m = (tid < (BLOCK_SIZE / 64)) ? row_smem[tid * 64] : -INFINITY;
            m = fmaxf(m, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, m, 16));
            m = fmaxf(m, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, m, 8));
            m = fmaxf(m, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, m, 4));
            m = fmaxf(m, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, m, 2));
            m = fmaxf(m, __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, m, 1));
            if (tid == 0) row_smem[0] = m;
        }
        __syncthreads();
        const float row_max = row_smem[0];

        // ---- Stage 2: sum of exp(|x| - max) ----
        float local_sum = 0.0f;
        if (lane < n4) {
            float4 v = in4[lane];
            local_sum += expf(fabsf(v.x) - row_max);
            local_sum += expf(fabsf(v.y) - row_max);
            local_sum += expf(fabsf(v.z) - row_max);
            local_sum += expf(fabsf(v.w) - row_max);
        }
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 32);
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 16);
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 8);
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 4);
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 2);
        local_sum += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, local_sum, 1);

        float* sum_smem = smem + (threadIdx.y * 2 + r) * 2 * sz + 1 * sz;
        sum_smem[tid] = local_sum;
        __syncthreads();

        if (tid < 32) {
            float s = (tid < (BLOCK_SIZE / 64)) ? sum_smem[tid * 64] : 0.0f;
            s += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, s, 16);
            s += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, s, 8);
            s += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, s, 4);
            s += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, s, 2);
            s += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFULL, s, 1);
            if (tid == 0) sum_smem[0] = s;
        }
        __syncthreads();
        const float row_sum = sum_smem[0];

        const float log_sum = logf(row_sum);

        // ---- Stage 3: write out  |x| - max - log(sum) ----
        if (lane < n4) {
            float4 v = in4[lane];
            float4 o;
            o.x = fabsf(v.x) - row_max - log_sum;
            o.y = fabsf(v.y) - row_max - log_sum;
            o.z = fabsf(v.z) - row_max - log_sum;
            o.w = fabsf(v.w) - row_max - log_sum;
            out4[lane] = o;
        }
        __syncthreads();
    }
}

extern "C" void fused_abs_logsoftmax_launcher(
    float* output,
    const float* input,
    int batch_rows,
    int row_len,
    cudaStream_t stream)
{
    // 256 threads = 4 warps; each block handles ROWS_PER_BLOCK=8 rows
    // (4 warps x 2 rows each). Fixed grid of 2048 blocks grid-strides.
    const int BLOCK_SIZE = 256;
    const int ROWS_PER_BLOCK = 8;
    const int smem = ROWS_PER_BLOCK * 2 * BLOCK_SIZE * sizeof(float); // 16 KB

    int blocks = (batch_rows + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    if (blocks > 2048) blocks = 2048;

    dim3 grid(blocks);
    dim3 block(BLOCK_SIZE / 4, 4);  // 64 threads per warp-ish group (x=64), 4 groups

    fused_abs_logsoftmax_kernel<256, 8><<<grid, dim3(64, 4), smem, stream>>>(
        output, input, batch_rows, row_len);
}

