#include <cuda_runtime.h>

// Fused |x| followed by LogSoftmax along the last dimension.
//
// Layout: input/output are (batch_rows, dim) contiguous, dim = width (512 here).
// One block handles one row; threads cooperate via shared memory.
//
// Restructured to avoid the expf->log dependency chain (which starves the
// scheduler on this device): we compute the max and the sum-of-exp in two
// passes over shared memory (each is a simple max/add reduction), and the
// final pass does y = (v - m) - log(s) where s = sum(exp(v - m)).
// expf and __logf are issued on independent values, giving the scheduler
// real parallel work. dim=512 fits in shared memory (2KB << 64KB).
//
// Vectorized float2 loads where dim is a multiple of 2 (512 is).

#define WARP_SIZE 64

template<int BLOCK_SIZE>
__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = WARP_SIZE / 2; off > 0; off >>= 1) {
        v += __shfl_xor_down_sync(0xffffffffffffffffULL, v, off);
    }
    return v;
}

template<int BLOCK_SIZE>
__device__ __forceinline__ float warp_reduce_max(float v) {
    #pragma unroll
    for (int off = WARP_SIZE / 2; off > 0; off >>= 1) {
        v = fmaxf(v, __shfl_xor_down_sync(0xffffffffffffffffULL, v, off));
    }
    return v;
}

template<int BLOCK_SIZE>
__device__ __forceinline__ float block_reduce_sum(float v, float* smem) {
    // 64KB shared mem; BLOCK_SIZE<=1024. Pad to avoid bank conflicts.
    const int lid = threadIdx.x;
    const int warps = BLOCK_SIZE / WARP_SIZE;
    if (lid < warps) smem[lid] = 0.0f;
    __syncthreads();
    int wid = lid / WARP_SIZE;
    int lane = lid & (WARP_SIZE - 1);
    if (lane == 0) smem[wid] = v;
    __syncthreads();
    v = (lid < warps) ? smem[lid] : 0.0f;
    if (wid == 0) v = warp_reduce_sum<BLOCK_SIZE>(v);
    __syncthreads();
    return v;
}

template<int BLOCK_SIZE>
__device__ __forceinline__ float block_broadcast(float v, float* smem) {
    if (threadIdx.x == 0) smem[0] = v;
    __syncthreads();
    return smem[0];
}

// dim <= 2048: row fully fits in shared memory; registers hold max/sum.
template<int BLOCK_SIZE, int VEC>
__global__ void fused_abs_logsoftmax_small(
    const float* __restrict__ input,
    float* __restrict__ output,
    int dim)
{
    extern __shared__ float smem[];

    input  += (size_t)blockIdx.x * dim;
    output += (size_t)blockIdx.x * dim;

    const int tid = threadIdx.x;
    const int nv   = dim / VEC;
    const int rem  = dim - nv * VEC;

    // Pass 1: load |x| into shared memory, compute local max
    float lmax = -INFINITY;
    if (VEC == 1) {
        for (int i = tid; i < dim; i += BLOCK_SIZE) {
            float v = fabsf(input[i]);
            smem[i] = v;
            lmax = fmaxf(lmax, v);
        }
    } else {
        for (int i = tid; i < nv; i += BLOCK_SIZE) {
            float2 p = *reinterpret_cast<const float2*>(input + i * VEC);
            float a = fabsf(p.x);
            float b = fabsf(p.y);
            smem[i * VEC]     = a;
            smem[i * VEC + 1] = b;
            lmax = fmaxf(lmax, fmaxf(a, b));
        }
        for (int i = nv * VEC + tid; i < dim; i += BLOCK_SIZE) {
            float v = fabsf(input[i]);
            smem[i] = v;
            lmax = fmaxf(lmax, v);
        }
    }
    lmax = block_reduce_max<BLOCK_SIZE>(lmax, smem + dim + 1);
    lmax = block_broadcast<BLOCK_SIZE>(lmax, smem + dim + 1);

    // Pass 2: sum of exp(v - m), over shared memory (fast)
    float lsum = 0.0f;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        lsum += expf(smem[i] - lmax);
    }
    lsum = block_reduce_sum<BLOCK_SIZE>(lsum, smem + dim + 1);
    lsum = block_broadcast<BLOCK_SIZE>(lsum, smem + dim + 1);

    // Pass 3: write y = (v - m) - log(sum)
    const float logsum = __logf(lsum);
    if (VEC == 1) {
        for (int i = tid; i < dim; i += BLOCK_SIZE) {
            output[i] = (smem[i] - lmax) - logsum;
        }
    } else {
        for (int i = tid; i < nv; i += BLOCK_SIZE) {
            float2 o;
            o.x = (smem[i * VEC]     - lmax) - logsum;
            o.y = (smem[i * VEC + 1] - lmax) - logsum;
            *reinterpret_cast<float2*>(output + i * VEC) = o;
        }
        for (int i = nv * VEC + tid; i < dim; i += BLOCK_SIZE) {
            output[i] = (smem[i] - lmax) - logsum;
        }
    }
    (void)rem;
}

// dim > 2048: row doesn't fit comfortably; multi-pass over global memory.
template<int BLOCK_SIZE>
__global__ void fused_abs_logsoftmax_large(
    const float* __restrict__ input,
    float* __restrict__ output,
    int dim)
{
    extern __shared__ float smem[];

    input  += (size_t)blockIdx.x * dim;
    output += (size_t)blockIdx.x * dim;

    const int tid = threadIdx.x;

    // Pass 1: max of |x|
    float lmax = -INFINITY;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        lmax = fmaxf(lmax, fabsf(input[i]));
    }
    lmax = block_reduce_max<BLOCK_SIZE>(lmax, smem);
    lmax = block_broadcast<BLOCK_SIZE>(lmax, smem);

    // Pass 2: sum of exp(|x| - m)
    float lsum = 0.0f;
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        lsum += expf(fabsf(input[i]) - lmax);
    }
    lsum = block_reduce_sum<BLOCK_SIZE>(lsum, smem);
    lsum = block_broadcast<BLOCK_SIZE>(lsum, smem);

    // Pass 3: write
    const float logsum = __logf(lsum);
    for (int i = tid; i < dim; i += BLOCK_SIZE) {
        output[i] = (fabsf(input[i]) - lmax) - logsum;
    }
}

extern "C" void fused_abs_logsoftmax_launcher(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_rows,
    int dim,
    cudaStream_t stream)
{
    if (batch_rows <= 0 || dim <= 0) return;

    if (dim <= 2048) {
        // dim=512 here -> small path (row in shared memory)
        const int threads = 256;
        const int smem = (dim + 1 + 64) * sizeof(float);
        fused_abs_logsoftmax_small<256, 2><<<batch_rows, threads, smem, stream>>>(
            input, output, dim);
    } else {
        const int threads = 512;
        const int smem = 256 * sizeof(float);
        fused_abs_logsoftmax_large<512><<<batch_rows, threads, smem, stream>>>(
            input, output, dim);
    }
}

