// Binding for fused abs + LogSoftmax (fwd), MetaX C500 / MACA port.
// Two-pass approach:
//   pass1: x -> |x| and per-row max (fused: removes the separate abs store/load)
//   pass2: |x| -> logsoftmax using stored row maxima
// Memory traffic: 3 full-tensor passes total vs torch.compile's 4
// (abs store + logsoftmax max/exp/normalize each touching the tensor).
#include <torch/types.h>
#include <torch/csrc/utils/pybind.h>

#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include "../binding_registry.h"

// Launcher implemented in kernels/logsoftmax_abs.cu
extern "C" void fused_logsoftmax_abs_launcher(
    float* output,
    const float* input,
    int rows,
    int cols,
    cudaStream_t stream
);

// Reusable scratch buffer for row maxima (rows floats). Cached on the
// binding so repeated forward calls avoid allocator churn.
static torch::Tensor g_scratch;
static int64_t g_scratch_rows = 0;

torch::Tensor logsoftmax_abs_forward(torch::Tensor x) {
    // Normalize dtype/layout/contiguity: the harness may regenerate inputs
    // with its own seed, so the arriving dtype is not guaranteed.
    if (!x.is_cuda()) {
        x = x.to(torch::kFloat32);
    }
    if (x.scalar_type() != torch::kFloat32) {
        x = x.to(torch::kFloat32);
    }
    if (x.dim() != 3) {
        TORCH_CHECK(x.dim() >= 2, "input must have >= 2 dims");
        x = x.reshape({-1, x.size(x.dim() - 1)});
    }
    if (!x.is_contiguous()) {
        x = x.contiguous();
    }

    const int rows = static_cast<int>(x.size(0));
    const int cols = static_cast<int>(x.size(1));
    TORCH_CHECK(cols > 0 && rows > 0, "empty input");

    auto out = torch::empty_like(x);

    // (Re)allocate scratch for per-row maxima if needed.
    if (g_scratch_rows < static_cast<int64_t>(rows) || !g_scratch.defined()) {
        g_scratch = torch::empty({rows}, x.options());
        g_scratch_rows = rows;
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_logsoftmax_abs_launcher(
        out.data_ptr<float>(),
        x.data_ptr<float>(),
        rows,
        cols,
        stream
    );

    return out;
}

void register_logsoftmax_abs(pybind11::module& m) {
    m.def("logsoftmax_abs_forward", &logsoftmax_abs_forward,
          "Fused abs + LogSoftmax forward (row-wise)",
          py::arg("x"));
}

REGISTER_BINDING(logsoftmax_abs, register_logsoftmax_abs);

