#include <cuda_runtime.h>

// Fused SELU + Tanh: y = tanh(selu(x))
// SELU: 1.0507009873554804934193349852946 * (x if x > 0 else 1.6732632423543772 * (exp(x) - 1))
// Both ops are branch-free, single-SFU; arithmetic hides behind memory traffic.
// float2 vectorized loads + fixed 1024-block grid-stride loop (warp size 64 on C500).

template<int BLOCK_SIZE>
__global__ void fused_selu_tanh_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized element index: this thread handles float2 pairs in a grid-stride loop.
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Scalar upper bound in float2 units.
    int n2 = size >> 1;

    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];

        float2 r;
        r.x = 1.0507009873554804934193349852946f *
              (v.x > 0.0f ? v.x
                          : 1.6732632423543772f * (__expf(v.x) - 1.0f));
        r.y = 1.0507009873554804934193349852946f *
              (v.y > 0.0f ? v.y
                          : 1.6732632423543772f * (__expf(v.y) - 1.0f));

        // tanh via float-precision intrinsic (single SFU op).
        v.x = __tanhf(r.x);
        v.y = __tanhf(r.y);

        out2[i] = v;
    }

    // Tail: odd element count.
    if (tid == 0 && (size & 1) != 0) {
        float v = input[size - 1];
        float r = 1.0507009873554804934193349852946f *
                  (v > 0.0f ? v : 1.6732632423543772f * (__expf(v) - 1.0f));
        output[size - 1] = __tanhf(r);
    }
}

extern "C" void fused_selu_tanh_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;  // 4 warps of 64 threads
    // Fixed 1024-block grid: avoids the fine-grid (1 block per element) trap
    // measured on this device; grid-stride loop covers any size.
    int blocks = 1024;

    fused_selu_tanh_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

