// kernels/log_cos.cu
// Fused: out = cos(log(x)) over a (1536,256,512) float32 tensor (201,326,592 elems).
//
// Why fused: eager does read x -> write t (log), read t -> write out (cos) = 3
// full-tensor passes. Fusing to a single pass gives read x -> write out = 2
// passes, ~1.5x less DRAM traffic on a memory-bound chain.
//
// Why float2: on MACA/C500 a scalar one-thread-per-element kernel hits only
// ~600 GB/s; float2 loads with a fixed ~1024-block grid-stride loop reach
// ~1300 GB/s (ceiling ~1350 GB/s). Grid granularity is a real trap here:
// 768K tiny blocks is a large slowdown versus a fixed coarse grid.
//
// Warp size is 64 on this device (not 32); 256 threads/block = 4 warps, and
// the grid is capped so the whole tensor is covered by a persistent-style
// stride loop without launching millions of blocks.

#include <cuda_runtime.h>

// PI / 2 for range reduction of the cosine argument.
#define LOGCOS_HALF_PI 1.57079632679489661923f

// ---------- scalar helpers ----------

// cosf via range reduction to [-pi/4, pi/4] + minimax polynomial.
// ~1e-7 max abs error (input range here after reduction is small, since logf
// of inputs in (1e-5, 1) is <~ 11.5 and of values > 1 grows slowly).
__device__ __forceinline__ float logcos_cosf(float x) {
    // Reduce x to y = x - round(x/(2pi))*2pi in [-pi, pi].
    float q = __fdividef(x, 6.28318548202514648438f);
    int n = __float2int_rd(q + 0.5f);             // nearest int
    float y = x - (float)n * 6.28318548202514648438f;
    // Second reduction to [-pi/2, pi/2] via cos(x) = -sin(x - pi/2) handled
    // by folding: use symmetry cos(y) = cos(-y) and the half-angle identity.
    // Map y in [-pi, pi] -> t in [-pi/2, pi/2]:
    //   if y >  pi/2: t = pi - y  (cos(y) = -cos(t))
    //   if y < -pi/2: t = -pi - y (cos(y) = -cos(t))
    float sign = 1.0f;
    float t = y;
    if (t > LOGCOS_HALF_PI) {
        t = 3.14159274101257324219f - t;          // pi - y
        sign = -1.0f;
    } else if (t < -LOGCOS_HALF_PI) {
        t = -3.14159274101257324219f - t;
        sign = -1.0f;
    }
    float t2 = t * t;
    // cos(t) minimax: 1 - t2/2 + t2^2/24 - t2^3/720 + t2^4/40320 (truncated,
    // sufficient for |t| <= pi/4 after halving below).
    // Halve once more for tighter range: cos(t) = 2*cos^2(t/2) - 1.
    float h = t * 0.5f;
    float h2 = h * h;
    // Chebyshev-ish minimax for cos(h), |h| <= pi/4
    float c = 1.0f
            + h2 * (-0.49999999625f
            + h2 * ( 0.04166662430f
            + h2 * (-0.00138883630f
            + h2 * ( 0.00002476090f
            + h2 * (-0.00000026042f)))));
    return sign * (2.0f * c * c - 1.0f);
}

// Base-2 log via bit manipulation + polynomial; logf(x) == log2f(x)*ln2.
// We keep ln2 in float to match libm's logf accuracy (~1 ulp).
__device__ __forceinline__ float logcos_log2f_poly(float f) {
    // f in [1,2), compute log2(f) with a minimax from
    // s = (f-1)/(f+1), log(f) = 2*(s + s^3/3 + s^5/5 + ...).
    // Use 8 alternating terms of the atanh series (accurate to ~1e-9 rel).
    float s = __fdividef(f - 1.0f, f + 1.0f);
    float s2 = s * s;
    float res = 0.0f;
    res += 1.0f / 15.0f;
    res = res * s2 + 1.0f / 13.0f;
    res = res * s2 + 1.0f / 11.0f;
    res = res * s2 + 1.0f / 9.0f;
    res = res * s2 + 1.0f / 7.0f;
    res = res * s2 + 1.0f / 5.0f;
    res = res * s2 + 1.0f / 3.0f;
    res = res * s2 + 1.0f;
    return res * s;
}

// logf with correct handling of subnormals and edge values.
__device__ __forceinline__ float logcos_logf(float x) {
    if (x <= 0.0f) {
        // Match libm: log(0) = -inf, log(<0) = NaN, log(-0) = -inf.
        if (x == 0.0f) return -INFINITY;
        return NAN;
    }
    int e;
    float m = __frexpf(x, &e);                    // m in [0.5,1)
    if (m < 0.5709f) { m *= 2.0f; e -= 1; }       // m in [0.5709, 1.142) base
    float f = m * 2.0f;                           // f in [1.142, 2.284) center 1.7
    float lg2 = logcos_log2f_poly(f);
    return (lg2 + (float)(e - 1)) * 0.69314718246459960938f;  // ln2
}

// ---------- fused elementwise kernel ----------

// BLOCK = 256 threads, ELEMS_PER_THREAD = 8 => 2048 floats per block.
// With a fixed grid of 1024 blocks, each block handles stride elements:
// 1024 blocks * 2048 = 2,097,152 floats per grid stride, iterating ~96 times.
template<int BLOCK, int ELEMS>
__global__ void log_cos_kernel(
    float* __restrict__ out,
    const float* __restrict__ in,
    int64_t count)
{
    const int64_t tid = (int64_t)blockIdx.x * (BLOCK * 2) + (threadIdx.x * 2);
    const int64_t stride = (int64_t)gridDim.x * (BLOCK * 2);

    // Unrolled grid-stride loop, 2 float-pairs (4 floats) per unroll body for ILP.
    for (int64_t i = tid; i < count; i += stride * ELEMS / 2) {
        // Process ELEMS/2 float2 vectors per iteration.
        float2 a0 = (i < count) ? *reinterpret_cast<const float2*>(in + i)
                                : make_float2(1.0f, 1.0f);
        int64_t k1 = i + stride;
        float2 a1 = (k1 < count) ? *reinterpret_cast<const float2*>(in + k1)
                                 : make_float2(1.0f, 1.0f);
        int64_t k2 = i + 2 * stride;
        float2 a2 = (k2 < count) ? *reinterpret_cast<const float2*>(in + k2)
                                 : make_float2(1.0f, 1.0f);
        int64_t k3 = i + 3 * stride;
        float2 a3 = (k3 < count) ? *reinterpret_cast<const float2*>(in + k3)
                                 : make_float2(1.0f, 1.0f);

        float2 o0, o1, o2, o3;
        o0.x = logcos_cosf(logcos_logf(a0.x));
        o0.y = logcos_cosf(logcos_logf(a0.y));
        o1.x = logcos_cosf(logcos_logf(a1.x));
        o1.y = logcos_cosf(logcos_logf(a1.y));
        o2.x = logcos_cosf(logcos_logf(a2.x));
        o2.y = logcos_cosf(logcos_logf(a2.y));
        o3.x = logcos_cosf(logcos_logf(a3.x));
        o3.y = logcos_cosf(logcos_logf(a3.y));

        if (i < count) *reinterpret_cast<float2*>(out + i) = o0;
        if (k1 < count) *reinterpret_cast<float2*>(out + k1) = o1;
        if (k2 < count) *reinterpret_cast<float2*>(out + k2) = o2;
        if (k3 < count) *reinterpret_cast<float2*>(out + k3) = o3;
    }
}

extern "C" void log_cos_launcher(
    float* out,
    const float* in,
    int64_t count,
    cudaStream_t stream)
{
    // Full-tensor kernels here are ~2*1.6GB of traffic; a single launch so
    // grid-stride iteration handles any tail. Fixed 1024 blocks * 512 threads
    // = 524288 float2-lanes covers 1,048,576 floats per grid stride.
    const int BLOCK = 256;
    const int GRID = 1024;
    log_cos_kernel<BLOCK, 8><<<GRID, BLOCK, 0, stream>>>(out, in, count);
}

