#include <cuda_runtime.h>
#include <math.h>

// Fused: out = cos(log(x))
// Single-pass, memory-bound elementwise fusion. Uses float2 vectorized loads
// with a fixed grid-stride loop (1024 blocks) to keep the SMs saturated.
// Rebalanced SFU usage (cos applied to log-result) hides the cos latency
// behind the log/comparison chain.
template<int BLOCK_SIZE>
__global__ void fused_log_cos_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size)
{
    // Base index in float2 elements.
    int tid2 = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int stride2 = BLOCK_SIZE * gridDim.x;
    int size2 = size >> 1;

