        float2 out;
        float lx = logf(fmaxf(in.x, 1e-20f));
        float ly = logf(fmaxf(in.y, 1e-20f));
        out.x = cosf(lx);
        out.y = cosf(ly);
        *reinterpret_cast<float2*>(output + 2 * i) = out;
    }

    // Odd tail element.
    if ((size & 1) != 0) {
        int i = size - 1;
        if (threadIdx.x == 0 && blockIdx.x == 0) {
            float v = input[i];
            output[i] = cosf(logf(fmaxf(v, 1e-20f)));
        }
    }
