// kernels/logcos.cu  -- fused log(x) -> cos(log(x)), float2 vectorized
// Memory-bound elementwise chain on MetaX C500 (warp 64, 104 SMs).
// Two SFU ops but no dependency on the *same* value chain that starves the
// scheduler: log and cos are independent per-element ops here, and each
// thread processes 2 elements to expose ILP across them.
#include <cuda_runtime.h>

__device__ __forceinline__ float fused_op(float v) {
    return cosf(logf(v));
}

template <int BLOCK>
__global__ void logcos_scalar(const float* __restrict__ in, float* __restrict__ out, int n) {
    int tid = blockIdx.x * BLOCK + threadIdx.x;
    if (tid < n) out[tid] = fused_op(in[tid]);
}

// float2 path: 2 elements per thread, grid-stride loop, fixed 1024-block grid.
__global__ void logcos_vec2(const float* __restrict__ in, float* __restrict__ out, int n) {
    const float2* in2 = reinterpret_cast<const float2*>(in);
    float2* out2 = reinterpret_cast<float2*>(out);
    int m = n >> 1;
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < m; i += blockDim.x * gridDim.x) {
        float2 v = in2[i];
        float2 r;
        r.x = fused_op(v.x);
        r.y = fused_op(v.y);
        out2[i] = r;
    }
}

extern "C" void logcos_launcher(const float* __restrict__ in, float* __restrict__ out, int n, cudaStream_t stream) {
    if (n <= 0) return;
    // Prefer the vectorized path when the tensor is float2-aligned (numel even
    // and base pointer 8-byte aligned). Empty tensors from torch are
    // 256-byte aligned, so alignment is effectively guaranteed.
    if (((uintptr_t)in & 7u) == 0 && ((uintptr_t)out & 7u) == 0 && (n & 1) == 0) {
        const int BLOCK = 256;
        int blocks = 1024;
        logcos_vec2<<<blocks, BLOCK, 0, stream>>>(in, out, n);
    } else {
        const int BLOCK = 256;
        int blocks = (n + BLOCK - 1) / BLOCK;
        logcos_scalar<BLOCK><<<blocks, BLOCK, 0, stream>>>(in, out, n);
    }
}

