// kernels/fused_elu_relu.cu
// Single-pass fusion of ELU followed by ReLU on a float32 tensor.
//
// Math (exact, no algebraic collapsing):
//   e = (x > 0) ? x : alpha * (expf(x) - 1)
//   out = fmaxf(e, 0.0f)
// with alpha = 1.0 (PyTorch ELU default).
//
// Design notes for MetaX C500:
//  - Memory-bound: one read of x + one write per element instead of the
//    2-read/2-write of two separate kernels.
//  - float2 vectorized loads/stores with a FIXED 1024-block grid-stride loop:
//    a one-thread-per-element grid reached only ~0.6 TB/s here, while this
//    shape reached ~1.3 TB/s against a ~1.35 TB/s ceiling.
//  - 256 threads per block, warp size 64 -> 4 warps per block.
#include <cuda_runtime.h>

__device__ __forceinline__ float elu_relu_scalar(float x) {
    // expf is a single SFU transaction here; no chained SFU dependency.
    float e = (x > 0.0f) ? x : (expf(x) - 1.0f);
    return fmaxf(e, 0.0f);
}

template<int BLOCK_SIZE>
__global__ void fused_elu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    // float2 vectorized processing: each thread handles 2 floats per step.
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    const long long n2 = size >> 1;          // number of float2 pairs
    const long long tid = (long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * gridDim.x;

    // Vector body
    for (long long i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = elu_relu_scalar(v.x);
        r.y = elu_relu_scalar(v.y);
        out2[i] = r;
    }

    // Tail element (odd element count) - handled by one thread, cheap.
    if ((size & 1LL) != 0LL) {
        if (tid == 0) {
            long long last = size - 1;
            output[last] = elu_relu_scalar(input[last]);
        }
    }
}

extern "C" void fused_elu_relu_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed 1024-block grid: keeps the grid coarse (avoids the
    // one-thread-per-element fine-grid trap) and covers up to
    // 1024*256*2 = 512K elements per stride; grid-stride handles the rest.
    const int GRID = 1024;

    fused_elu_relu_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

