#include <cuda_runtime.h>

// Fused ELU + ReLU single-pass kernel.
//
// relu(elu(x)) = relu(x) for x > 0 (since elu(x) = x there)
//              = relu(alpha*(exp(x)-1)) = 0 for x <= 0 (exp(x)-1 <= 0)
// So the result is simply max(x, 0) -> no expf SFU chain, one memory pass.
//
// Vectorized float2 loads with a fixed-size grid-stride loop: enough blocks
// to fill the 104 SMs several times over, each block processing a contiguous
// tile so all loads/stores coalesce.

__global__ void fused_elu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int BLOCK = 256;
    int tid = blockIdx.x * BLOCK + threadIdx.x;
    int stride = gridDim.x * BLOCK;

    // Base element index this thread handles (pairs of floats)
    int base = tid * 2;
    int pair_stride = stride * 2;

    for (int i = base; i < size; i += pair_stride) {
        float2 v;
        v.x = 0.0f; v.y = 0.0f;
        if (i + 1 < size) {
            v = *reinterpret_cast<const float2*>(input + i);
            v.x = fmaxf(v.x, 0.0f);
            v.y = fmaxf(v.y, 0.0f);
            *reinterpret_cast<float2*>(output + i) = v;
        } else if (i < size) {
            float a = input[i];
            output[i] = fmaxf(a, 0.0f);
        }
    }
}

extern "C" void fused_elu_relu_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK = 256;
    const int GRID = 1024;
    fused_elu_relu_kernel<<<GRID, BLOCK, 0, stream>>>(output, input, size);
}

