#include <cuda_runtime.h>

// Fused ELU + ReLU: out = relu(elu(x))
//   elu(x) = x if x > 0 else alpha*(exp(x)-1), alpha=1.0
//   relu(y) = max(y, 0)
// Combined: x > 0 -> x ; x <= 0 -> max(exp(x)-1, 0) = 0 (since exp(x)-1 <= 0)
// Branch-free form below is numerically identical to the sequential pair.
template<int BLOCK_SIZE>
__global__ void fused_elu_relu_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vectorized view: process 2 floats per thread per iteration.
    int n2 = size >> 1;
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int stride = BLOCK_SIZE * gridDim.x;

    // Grid-stride loop over float2 pairs
    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        // Branch-free ELU+ReLU using SAT min/max semantics
        r.x = fmaxf(v.x, fmaxf(v.x * __expf(-fmaxf(-v.x, 0.0f)) - 1.0f, 0.0f));
        r.y = fmaxf(v.y, fmaxf(v.y * __expf(-fmaxf(-v.y, 0.0f)) - 1.0f, 0.0f));
        out2[i] = r;
    }

    // Handle trailing odd element
    if ((size & 1) != 0) {
        int i = tid;
        if (i < size) {
            float v = input[i];
            output[i] = fmaxf(v, fmaxf(v * __expf(-fmaxf(-v, 0.0f)) - 1.0f, 0.0f));
        }
    }
}

extern "C" void fused_elu_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    const int threads = 256;
    // Fixed block count sized to fill the 104 SMs; grid-stride handles the rest.
    int blocks = 1024;
    if (blocks * threads > (size + 1) / 2) {
        blocks = ((size + 1) / 2 + threads - 1) / threads;
        if (blocks < 1) blocks = 1;
    }
    fused_elu_relu_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, size);
}

