// kernels/fused_gelu_trunc.cu
// Fused elementwise: GELU (tanh approximation, matching torch's gelu 'none'
// approximate mode) followed by truncation toward zero.
//
// One pass over memory instead of two full-tensor round trips.
// Vectorized with float2 loads on a fixed-size grid-stride loop (warp size 64
// on MetaX C500, 104 SMs).

#include <cuda_runtime.h>
#include <math.h>

// tanh-form GELU constants (matches torch.nn.functional.gelu approximate='tanh')
__constant__ float kCbrt2OverPi = 0.7978845608028654f;  // sqrt(2/pi)
__constant__ float kConst = 0.044715f;

template<int BLOCK_SIZE, int VEC>
__global__ void fused_gelu_trunc_impl(float* __restrict__ output,
                                      const float* __restrict__ input,
                                      int size) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    if (VEC == 2) {
        int n2 = size >> 1;  // number of float2 pairs
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);

        for (int i = tid; i < n2; i += stride) {
            float2 v = in2[i];
            float2 r;

            #pragma unroll
            for (int c = 0; c < 2; ++c) {
                float x = (c == 0) ? v.x : v.y;
                float x2 = x * x;
                float inner = kCbrt2OverPi * x * (1.0f + kConst * x2);
                // tanh via the library function; SFU latency is hidden behind
                // the second element and the memory-bound loop.
                float t = tanhf(inner);
                float g = 0.5f * x * (1.0f + t);
                // trunc: drop fractional part, toward zero.
                r.x = (c == 0) ? truncf(g) : r.x;
                if (c == 1) r.y = truncf(g);
            }

            out2[i] = r;
        }

        // Handle odd tail element
        int tail = n2 * 2;
        if (tid == 0 && (size & 1)) {
            float x = input[tail];
            float x2 = x * x;
            float inner = kCbrt2OverPi * x * (1.0f + kConst * x2);
            float g = 0.5f * x * (1.0f + tanhf(inner));
            output[tail] = truncf(g);
        }
    } else {
        // Scalar fallback path (config 1)
        for (int i = tid; i < size; i += stride) {
            float x = input[i];
            float x2 = x * x;
            float inner = kCbrt2OverPi * x * (1.0f + kConst * x2);
            float g = 0.5f * x * (1.0f + tanhf(inner));
            output[i] = truncf(g);
        }
    }
}

extern "C" void fused_gelu_trunc_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid of ~1024 blocks regardless of size: avoids the fine-grid
    // (one block per tiny tile) trap measured on this device.
    const int TARGET_GRID = 1024;

    // Base thread count: 4 warps (256 threads) per block.
    int block_size = 256;

    // Pick grid so each block handles roughly (size / TARGET_GRID) elements,
    // capped for small inputs.
    int pairs = (size + 1) / 2;
    int grid = (pairs + block_size - 1) / block_size;
    if (grid > TARGET_GRID) grid = TARGET_GRID;
    if (grid < 1) grid = 1;

    if (config == 0) {
        fused_gelu_trunc_impl<256, 2><<<grid, block_size, 0, stream>>>(
            output, input, size);
    } else {
        fused_gelu_trunc_impl<256, 1><<<grid, block_size, 0, stream>>>(
            output, input, size);
    }
}

