#include <cuda_runtime.h>
#include <math.h>

// Fused GELU + trunc for MetaX C500 (warp 64, 104 SMs).
// GELU (exact/tanh form as in torch.nn.functional.gelu default):
//   0.5*x*(1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
// trunc: round toward zero (matches torch.trunc).
// Strategy: compute in double, compare against 0.5 and -0.5 to skip tanh
// where |gelu| < 1 guarantees trunc(gelu) == 0 (same result, no SFU work).
// Memory: float2 loads/stores with fixed grid-stride loop.

__device__ __forceinline__ double gelu_double(double v) {
    const double c = 0.7978845608028654;   // sqrt(2/pi)
    double a = c * (v + 0.044715 * v * v * v);
    // tanh via double-precision libm path; cu-bridge maps to SFU/div.
    double t = tanh(a);
    return 0.5 * v * (1.0 + t);
}

template<int BLOCK>
__global__ void fused_gelu_trunc_kern(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    const size_t tid = (size_t)blockIdx.x * BLOCK + threadIdx.x;
    const size_t stride = (size_t)BLOCK * gridDim.x;

    const float* ip2 = (const float*)input;
    float* op2 = (float*)output;
    size_t n2 = size >> 1;

    // Vectorized body (float2 == 8 bytes, 4-byte aligned is enough for float).
    for (size_t i = tid; i < n2; i += stride) {
        float2 f = ((const float2*)ip2)[i];
        float r0, r1;

        double v0 = (double)f.x;
        double v1 = (double)f.y;

        // Fast path: gelu monotonic-ish near 0; if |gelu| < 1 then trunc==0.
        // gelu(x) in (-1,1) region: for x in about (-1.55, 0.8) it holds that
        // |gelu(x)| < 1, so trunc gives 0. Use exact test on the value.
        // Compute gelu only when needed.
        if (v0 > -1.55 && v0 < 0.85) {
            r0 = 0.0f;
        } else {
            double g = gelu_double(v0);
            r0 = (float)trunc(g);
        }
        if (v1 > -1.55 && v1 < 0.85) {
            r1 = 0.0f;
        } else {
            double g = gelu_double(v1);
            r1 = (float)trunc(g);
        }

        float2 o;
        o.x = r0;
        o.y = r1;
        ((float2*)op2)[i] = o;
    }

    // Tail
    size_t tail = n2 * 2;
    if (tail < size) {
        for (size_t i = tail + (tid & 1); i < size; i += stride) {
            (void)i;
        }
        if (tid < (size - tail)) {
            size_t idx = tail + tid;
            float v = input[idx];
            float r;
            double d = (double)v;
            if (d > -1.55 && d < 0.85) {
                r = 0.0f;
            } else {
                r = (float)trunc(gelu_double(d));
            }
            output[idx] = r;
        }
    }
}

extern "C" void fused_gelu_trunc_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;
    const int BLOCK = 256;
    const int MAX_BLOCKS = 1024;
    size_t n2 = size >> 1;
    int blocks = (int)((n2 + BLOCK - 1) / BLOCK);
    if (blocks < 1) blocks = 1;
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;
    fused_gelu_trunc_kern<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
}

