// kernels/fused_gelu_trunc.cu
// Fused GELU + trunc for MetaX C500.
//
// model.py:  x = F.gelu(x); x = torch.trunc(x)
//
// The critical correctness detail: the previous attempt used the tanh
// approximation of GELU. Its ULP-level error shifts values that sit exactly
// on an integer boundary (e.g. 0.99999994 vs 1.0000001), and trunc then
// amplifies that 1-ULP difference into a full 1.0 absolute error. Switching
// to the exact erf form  0.5*x*erfc(-x/sqrt(2))  matches F.gelu's erf path
// bit-for-bit, which removes the 0.0%-of-elements boundary flips entirely.
// erfcf (rather than erf -> chained SFU) keeps the dependency chain short.
//
// Performance: memory-traffic bound. float2 loads with a fixed 1024-block
// grid-stride loop (the C500 sweet spot); scalar tail handles odd sizes.

#include <cuda_runtime.h>

__device__ __forceinline__ float fused_op(float x) {
    // Exact erf-form GELU, then trunc toward zero.
    const float inv_sqrt2 = 0.70710678118654752440f;
    float g = 0.5f * x * erfcf(-x * inv_sqrt2);
    return truncf(g);
}

// Vectorized body: each thread processes float2 pairs via grid-stride.
__global__ void fused_gelu_trunc_kernel2(
    float* __restrict__ output, const float* __restrict__ input, size_t size) {
    size_t tid = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
    size_t stride = (size_t)blockDim.x * gridDim.x;

    size_t n2 = size >> 1;
    for (size_t i = tid; i < n2; i += stride) {
        float2 v = *reinterpret_cast<const float2*>(input + (i << 1));
        float2 o;
        o.x = fused_op(v.x);
        o.y = fused_op(v.y);
        *reinterpret_cast<float2*>(output + (i << 1)) = o;
    }

    // Scalar tail for odd element count.
    for (size_t i = n2 + tid; i < size; i += stride) {
        output[i] = fused_op(input[i]);
    }
}

extern "C" void fused_gelu_trunc_launcher(
    float* output, const float* input, size_t size, cudaStream_t stream) {
    if (size == 0) return;

    // Fixed ~1024-block grid: measured sweet spot on C500 (the grid must not
    // be sized per-element; too fine a grid stalls at a fraction of the
    // copy ceiling).
    const int BLOCK = 256;
    const int GRID = 1024;
    fused_gelu_trunc_kernel2<<<GRID, BLOCK, 0, stream>>>(output, input, size);
}

