#include <cuda_runtime.h>

// Fused GELU (tanh approximation) + trunc.
// Memory-bound elementwise: one pass over x instead of two (geLU then trunc).
// float2 vectorized loads, fixed 1024-block grid-stride loop (per MACA notes:
// fine grids are a perf trap on C500; this pattern reached ~1300 GB/s).
__device__ __forceinline__ float gelu_core(float x) {
    // tanh(sqrt(2/pi) * (x + 0.044715 x^3))
    const float c = 0.7978845608028654f;   // sqrt(2/pi)
    const float a = 0.044715f;
    float x2 = x * x;
    float inner = c * (x + a * x2 * x);
    // tanhf is a single SFU op; no chained dependency afterwards.
    float t = tanhf(inner);
    return 0.5f * x * (1.0f + t);
}

// Vectorized body: 2 elements per thread using float2 load/store.
__device__ __forceinline__ float2 gelu_trunc2(float2 v) {
    float2 r;
    r.x = truncf(gelu_core(v.x));
    r.y = truncf(gelu_core(v.y));
    return r;
}

template<int BLOCK>
__global__ void gelu_trunc_kernel(float* __restrict__ out,
                                  const float* __restrict__ in,
                                  int n2) {
    const int tid = blockIdx.x * BLOCK + threadIdx.x;
    const int stride = gridDim.x * BLOCK;

    float2* out2 = reinterpret_cast<float2*>(out);
    const float2* in2 = reinterpret_cast<const float2*>(in);

    for (int i = tid; i < n2; i += stride) {
        out2[i] = gelu_trunc2(in2[i]);
    }
}

// Scalar tail for odd element counts (n % 2 == 1).
__global__ void gelu_trunc_tail(float* __restrict__ out,
                                const float* __restrict__ in,
                                int start, int n) {
    const int tid = blockIdx.x * 256 + threadIdx.x;
    const int stride = gridDim.x * 256;
    for (int i = start + tid; i < n; i += stride) {
        out[i] = truncf(gelu_core(in[i]));
    }
}

extern "C" void gelu_trunc_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int n2 = size / 2;
    const int tail = size - n2 * 2;

    if (n2 > 0) {
        const int BLOCK = 256;
        // Fixed grid of 1024 blocks: keeps occupancy high without an
        // over-fine grid (104 SMs -> ~2.5 blocks/SM wave).
        int blocks = 1024;
        if (n2 < blocks * BLOCK) {
            blocks = (n2 + BLOCK - 1) / BLOCK;
            if (blocks < 1) blocks = 1;
        }
        gelu_trunc_kernel<256><<<blocks, BLOCK, 0, stream>>>(output, input, n2);
    }

    if (tail > 0) {
        int start = n2 * 2;
        int blocks = 32;
        gelu_trunc_tail<<<blocks, 256, 0, stream>>>(output, input, start, size);
    }
}

