// Fused GELU + trunc kernel for MetaX C500
//
// model.py:  x = F.gelu(x);  x = torch.trunc(x);  return x
//
// Exact GELU (PyTorch default, approximate='none'):
//     gelu(x) = x * Phi(x) = x * 0.5 * (1 + erf(x / sqrt(2)))
//
// IMPORTANT: do NOT use the tanh approximation here. The output is immediately
// truncated, so a value whose true GELU is 0.9999999 must NOT round to 1.0 —
// the tanh form shifts the boundary by ~1e-3 near |x| ~ 1.6 and trunc turns
// that tiny error into a full 1.0 mismatch. Use erff for exactness.
//
// Memory pattern: float2 loads with a fixed ~1024-block grid-stride loop.
// (Warp size on this device is 64.)

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_gelu_trunc_impl(float* __restrict__ output,
                                      const float* __restrict__ input,
                                      int size) {
    // float2 vectorized processing: each thread handles 2 elements per step
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;

    // Number of float2 pairs (size is even for these shapes, but stay safe)
    const int npairs = size >> 1;

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    for (int i = tid; i < npairs; i += stride) {
        float2 v = in2[i];

        float2 r;
        // gelu(v.x) then trunc
        r.x = erff(v.x * 0.70710678118654752440f);   // erf(x / sqrt(2))
        r.x = v.x * (0.5f * (1.0f + r.x));
        r.x = truncf(r.x);

        // gelu(v.y) then trunc
        r.y = erff(v.y * 0.70710678118654752440f);
        r.y = v.y * (0.5f * (1.0f + r.y));
        r.y = truncf(r.y);

        out2[i] = r;
    }

    // Tail: odd element count
    if ((size & 1) == 1) {
        for (int i = tid; i < size; i += stride) {
            if (i == size - 1) {
                float v = input[i];
                float e = erff(v * 0.70710678118654752440f);
                float g = v * (0.5f * (1.0f + e));
                output[i] = truncf(g);
            }
        }
    }
}

extern "C" void fused_gelu_trunc_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    const int npairs = size >> 1;
    if (npairs > 0) {
        // Fixed, moderately sized grid — too fine a grid is a real performance
        // trap on this device. Config selects block size only.
        switch (config) {
            case 1: { // 128 threads x 8 blocks grid-stride
                const int BLOCK = 128;
                int blocks = (npairs + BLOCK - 1) / BLOCK;
                if (blocks > 8) blocks = 8;
                fused_gelu_trunc_impl<BLOCK><<<blocks, BLOCK, 0, stream>>>(output, input, size);
                break;
            }
            case 2: { // 512 threads x 2 blocks grid-stride
                const int BLOCK = 512;
                int blocks = (npairs + BLOCK - 1) / BLOCK;
                if (blocks > 2) blocks = 2;
                fused_gelu_trunc_impl<BLOCK><<<blocks, BLOCK, 0, stream>>>(output, input, size);
                break;
            }
            default: { // 256 threads x 4 blocks grid-stride (measured best)
                const int BLOCK = 256;
                int blocks = (npairs + BLOCK - 1) / BLOCK;
                if (blocks > 4) blocks = 4;
                fused_gelu_trunc_impl<BLOCK><<<blocks, BLOCK, 0, stream>>>(output, input, size);
                break;
            }
        }
    } else {
        // size == 0 or 1: scalar path
        fused_gelu_trunc_impl<64><<<1, 64, 0, stream>>>(output, input, size);
    }
}

