// kernels/gelu_trunc.cu — fused GELU + trunc, memory-bound elementwise.
// C500 notes: warp size 64, 104 SMs, ~1350 GB/s copy ceiling.
// Use float2 loads with a fixed ~1024-block grid-stride loop (measured
// 1227-1319 GB/s on this device for single-SFU activation chains).
#include <cuda_runtime.h>

// tanh-based GELU: 0.5*x*(1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
// x^3 = x*x*x — avoid the expf->log1pf chained-SFU pattern entirely; tanh
// is a single SFU op and the multiplies are cheap scalar ops.
__device__ __forceinline__ float gelu_tanh(float x) {
    const float kSqrt2OverPi = 0.7978845608028654f;
    const float kCoef = 0.044715f;
    float x2 = x * x;
    float x3 = x2 * x;
    float inner = kSqrt2OverPi * (x + kCoef * x3);
    float t = tanhf(inner);
    return 0.5f * x * (1.0f + t);
}

template<int BLOCK_SIZE>
__global__ void gelu_trunc_kernel_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int stride = BLOCK_SIZE * gridDim.x;

    // Grid-stride loop: fixed grid (launched below) keeps all 104 SMs busy
    // without a per-element block explosion.
    for (int i = tid; i < size; i += stride) {
        float v = gelu_tanh(input[i]);
        // truncf without branching: copysign of the integer-cast works for
        // the in-range values; clamp huge magnitudes to avoid UB of float->int.
        float a = fminf(fmaxf(v, -2147483647.0f), 2147483647.0f);
        float t = (float)((int)a);
        // truncate toward zero even for negative zero case
        output[i] = (v >= 0.0f || t != 0.0f) ? t : v;
        // equivalent to truncf(v): for |v| < 1 negative, trunc is -0.0
        output[i] = (a < 0.0f && v > -1.0f) ? -0.0f : t;
    }
}

extern "C" void gelu_trunc_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;      // 4 warps of 64 threads
    const int GRID = 1024;           // fixed grid: ~10 waves over 104 SMs
    int n = (size + 1) / 2;          // float2 pairs
    // If data is float2-aligned (default for torch float tensors), launch
    // the vectorized path.
    if ((((uintptr_t)input & 7) == 0) && (((uintptr_t)output & 7) == 0) && (size % 2 == 0)) {
        gelu_trunc_kernel_impl<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    } else {
        gelu_trunc_kernel_impl<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    }
}

