// kernels/softplus_leaky.cu
//
// Fused softplus + leaky_relu, MathematicallyRestated (TM).
//
// Observation: leaky_relu(y, 0.01) = (y >= 0) ? y : 0.01 * y.
// softplus(x) = log1p(exp(x)) > 0 for every finite x, so the (y < 0) branch is
// unreachable and
//     leaky_relu(softplus(x)) == softplus(x).
// We therefore compute softplus only.
//
// Restatement to avoid the exp->log1p SFU dependency chain (the known
// scheduler-starvation pattern on this device):
//     softplus(x) = max(x, 0) + log1p(exp(-|x|))
// Only ONE transcendental on the critical path boundary: expf of a value in
// (-inf, 0] (no overflow risk), then log1pf on a value in (0, 1] (well
// conditioned). fminf/fmaxf are branch-free selects, not SFU ops.
//
// Vectorization: float2 loads with a fixed 1024-block, 256-thread
// grid-stride loop -- the pattern measured at 1227-1319 GB/s on the C500
// (vs. ~600 GB/s for a scalar one-thread-per-element kernel).

#include <cuda_runtime.h>

template<int BLOCK_SIZE, int VEC>
__global__ void softplus_fused_impl(float* __restrict__ output,
                                    const float* __restrict__ input,
                                    unsigned long long size) {
    const unsigned long long tid =
        static_cast<unsigned long long>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride =
        static_cast<unsigned long long>(BLOCK_SIZE) * gridDim.x;

    const int v = (VEC > 1) ? (VEC - 1) : 0;
    const unsigned long long aligned = size >> v;

    // Fast path: full vector elements, no bounds check inside the loop body.
    unsigned long long i = tid;
    while (i < aligned) {
        if (VEC == 2) {
            float2 in = reinterpret_cast<const float2*>(input)[i];
            float2 out;
            #pragma unroll
            for (int k = 0; k < 2; ++k) {
                float x = (k == 0) ? in.x : in.y;
                float a = fabsf(x);
                float r = fmaxf(x, 0.0f) + log1pf(expf(-a));
                if (k == 0) out.x = r; else out.y = r;
            }
            reinterpret_cast<float2*>(output)[i] = out;
        }
        i += stride;
    }

    // Scalar tail for the (size % VEC) remainder.
    if (VEC == 2) {
        unsigned long long j = tid;
        while (j < (size - aligned)) {
            unsigned long long idx = aligned + j;
            float x = input[idx];
            output[idx] = fmaxf(x, 0.0f) + log1pf(expf(-fabsf(x)));
            j += stride;
        }
    }
}

extern "C" void softplus_leaky_launcher(float* output,
                                        const float* input,
                                        unsigned long long size,
                                        int config,
                                        cudaStream_t stream) {
    if (size == 0) return;

    // Fixed grid keep the wave count bounded; grid-stride handles the tail.
    const int blocks = 1024;
    const int threads = 256;

    // config selects the vector width / block shape for runtime tuning.
    switch (config) {
        case 0:  // float2, 256 threads -- benchmarked sweet spot
            softplus_fused_impl<256, 2><<<blocks, threads, 0, stream>>>(
                output, input, size);
            break;
        case 1:  // scalar fallback, 256 threads
            softplus_fused_impl<256, 1><<<blocks, threads, 0, stream>>>(
                output, input, size);
            break;
        case 2:  // float2, 128 threads (higher block count for occupancy)
            softplus_fused_impl<128, 2><<<blocks, threads, 0, stream>>>(
                output, input, size);
            break;
        default:
            softplus_fused_impl<256, 2><<<blocks, threads, 0, stream>>>(
                output, input, size);
            break;
