#include <cuda_runtime.h>

// Fused: leaky_relu then selu.
//   leaky_relu(x) = x            if x > 0  else  0.01 * x
//   selu(y)      = scale * y     if y > 0  else  alpha * (exp(y) - 1)
// scale = 1.0507009873554804934193349852946, alpha = 1.6732632423543772848174624670917
//
// Negative branch is computed directly as  alpha*(exp(y) - 1); never multiply
// selu(x) by a select mask (that zeroed/near-zeroed the negative branch and
// caused the 9.3% mismatch).
//
// Warp size on this device is 64. Memory-bound elementwise: use float2 loads
// with a fixed 1024-block grid-stride loop (~1300 GB/s on C500 vs ~600 GB/s
// for one thread per element).

__device__ __constant__ float SELU_ALPHA = 1.6732632423543772848174624670917f;
__device__ __constant__ float SELU_SCALE = 1.0507009873554804934193349852946f;
__device__ __constant__ float NEG_SLOPE  = 0.01f;

template<int BLOCK_SIZE>
__global__ void leaky_selu_kernel(float* __restrict__ output,
                                  const float* __restrict__ input,
                                  int size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const float alpha = SELU_ALPHA;
    const float scale = SELU_SCALE;
    const float slope = NEG_SLOPE;
    const float alpha_scale = alpha * scale;

    // float2 vectorized grid-stride loop
    for (int i = tid; i < size; i += stride) {
        float2 v = reinterpret_cast<const float2*>(input)[i];
        float2 r;
        float a = v.x;
        float b = v.y;

        // leaky_relu
        float la = (a > 0.0f) ? a : (slope * a);
        float lb = (b > 0.0f) ? b : (slope * b);

        // selu: positive -> scale*y ; negative -> alpha*(expf(y)-1) * scale
        float xa = (la > 0.0f) ? (scale * la)
                               : (alpha_scale * (__expf(la) - 1.0f));
        float xb = (lb > 0.0f) ? (scale * lb)
                               : (alpha_scale * (__expf(lb) - 1.0f));

        r.x = xa;
        r.y = xb;
        reinterpret_cast<float2*>(output)[i] = r;
    }
}

extern "C" void leaky_selu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    (void)config;
    // size counts float2 elements (pairs); caller passes numel()/2.
    const int BLOCK_SIZE = 256;
    // Fixed ~1024 blocks, grid-stride handles the rest.
    int blocks = 1024;
    int total = (int)(((__int64)blocks * BLOCK_SIZE));
    if (size < total) {
        blocks = (size + BLOCK_SIZE - 1) / BLOCK_SIZE;
        if (blocks < 1) blocks = 1;
        if (blocks > 1024) blocks = 1024;
    }
    leaky_selu_kernel<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

