#include <cuda_runtime.h>

// Fused: leaky_relu(x) then selu(x).
// selu:  alpha=1.6732632423543772, scale=1.0507009873554805
//   x>0 : scale*x
//   x<=0: scale*alpha*(exp(x)-1)
// leaky_relu: negative slope = 0.01
// Combined: y = x>0 ? scale*x : scale*alpha*(exp(0.01*x)-1)
//
// Single-pass, float2 vectorized, fixed grid with grid-stride loop.
// Warp size on this device is 64.

__global__ void fused_leaky_selu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const float scale = 1.0507009873554805f;
    const float alpha = 1.6732632423543772f;
    const float slope = 0.01f;

    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const int n2 = size >> 1;

    // Float2 fast path: size even, vectorized loads/stores
    for (int i = tid; i < n2; i += stride) {
        float2 in = reinterpret_cast<const float2*>(input)[i];

        float a = in.x;
        float b = in.y;

        float ra = fmaf(alpha, expf(slope * a), -1.0f) * scale;
        float rb = fmaf(alpha, expf(slope * b), -1.0f) * scale;

        float2 out;
        out.x = a > 0.0f ? scale * a : ra;
        out.y = b > 0.0f ? scale * b : rb;

        reinterpret_cast<float2*>(output)[i] = out;
    }

    // Tail for odd size
    if ((size & 1) != 0) {
        int i = size - 1;
        if (i >= 0) {
            float a = input[i];
            float r = fmaf(alpha, expf(slope * a), -1.0f) * scale;
            output[i] = a > 0.0f ? scale * a : r;
        }
    }
}

extern "C" void fused_leaky_selu_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int threads = 256;          // 4 warps of 64
    const int blocks = 1024;          // fixed grid; grid-stride covers any size

    fused_leaky_selu_kernel<<<blocks, threads, 0, stream>>>(
        output,
        input,
        size
    );
}

