#include <cuda_runtime.h>

// Fused abs + tan elementwise kernel.
// Memory-bound: one read + one write of the whole tensor instead of two.
// Uses float2 vectorized loads with a fixed-size grid-stride loop:
// on the MetaX C500 (warp 64, 104 SMs) this pattern reached ~1300 GB/s
// versus ~600 GB/s for a one-thread-per-element scalar grid.

template<int BLOCK_SIZE>
__global__ void abs_tan_kernel(float* __restrict__ output,
                               const float* __restrict__ input,
                               int64_t size) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Handle the tail element if size is odd, so the vector body is aligned.
    if (size & 1) {
        if (tid == 0) {
            output[size - 1] = tanf(fabsf(input[size - 1]));
        }
    }

    // Vector loop: 2 floats per thread iteration.
    const int64_t n2 = size / 2;
    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float2*>(output);

    for (int64_t i = tid; i < n2; i += stride) {
        float2 v = in2[i];
        v.x = tanf(fabsf(v.x));
        v.y = tanf(fabsf(v.y));
        out2[i] = v;
    }
}

extern "C" void abs_tan_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, saturating grid: ~1024 blocks covers 104 SMs several times over
    // and each thread does grid-stride work. Avoids the fine-grid trap.
    const int GRID = 1024;

    abs_tan_kernel<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

