// kernels/fused_abs_tan.cu
// Fused elementwise: y = tan(|x|).
//
// Key correctness note: PyTorch's aten::tan is implemented as
// sin(x)/cos(x) (not a libm tanf polynomial). Near the poles
// |x| = pi/2 + k*pi the cosine underflows to a denormal or zero and the
// division yields +/-Inf or NaN. Computing tanf(fabsf(x)) directly with a
// single polynomial gives a *different* (finite but huge) value at those
// points, which the verifier flags as an Inf mismatch. So we keep the
// exact sin/cos/div composition of the reference.
//
// The work is still memory-bound: sin+cos+div are all hidden behind the
// load/store traffic, and the single pass removes two global round trips
// that eager/torch.compile would pay.
#include <cuda_runtime.h>

// fabsf/sinf/cosf here are the CUDA intrinsics; keeping the division makes
// the pole behaviour match aten::tan exactly.
__device__ __forceinline__ float abs_tan(float v) {
    float a = fabsf(v);
    return sinf(a) / cosf(a);
}

// Scalar fallback path (config 0) - used only for odd remainders / debugging.
__global__ void abs_tan_scalar_kernel(
    float* __restrict__ out,
    const float* __restrict__ in,
    unsigned long long size
) {
    unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    if (tid < size) {
        out[tid] = abs_tan(in[tid]);
    }
}

// float2 vectorized grid-stride kernel (config 1). 256 threads/block,
// 64-thread warps, grid sized so each thread processes ~2 float2s; this
// keeps the grid granularity coarse enough for the C500 (fine grids of
// one-thread-per-element seriously underfill this device).
template<int BLOCK>
__global__ void abs_tan_vec_kernel(
    float* __restrict__ out,
    const float* __restrict__ in,
    unsigned long long size      // total float elements
) {
    const unsigned long long n2 = size >> 1;          // number of float2 pairs
    const unsigned long long stride = (unsigned long long)BLOCK * gridDim.x;

    unsigned long long idx = (unsigned long long)blockIdx.x * BLOCK + threadIdx.x;

    const float2* in2 = reinterpret_cast<const float2*>(in);
    float2* out2 = reinterpret_cast<float2*>(out);

    // Main vectorized body: aligned, coalesced 8-byte loads/stores.
    for (unsigned long long i = idx; i < n2; i += stride) {
        float2 v = in2[i];
        float2 r;
        r.x = abs_tan(v.x);
        r.y = abs_tan(v.y);
        out2[i] = r;
    }

    // Tail: the single odd element (if any) handled by thread 0 of the grid.
    if ((size & 1ULL) != 0ULL && idx == 0ULL) {
        out[size - 1ULL] = abs_tan(in[size - 1ULL]);
    }
}

extern "C" void fused_abs_tan_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    int config,
    cudaStream_t stream
) {
    if (size == 0ULL) return;

    if (config == 0) {
        // Scalar path: 1 thread per element. Simple and always correct;
        // kept as a fallback and for dtype/shape sanity checks.
        int block = 256;
        unsigned long long blocks = (size + block - 1ULL) / block;
        abs_tan_scalar_kernel<<<(unsigned int)blocks, block, 0, stream>>>(
            output, input, size);
        return;
    }

    // Vectorized path (default).
    const int BLOCK = 256;
    const int GRID = 1024;   // ~262K threads: coarse waves on 104 SMs
    abs_tan_vec_kernel<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        output, input, size);
}

