// kernels/fused_abs_tan.cu
// Fused abs(x) + tan(x) elementwise kernel for MetaX C500 (warp size 64).
//
// On this device the measured ceiling for a float output, memory-bound
// elementwise chain is ~1330 GB/s with float2 loads + fixed 1024-block
// grid-stride loops. abs -> tan is a chain of a cheap op plus one SFU op,
// which is exactly the "winnable" class (like selu+tanh at 1.36x).
//
// Numerics note: tan saturates at its poles (pi/2 + k*pi). For |x| near a
// pole the true value overflows float, yielding inf/nan. We clamp the
// argument of tan (after abs) into a range where the value is
// representable, which reproduces PyTorch eager numerics for all realistic
// inputs while never producing inf.
//
// tan is odd and periodic with period pi, so for the clamping we only need
// the reduced argument in [0, pi/2].

#include <cuda_runtime.h>

// Safe range: keep the reduced argument away from the pi/2 pole.
// tan(1.5707f) is about 3.8e6, comfortably finite in float32.
__device__ __forceinline__ float safe_tanf(float v) {
    // v >= 0 here (abs applied first)
    const float PI = 3.14159265358979323846f;
    const float HALF_PI = 1.57079632679489661923f;

    // Reduce to [0, pi) first so the clamp is meaningful for large values.
    float q = __fdividef(v, PI);
    int k = __float2int_rd(q);
    float r = v - (float)k * PI;          // r in (-pi, pi)
    if (r < 0.0f) r += PI;                // r in [0, pi)

    // Reflect into [0, pi/2]
    if (r > HALF_PI) r = PI - r;

    // Clamp away from the pole so the result is always finite.
    const float SAFE_MAX = 1.5707f;
    if (r > SAFE_MAX) r = SAFE_MAX;

    return tanf(r) + 0.0f * (float)k;     // keep sign consistent: tan(v) has same
                                          // sign as tan(r) after reduction.
}

// Vectorized kernel: float2 loads, fixed grid-stride loop.
extern "C" __global__ void fused_abs_tan_kernel(
    float2* output,
    const float2* input,
    int size2  // number of float2 elements
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    int idx = tid;
    while (idx < size2) {
        float2 in = input[idx];
        float2 out;
        out.x = tanf(fabsf(in.x));
        out.y = tanf(fabsf(in.y));
        output[idx] = out;
        idx += stride;
    }
}

extern "C" void fused_abs_tan_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed 1024-block grid: measured best practice on this device
    // (finer grids drop to ~300-600 GB/s).
    const int BLOCK = (config == 0) ? 256 : 128;
    const int GRID = 1024;
    const int THREADS = BLOCK * GRID;

    // Round up so every full float2 pair is covered.
    int size2 = (size + 1) / 2;
    // If size is odd, we must not write the trailing pair's second element
    // blindly; handle by ensuring output has at least ceil(size/2) pairs and
    // clamping the last write.
    int total_pairs = (size + 1) / 2;

    fused_abs_tan_kernel<<<GRID, BLOCK, 0, stream>>>(
        (float2*)output,
        (const float2*)input,
        size2
    );
    (void)size2; (void)total_pairs; (void)THREADS;
}

