// kernels/fused_relu_trunc.cu
// Fused ReLU + Trunc: y = trunc(relu(x)) == trunc(x) if x > 0 else 0.
//
// Restated branch-free to avoid the compiler fusing fabs/trunc in a way that
// drops the ReLU clamp on negative inputs: compute t = trunc(x), then select
// t when x > 0 and 0.0f otherwise.  Single memory pass, float2 vectorized,
// fixed ~1024-block grid-stride loop (MACA C500 guidance: fine grids are a
// performance trap).
#include <cuda_runtime.h>

__device__ __forceinline__ float fused_relu_trunc_scalar(float x) {
    float t = truncf(x);
    // x > 0  -> t ;  x <= 0 -> 0   (handles -0.0f and NaN -> 0 correctly)
    return (x > 0.0f) ? t : 0.0f;
}

__global__ void fused_relu_trunc_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size)
{
    const unsigned long long tid =
        (unsigned long long)blockIdx.x * (unsigned long long)blockDim.x
        + (unsigned long long)threadIdx.x;
    const unsigned long long stride =
        (unsigned long long)blockDim.x * (unsigned long long)gridDim.x;

    const unsigned long long vec_size = size >> 1;  // size / 2

    // --- Vectorized float2 portion -------------------------------------
    if (tid < vec_size) {
        for (unsigned long long i = tid; i < vec_size; i += stride) {
            float2 in = reinterpret_cast<const float2*>(input)[i];
            float2 out;
            out.x = fused_relu_trunc_scalar(in.x);
            out.y = fused_relu_trunc_scalar(in.y);
            reinterpret_cast<float2*>(output)[i] = out;
        }
    }

    // --- Tail element (odd total count), one dedicated thread ----------
    if ((size & 1ULL) != 0ULL) {
        if (tid == 0ULL) {
            output[size - 1ULL] = fused_relu_trunc_scalar(input[size - 1ULL]);
        }
    }
}

extern "C" void fused_relu_trunc_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream)
{
    const int blockSize = 256;              // 4 warps of 64 lanes
    const int maxBlocks  = 1024;            // fixed grid: ~10 waves on 104 SMs
    unsigned long long elements = size >> 1;
    if (elements == 0ULL) elements = 1ULL;  // keep 1 block for the odd-tail case
    int blocks = (int)((elements + (unsigned long long)blockSize - 1ULL)
                       / (unsigned long long)blockSize);
    if (blocks > maxBlocks) blocks = maxBlocks;
    if (blocks < 1) blocks = 1;

    fused_relu_trunc_kernel<<<blocks, blockSize, 0, stream>>>(
        output, input, size);
}

