#include <cuda_runtime.h>

// Fused ReLU + Trunc on 16x3840x3840 floats (236M elements, ~945 MB).
// Math is branch-free: relu(x) = x < 0 ? 0 : x, then trunc.
// Memory-bound => float2 grid-stride loop over a fixed 1024-block grid
// (104 SMs, warp size 64) so each block processes a large contiguous tile.
template<int BLOCK_SIZE>
__global__ void fused_relu_trunc_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    long long size
) {
    const long long tid = (long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const long long stride = (long long)BLOCK_SIZE * gridDim.x;

    for (long long i = tid; i < size; i += stride) {
        const bool full = (i + BLOCK_SIZE) < size;
        if (full) {
            float2 v = *reinterpret_cast<const float2*>(input + i);
            // relu then trunc
            float a = v.x < 0.0f ? 0.0f : v.x;
            float b = v.y < 0.0f ? 0.0f : v.y;
            float2 out;
            out.x = truncf(a);
            out.y = truncf(b);
            *reinterpret_cast<float2*>(output + i) = out;
        } else {
            #pragma unroll
            for (int k = 0; k < 2; ++k) {
                long long idx = i + (long long)k * BLOCK_SIZE;
                if (idx < size) {
                    float v = input[idx];
                    float a = v < 0.0f ? 0.0f : v;
                    output[idx] = truncf(a);
                }
            }
        }
    }
}

extern "C" void fused_relu_trunc_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    // Fixed grid sized to the device (104 SMs); grid-stride handles the rest.
    int blocks = 1024;
    fused_relu_trunc_kernel<256><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

