#include <cuda_runtime.h>

// Fused GELU (tanh approximation) + SELU.
//
// out = selu(gelu(x))
//     gelu(x)  = 0.5x(1 + tanh( sqrt(2/pi) (x + 0.044715 x^3) ))
//     selu(g)  = 1.0507 * (g if g>0 else 1.6732632*g)
//
// Single expf per element (tanh(z) = 1 - 2/(e^{2z}+1)); no chained SFU
// dependency, so the arithmetic is fully hidden behind memory traffic.
// float4 vectorization + fixed grid keeps DRAM traffic to one read/one write.

__device__ __forceinline__ float gelu_core(float x) {
    const float kSqrt2Pi  = 0.7978845608028654f;
    const float kCoeff    = 0.044715f;
    float x2 = x * x;
    float x3 = x2 * x;
    float z  = kSqrt2Pi * (x + kCoeff * x3);
    float ez = expf(2.0f * z);
    float t  = 1.0f - 2.0f / (ez + 1.0f);
    return 0.5f * x * (1.0f + t);
}

__device__ __forceinline__ float selu_core(float g) {
    const float kAlpha = 1.6732631762428436f;
    const float kScale = 1.0507009873554805f;
    return kScale * (g > 0.0f ? g : kAlpha * g);
}

template<int BLOCK_SIZE, int VEC>
__global__ void fused_gelu_selu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size  // number of float elements
) {
    // Vector LANES per block; each thread handles VEC consecutive elements.
    const size_t vTotal = size / static_cast<size_t>(VEC);   // full vectors
    const size_t tid    = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    // Cast pointer widths: work in units of float4 when VEC == 4.
    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    if (VEC == 4) {
        #pragma unroll 1
        for (size_t v = tid; v < vTotal; v += stride) {
            float4 a = in4[v];
            float4 r;
            r.x = selu_core(gelu_core(a.x));
            r.y = selu_core(gelu_core(a.y));
            r.z = selu_core(gelu_core(a.z));
            r.w = selu_core(gelu_core(a.w));
            out4[v] = r;
        }
        // Scalar tail
        size_t tailBase = vTotal * 4;
        for (size_t i = tailBase + tid; i < size; i += stride) {
            output[i] = selu_core(gelu_core(input[i]));
        }
    } else {
        #pragma unroll 1
        for (size_t i = tid; i < size; i += stride) {
            output[i] = selu_core(gelu_core(input[i]));
        }
    }
}

extern "C" void fused_gelu_selu_launcher(
    float* output,
    const float* input,
    size_t size,
    int config,
    cudaStream_t stream
) {
    // 268M elements: fixed grid of 1024 blocks x 256 threads, grid-stride.
    // 4 elements per thread per step via float4 -> ~1.07M elements/wave,
    // ~251 waves; keeps every SM busy while staying coarse enough to avoid
    // the fine-grid trap on this device.
    const int kBlockSize = 256;
    const int kGrid      = 1024;

    // Input/output buffers must be 16-byte aligned for float4; torch tensors
    // are at least 256-byte aligned, so this always holds.
    if ((config & 3) == 0 && ((reinterpret_cast<uintptr_t>(input) & 15) == 0) &&
        ((reinterpret_cast<uintptr_t>(output) & 15) == 0) && (size >= 4)) {
        fused_gelu_selu_kernel<kBlockSize, 4><<<kGrid, kBlockSize, 0, stream>>>(
            output, input, size);
    } else {
