#include <cuda_runtime.h>

// Fused GELU (tanh/sigmoid approximation) + SELU.
//
// model.py semantics:
//   x = F.gelu(x)               -> tanh-approximate form when approximate='tanh'
//   x = torch.selu(x)           -> selu(x) = 1.050700987355480493 * (x + 0.0717641293125775 * (exp(x)-1)) for x>0
//
// The tanh-approx GELU is: 0.5*x*(1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
// We restate tanh(z) as 1 - 2/(exp(2z)+1) so the whole chain is a single
// expf-based branch-free expression; the expf results feed independent
// multiplies/adds, avoiding a chained-SFU dependency (expf->log1pf style).
//
// Vectorized with float2 and a fixed-size grid-stride loop: on the C500
// (64-wide warps, 104 SMs) fine per-element grids stall at ~600 GB/s while
// float2 with ~1024 blocks reaches ~1300 GB/s.

namespace {

__device__ __forceinline__ float gelu_tanh_core(float x) {
    const float kSqrt2Pi = 0.7978845608028654f;   // sqrt(2/pi)
    const float kCoeff   = 0.044715f;
    float x3 = x * x * x;
    float z = kSqrt2Pi * (x + kCoeff * x3);
    // tanh(z) == 1 - 2/(exp(2z)+1)
    float e = expf(2.0f * z);
    float tanh_z = 1.0f - 2.0f / (e + 1.0f);
    return 0.5f * x * (1.0f + tanh_z);
}

__device__ __forceinline__ float selu_core(float x) {
    const float kAlpha = 1.6732632423543772f;
    const float kScale = 1.0507009873554805f;
    // branch-free: (x > 0) ? scale*x : scale*(alpha*e - alpha)
    float e = expf(x);
    float neg = kScale * (kAlpha * e - kAlpha);
    float pos = kScale * x;
    // select without a divergent branch
    return (x > 0.0f) ? pos : neg;
}

template<int BLOCK_SIZE>
__global__ void fused_gelu_selu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    unsigned long long tid = (unsigned long long)blockIdx.x * (unsigned long long)BLOCK_SIZE
                             + (unsigned long long)threadIdx.x;
    unsigned long long stride = (unsigned long long)BLOCK_SIZE * (unsigned long long)gridDim.x;

    const int UNROLL = 4;
    unsigned long long vectorized = size / (2u * UNROLL);

    // Each thread walks base, base+stride, ... handling UNROLL float2 pairs per step
    unsigned long long base = tid * 2u;
    unsigned long long vstride = stride * 2u;

    #pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
        unsigned long long pos = base + (unsigned long long)u * vstride;
        if (pos + 1u < size) {
            float2 in = *reinterpret_cast<const float2*>(input + pos);
            float2 out;
            out.x = selu_core(gelu_tanh_core(in.x));
            out.y = selu_core(gelu_tanh_core(in.y));
            *reinterpret_cast<float2*>(output + pos) = out;
        }
    }

    // Tail: scalar handling of any remaining element (size is odd)
    unsigned long long tail_start = vectorized * 2u * UNROLL;
    unsigned long long tail = size - tail_start;
    if (tail != 0u) {
        if (tid < tail) {
            unsigned long long pos = tail_start + tid;
            output[pos] = selu_core(gelu_tanh_core(input[pos]));
        }
    }
}

} // namespace

extern "C" void fused_gelu_selu_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    int config,
    cudaStream_t stream
) {
    if (size == 0u) return;

    const int blocks = 1024;
    switch (config) {
        case 0:
            fused_gelu_selu_kernel<256><<<blocks, 256, 0, stream>>>(output, input, size);
            break;
        case 1:
            fused_gelu_selu_kernel<512><<<blocks, 512, 0, stream>>>(output, input, size);
            break;
        default:
            fused_gelu_selu_kernel<256><<<blocks, 256, 0, stream>>>(output, input, size);
            break;
    }
}

