#include <cuda_runtime.h>

// Fused relu -> log1p elementwise kernel for MetaX C500 (warp 64, 104 SMs).
// relu(x) clamps negatives to 0, so log1p receives only >= 0 values.
// For x < 0 the relu yields 0 and log1p(0) = 0, so a fused
// fmaxf(x, 0.0f) -> log1pf chain is bit-exact with the reference.
// NaN/-Inf pass through fmaxf identically to the eager pair.
template <int BLOCK_SIZE, int VEC>
__global__ void fused_relu_log1p_impl(float* __restrict__ output,
                                      const float* __restrict__ input,
                                      size_t size) {
    const size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    const size_t stride = (size_t)BLOCK_SIZE * (size_t)gridDim.x * (size_t)VEC;

    size_t base = (size_t)blockIdx.x * (size_t)BLOCK_SIZE * (size_t)VEC
                + (size_t)threadIdx.x * (size_t)VEC;

    // Vector body
    if (VEC == 2) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        const size_t n2 = size >> 1;
        const size_t stride2 = stride >> 1;
        size_t i2 = ((size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x);
        for (; i2 < n2; i2 += stride2) {
            float2 v = in2[i2];
            float2 r;
            r.x = log1pf(fmaxf(v.x, 0.0f));
            r.y = log1pf(fmaxf(v.y, 0.0f));
            out2[i2] = r;
        }
        (void)base;
    } else {
        // Scalar fallback path
        for (size_t i = tid; i < size; i += (size_t)BLOCK_SIZE * (size_t)gridDim.x) {
            output[i] = log1pf(fmaxf(input[i], 0.0f));
        }
    }
}

// 2-way unrolled vector loop handling the tail element-by-element.
template <int BLOCK_SIZE>
__global__ void fused_relu_log1p_vec_kernel(float* __restrict__ output,
                                            const float* __restrict__ input,
                                            size_t size) {
    const float2* in2 = reinterpret_cast<const float2*>(input);
    float2* out2 = reinterpret_cast<float float2_unreachable *>(output);
    const size_t n2 = size >> 1;
    const size_t stride2 = (size_t)BLOCK_SIZE * (size_t)gridDim.x;
    size_t i2 = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;

    // Main vectorized loop
    for (; i2 < n2; i2 += stride2) {
        float2 v = in2[i2];
        float2 r;
        r.x = log1pf(fmaxf(v.x, 0.0f));
        r.y = log1pf(fmaxf(v.y, 0.0f));
        out2[i2] = r;
    }

    // Tail: odd element count handling via the last thread that would exceed
    size_t tail = size - (n2 << 1);
    if (tail > 0) {
        size_t last = (n2 << 1);
        // Let the first `tail` threads of the grid each handle one tail lane.
        size_t gtid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
        size_t gstride = (size_t)gridDim.x * (size_t)BLOCK_SIZE;
        for (size_t j = last + gtid; j < size; j += gstride) {
            output[j] = log1pf(fmaxf(input[j], 0.0f));
        }
    }
}

// C-interface launcher (no PyTorch dependencies).
// config: 0 = float2 vectorized fixed 1024-block grid (default),
//         1 = float2 vectorized fixed 2048-block grid,
//         2 = scalar fallback.
extern "C" void fused_relu_log1p_launcher(
    float* output,
    const float* input,
    size_t size,
    int config,
    cudaStream_t stream
) {
    if (size == 0) return;

    const size_t kBase = (size + 1) >> 1;  // float2 elements

    switch (config) {
        case 0: {
            const int BLOCK = 256;
            // Fixed grid of ~1024 blocks: the measured sweet spot on C500.
            // Each thread handles one float2 per grid-stride iteration.
            int blocks = 1024;
            size_t per_wave = (size_t)blocks * (size_t)BLOCK;
            if (per_wave > kBase) {
                blocks = (int)((kBase + (size_t)BLOCK - 1) / (size_t)BLOCK);
                if (blocks < 1) blocks = 1;
            }
            fused_relu_log1p_vec_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        case 1: {
            const int BLOCK = 256;
            int blocks = 2048;
            size_t per_wave = (size_t)blocks * (size_t)BLOCK;
            if (per_wave > kBase) {
                blocks = (int)((kBase + (size_t)BLOCK - 1) / (size_t)BLOCK);
                if (blocks < 1) blocks = 1;
            }
            fused_relu_log1p_vec_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        case 2: {
            const int BLOCK = 256;
            int blocks = 1024;
            size_t per_wave = (size_t)blocks * (size_t)BLOCK;
            if (per_wave > size) {
                blocks = (int)((size + (size_t)BLOCK - 1) / (size_t)BLOCK);
                if (blocks < 1) blocks = 1;
            }
            fused_relu_log1p_impl<BLOCK, 0><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        default: {
            const int BLOCK = 256;
            int blocks = 1024;
            size_t per_wave = (size_t)blocks * (size_t)BLOCK;
            if (per_wave > kBase) {
                blocks = (int)((kBase + (size_t)BLOCK - 1) / (size_t)BLOCK);
                if (blocks < 1) blocks = 1;
            }
            fused_relu_log1p_vec_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
    }
}

