// Fused abs + LogSoftmax over the last dimension.
// One block per row; online (single-pass) max + exp-sum via the standard
// one-block two-phase pattern. Vectorized float4 loads, warp size 64.
#include <cuda_runtime.h>

// Block size: 256 threads (4 warps of 64). Covers row_len <= 256*4*VEC = 4096
// with a pure stride loop, and larger rows via the grid-stride tail.
#define BLOCK 256

// Warp-level reduction over a 64-wide warp (xor butterfly).
__device__ __forceinline__ float warp_reduce_max(float v) {
    #pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        float o = __shfl_xor_sync(0xFFFFFFFFFFFFFFFFull, v, off);
        v = fmaxf(v, o);
    }
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    #pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        v += __shfl_xor_sync(0xFFFFFFFFFFFFFFFFull, v, off);
    }
    return v;
}

__global__ void fused_abs_logsoftmax_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_rows,
    int row_len)
{
    int row = blockIdx.x;
    if (row >= batch_rows) return;

    const float* in = input + (size_t)row * row_len;
    float* out = output + (size_t)row * row_len;

    const int tid = threadIdx.x;
    const int nvec = row_len >> 2;           // number of float4 slots
    const int rem = row_len & 3;             // tail elements

    // ---- Phase 1: online max + sum over the row (single pass) ----
    float lmax = -INFINITY;
    float lsum = 0.0f;

    for (int i = tid; i < nvec; i += BLOCK) {
        float4 v = reinterpret_cast<const float4*>(in)[i];
        v.x = fabsf(v.x); v.y = fabsf(v.y);
        v.z = fabsf(v.z); v.w = fabsf(v.w);
        float m = fmaxf(fmaxf(v.x, v.y), fmaxf(v.z, v.w));
        float m0 = lmax;
        lmax = fmaxf(lmax, m);
        // online accumulation: sum(new) = sum(old) * exp(old_max - new_max) + exp(v - new_max)
        float c = __expf(m0 - lmax);
        lsum = lsum * c + (__expf(v.x - lmax) + __expf(v.y - lmax)) +
                        (__expf(v.z - lmax) + __expf(v.w - lmax));
    }
    // scalar tail
    for (int i = nvec * 4 + tid; i < row_len; i += BLOCK) {
        float v = fabsf(in[i]);
        float m0 = lmax;
        lmax = fmaxf(lmax, v);
        lsum = lsum * __expf(m0 - lmax) + __expf(v - lmax);
    }
    // ensure tail contributions exist even if rem == 0 (no-op otherwise)

    // Warp reduce
    float wmax = warp_reduce_max(lmax);
    float wsum = warp_reduce_sum(lsum);

    // Block reduce via shared memory (4 warps -> 4 slots)
    __shared__ float smax[4];
    __shared__ float ssum[4];

    int wid = tid >> 6;          // warp id (warp size 64)
    int lane = tid & 63;
    if (lane == 0) {
        smax[wid] = wmax;
        ssum[wid] = wsum;
    }
    __syncthreads();

    __shared__ float fmax_s, fsum_s;
    if (tid < 4) {
        float m = (tid < (BLOCK >> 6)) ? smax[tid] : -INFINITY;
        float s = (tid < (BLOCK >> 6)) ? ssum[tid] : 0.0f;
        m = warp_reduce_max(m);
        s = warp_reduce_sum(s);
        if (tid == 0) {
            fmax_s = m;
            fsum_s = s;
        }
    }
    __syncthreads();

    float mx = fmax_s;
    float sm = fsum_s;
    float logsum = logf(sm) + mx;   // log(sum exp(x - max)) + max

    // ---- Phase 2: normalize ----
    for (int i = tid; i < nvec; i += BLOCK) {
        float4 v = reinterpret_cast<const float4*>(in)[i];
        v.x = fabsf(v.x); v.y = fabsf(v.y);
        v.z = fabsf(v.z); v.w = fabsf(v.w);
        v.x = (v.x - mx) - logsum;
        v.y = (v.y - mx) - logsum;
        v.z = (v.z - mx) - logsum;
        v.w = (v.w - mx) - logsum;
        reinterpret_cast<float4*>(out)[i] = v;
    }
    for (int i = nvec * 4 + tid; i < row_len; i += BLOCK) {
        out[i] = (fabsf(in[i]) - mx) - logsum;
    }
}

extern "C" void fused_abs_logsoftmax_launcher(
    float* output,
    const float* input,
    int batch_rows,
    int row_len,
    cudaStream_t stream)
{
    // One block per row; rows are large (1024) so 256-thread blocks with
    // float4 grid-stride loops do 16 vec loads each in phase 1/2.
    int blocks = batch_rows;
    if (row_len <= 0) return;

    fused_abs_logsoftmax_kernel<<<blocks, BLOCK, 0, stream>>>(
        output, input, batch_rows, row_len);
}

