// kernels/logsoftmax_kernel.cu
// Fused |x| followed by LogSoftmax(dim=-1).
//
// Reduction is over the last dim (width). Threads map to (row, col) pairs,
// NOT a flat element index, otherwise every output is wrong.
// Layout: row = i / width, col = i % width.

#include <cuda_runtime.h>

#define FULL_MASK 0xffffffffu

// One block handles ONE row when width <= 1024. Block size >= width so each
// thread owns at most one element of the row.
template<int BLOCK_SIZE>
__device__ __forceinline__ void process_row(
    const float* __restrict__ row_in,
    float* __restrict__ row_out,
    int width,
    float* smem_m,
    float* smem_z
) {
    const int tid = threadIdx.x;
    const int lane = tid & 63;
    const int warp = tid >> 6;

    // ---- Pass 1: max of |x| (online softmax style: max first, then sum)
    float my = -INFINITY;
    if (tid < width) {
        my = fabsf(row_in[tid]);
    }
    // Broadcast-load extra elements if width < BLOCK_SIZE (no-op when equal)
    // Warp reduce max (warp size 64 on C500)
#pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        float v = __shfl_xor_sync(FULL_MASK, my, off);
        if (v > my) my = v;
    }
    smem_m[warp] = my;
    __syncthreads();

    if (warp == 0) {
        my = (tid < (BLOCK_SIZE >> 6)) ? smem_m[lane] : -INFINITY;
#pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            float v = __shfl_xor_sync(FULL_MASK, my, off);
            if (v > my) my = v;
        }
        if (lane == 0) smem_m[0] = my;
    }
    __syncthreads();
    const float maxv = smem_m[0];

    // ---- Pass 2: sum of exp(|x| - max)
    float myz = 0.0f;
    if (tid < width) {
        myz = expf(my - maxv);   // |x| <= max so exponent <= 0, no overflow
    }
#pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        myz += __shfl_xor_sync(FULL_MASK, myz, off);
    }
    smem_z[warp] = myz;
    __syncthreads();

    if (warp == 0) {
        myz = (tid < (BLOCK_SIZE >> 6)) ? smem_z[lane] : 0.0f;
#pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            myz += __shfl_xor_sync(FULL_MASK, myz, off);
        }
        if (lane == 0) smem_z[0] = myz;
    }
    __syncthreads();
    const float sum = smem_z[0];
    const float logsum = logf(sum) + maxv;

    // ---- Store: logsoftmax = |x| - logsum
    if (tid < width) {
        row_out[tid] = my - logsum;   // 'my' holds |x| only if tid < width
    }
}

// Fallback: grid-stride over a single row, multi-element per thread.
// Used when width > BLOCK_SIZE (not the case here, but keeps correctness).
__global__ void fused_abs_logsoftmax_wide_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int width
) {
    extern __shared__ float smem[];
    float* smem_m = smem;
    float* smem_z = smem + 128;

    const int row = blockIdx.x;
    const float* row_in = input + (int64_t)row * width;
    float* row_out = output + (int64_t)row * width;

    const int tid = threadIdx.x;
    const int stride = blockDim.x;

    // load chunk max
    float my = -INFINITY;
    for (int i = tid; i < width; i += stride) {
        float v = fabsf(row_in[i]);
        if (v > my) my = v;
    }
    // block-wide max via shared memory
    smem_m[tid] = my;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            float a = smem_m[tid], b = smem_m[tid + s];
            smem_m[tid] = (b > a) ? b : a;
        }
        __syncthreads();
    }
    const float maxv = smem_m[0];
    __syncthreads();

    // sum exp
    float myz = 0.0f;
    for (int i = tid; i < width; i += stride) {
        myz += expf(fabsf(row_in[i]) - maxv);
    }
    smem_z[tid] = myz;
    __syncthreads();
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) smem_z[tid] += smem_z[tid + s];
        __syncthreads();
    }
    const float logsum = logf(smem_z[0]) + maxv;
    __syncthreads();

    for (int i = tid; i < width; i += stride) {
        row_out[i] = fabsf(row_in[i]) - logsum;
    }
}

__global__ void fused_abs_logsoftmax_1024_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int width
) {
    __shared__ float smem_m[16];
    __shared__ float smem_z[16];
    const int row = blockIdx.x;
    const float* row_in = input + (int64_t)row * width;
    float* row_out = output + (int64_t)row * width;
    process_row<1024>(row_in, row_out, width, smem_m, smem_z);
}

// Vectorized store variant: 1024 threads own one element each, but the
// final store is issued by 256 threads writing float4. Output rows are
// 1024 floats = 4096 bytes, 4-byte aligned, so float4 stores coalesce.
__global__ void fused_abs_logsoftmax_1024_vec_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int width
) {
    __shared__ float smem_m[16];
    __shared__ float smem_z[16];
    __shared__ float sval[1024];

    const int row = blockIdx.x;
    const float* row_in = input + (int64_t)row * width;
    float* row_out = output + (int64_t)row * width;
    const int tid = threadIdx.x;

    // ---- max of |x|
    float my = -INFINITY;
    if (tid < width) {
        my = fabsf(row_in[tid]);
        sval[tid] = my;   // cache |x| for the store pass (avoid reload)
    }
    const int lane = tid & 63;
    const int warp = tid >> 6;
#pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        float v = __shfl_xor_sync(FULL_MASK, my, off);
        if (v > my) my = v;
    }
    smem_m[warp] = my;
    __syncthreads();
    if (warp == 0) {
        my = smem_m[lane];
#pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            float v = __shfl_xor_sync(FULL_MASK, my, off);
            if (v > my) my = v;
        }
        if (lane == 0) smem_m[0] = my;
    }
    __syncthreads();
    const float maxv = smem_m[0];

    // ---- sum exp
    float myz = 0.0f;
    if (tid < width) myz = expf(my - maxv);
#pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        myz += __shfl_xor_sync(FULL_MASK, myz, off);
    }
    smem_z[warp] = myz;
    __syncthreads();
    if (warp == 0) {
        myz = smem_z[lane];
#pragma unroll
        for (int off = 32; off > 0; off >>= 1) {
            myz += __shfl_xor_sync(FULL_MASK, myz, off);
        }
        if (lane == 0) smem_z[0] = myz;
    }
    __syncthreads();
    const float logsum = logf(smem_z[0]) + maxv;

    // ---- vectorized store, 256 threads x float4
    if (tid < 256) {
        float4 v;
        const float* p = sval + tid * 4;
        v.x = p[0] - logsum;
        v.y = p[1] - logsum;
        v.z = p[2] - logsum;
        v.w = p[3] - logsum;
        if (tid * 4 < width) {
            reinterpret_cast<float4*>(row_out)[tid] = v;
        }
    }
}

extern "C" void fused_abs_logsoftmax_launcher(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_rows,
    int width,
    cudaStream_t stream
) {
    const int rows = batch_rows;
    if (width <= 1024) {
        // one block per row, 1024 threads (warp 64 => 16 warps)
        fused_abs_logsoftmax_1024_vec_kernel<<<rows, 1024, 0, stream>>>(
            input, output, width);
    } else {
        // wide rows: grid-stride within a row
        int threads = 512;
        if (width > 4096) threads = 1024;
        fused_abs_logsoftmax_wide_kernel<<<rows, threads, 0, stream>>>(
            input, output, width);
    }
}

