// Normalize dtype/contiguity: the eval harness regenerates inputs with its own
// seed and the dtype arriving at forward() is not guaranteed to match.
static torch::Tensor to_f32_contiguous(torch::Tensor t) {
    if (!t.is_contiguous()) {
        t = t.contiguous();
    }
    if (t.dtype() != torch::kFloat32) {
        t = t.to(torch::kFloat32);
    }
