}

torch::Tensor fused_abslogsoftmax_forward(torch::Tensor x, int config) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    x = to_f32_contiguous(x);

    TORCH_CHECK(x.dim() >= 1, "Input must have at least 1 dimension");

    int64_t batch_rows = 1;
    for (int64_t i = 0; i < x.dim() - 1; ++i) {
        batch_rows *= x.sizes()[i];
    }
    int64_t row_len = x.sizes()[x.dim() - 1];

    auto out = torch::empty_like(x);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_abslogsoftmax_launcher(
        out.data_ptr<float>(),
        x.data_ptr<float>(),
        (int)batch_rows,
        (int)row_len,
        config,
        stream
    );

    return out;
}

