// Fused abs + LogSoftmax over the last dimension, for MetaX C500.
//
// Two passes over each row:
//   pass 1: reduce max(|x|), then reduce sum(exp(|x| - max))  (fused here)
//   pass 2: y = |x| - max - log(sum)
//
// Reduction strategy: one warp (64 threads on C500) per row solved entirely
// with __shfl_sync (no shared memory, no __syncthreads), plus a grid-stride
// loop so each warp covers multiple rows. Row length 1024 = 16 float2s, so a
// warp handles a row with 16 loads per thread pair-group; we keep a fixed
// grid of ~4 warps per block x 520 blocks to cover 104 SMs without an
// oversized grid (the fine-grid trap measured on this device).

#include <cuda_runtime.h>

namespace {

__device__ __forceinline__ float warp_reduce_max(float v, unsigned mask) {
    // Warp size is 64 on xcore1000.
    #pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        float t = __shfl_xor_sync(mask, v, off);
        v = fmaxf(v, t);
    }
    return v;
}

__device__ __forceinline__ float warp_reduce_sum(float v, unsigned mask) {
    #pragma unroll
    for (int off = 32; off > 0; off >>= 1) {
        v += __shfl_xor_sync(mask, v, off);
    }
    return v;
}

// One warp per row. Threads 0..63 cooperate; each thread strides by 64.
// Row len assumed multiple of 2 (float2 loads). Fall back path handles tails.
template<int BLOCK_WARPS>
__global__ void abslogsoftmax_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int batch_rows,
    int row_len)
{
    const int warp_size = 64;
    int warp_id_in_block = threadIdx.x / warp_size;
    int lane = threadIdx.x % warp_size;

    // grid-stride over rows, one warp per row
    int total_warps = BLOCK_WARPS * gridDim.x;
    int warp_global = blockIdx.x * BLOCK_WARPS + warp_id_in_block;

    const unsigned mask = 0xffffffffu;

    for (int r = warp_global; r < batch_rows; r += total_warps) {
        const float* row_in = input + (size_t)r * row_len;
        float* row_out = output + (size_t)r * row_len;

        // ---------- pass 1: max and sum of exp ----------
        float local_max = -INFINITY;
        float local_sum = 0.0f;

        int n2 = row_len / 2;
        // Vectorized body: each thread reads 2 floats per step, stride 64.
        const float2* row2 = reinterpret_cast<const float2*>(row_in);
        for (int i = lane; i < n2; i += warp_size) {
            float2 v = row2[i];
            float a = fabsf(v.x);
            float b = fabsf(v.y);
            local_max = fmaxf(local_max, fmaxf(a, b));
        }
        // scalar tail
        for (int i = n2 * 2 + lane; i < row_len; i += warp_size) {
            local_max = fmaxf(local_max, fabsf(row_in[i]));
        }

        float gmax = warp_reduce_max(local_max, mask);
        // guard against -inf row (all NaN/unused) -> 0
        gmax = fmaxf(gmax, -88.0f);

        // second reduction pass: sum exp(x - gmax)
        local_sum = 0.0f;
        for (int i = lane; i < n2; i += warp_size) {
            float2 v = row2[i];
            local_sum += expf(fmaxf(fabsl(v.x) - gmax, -88.0f));
            local_sum += expf(fmaxf(fabsl(v.y) - gmax, -88.0f));
        }
        for (int i = n2 * 2 + lane; i < row_len; i += warp_size) {
            local_sum += expf(fmaxf(fabsf(row_in[i]) - gmax, -88.0f));
        }

        float gsum = warp_reduce_sum(local_sum, mask);
        float logsum = logf(gsum);

        // ---------- pass 2: write output ----------
        if (lane < n2) {
            for (int i = lane; i < n2; i += warp_size) {
                float2 v = row2[i];
                float2 o;
                o.x = fabsf(v.x) - gmax - logsum;
                o.y = fabsf(v.y) - gmax - logsum;
                (reinterpret_cast<float2*>(row_out))[i] = o;
            }
        }
        for (int i = n2 * 2 + lane; i < row_len; i += warp_size) {
            row_out[i] = fabsf(row_in[i]) - gmax - logsum;
        }
    }
}

