#include <cuda_runtime.h>

// Fused ReLU + Abs kernel.
//
// abs(relu(x)) == relu(x) == max(x, 0), so the two-op chain collapses to a
// single elementwise pass: read x once, write max(x, 0) once. That removes
// one full 1.07 GB read + 1.07 GB write round trip versus the unfused pair.
//
// Vectorization: float4 (16 bytes) loads/stores with a fixed grid of 1024
// blocks of 256 threads (4 warps of 64 on C500), grid-stride loop. This is
// the documented sweet spot on this device (~1300 GB/s vs ~600 GB/s for a
// scalar one-thread-per-element launch).
template<int BLOCK_SIZE>
__global__ void fused_relu_abs_impl(float* __restrict__ output,
                                    const float* __restrict__ input,
                                    long long size) {
    const long long tid = static_cast<long long>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const long long stride = static_cast<long long>(BLOCK_SIZE) * gridDim.x;

    // Vector body: 16 bytes per iteration per thread.
    const long long v_size = size >> 2;  // floor(size / 4)

    float4* out4 = reinterpret_cast<float4*>(output);
    const float4* in4 = reinterpret_cast<const float4*>(input);

    for (long long i = tid; i < v_size; i += stride) {
        float4 v = in4[i];
        v.x = fmaxf(v.x, 0.0f);
        v.y = fmaxf(v.y, 0.0f);
        v.z = fmaxf(v.z, 0.0f);
        v.w = fmaxf(v.w, 0.0f);
        out4[i] = v;
    }

    // Scalar tail for the (size % 4) remaining elements.
    const long long tail_base = v_size << 2;
    for (long long j = tid; j < (size - tail_base); j += stride) {
        output[tail_base + j] = fmaxf(input[tail_base + j], 0.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_relu_abs_launcher(
    float* output,
    const float* input,
    long long size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed 1024-block grid: enough waves to fill 104 SMs without the
    // fine-grained grid that measurably hurts this device.
    const int GRID = 1024;

    fused_relu_abs_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

