#include <cuda_runtime.h>

// Fused relu + abs: y = |max(x, 0)| = max(x, 0) (relu output is already
// non-negative, so abs is identity on it). Kept as explicit max(x,0) to
// preserve the original semantics exactly.
//
// Memory-bound: single pass over 268M floats. Uses float2 loads with a
// fixed GRID-blocks grid-stride loop (warp size 64, 104 SMs).

template<int BLOCK_SIZE>
__global__ void fused_relu_abs_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Scalar tail handled separately so the vector body is always aligned
    // and full (size is even here, but be safe).
    int vec_size = size & ~1;

    // float2 grid-stride: consecutive thread pairs touch consecutive 8B words
    // -> fully coalesced.
    for (int i = tid * 2; i < vec_size; i += stride * 2) {
        float2 v;
        v.x = input[i];
        v.y = input[i + 1];
        float2 r;
        r.x = fmaxf(v.x, 0.0f);
        r.y = fmaxf(v.y, 0.0f);
        output[i]     = r.x;
        output[i + 1] = r.y;
    }

    for (int i = vec_size + tid; i < size; i += stride) {
        output[i] = fmaxf(input[i], 0.0f);
    }
}

extern "C" void fused_relu_abs_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK = 256;          // 4 warps of 64 lanes
    const int GRID = 1024;          // fixed grid: ~2M elements per block
    fused_relu_abs_kernel<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        output, input, size
    );
}

