#include <cuda_runtime.h>

// Fused abs(x) -> hardsigmoid(x) for x >= 0 (abs guarantees non-negativity).
// hardsigmoid: clamp(x/6 + 0.5, 0, 1). Since x >= 0, x/6 + 0.5 >= 0.5 > 0,
// so only the upper clamp(x/6 + 0.5, max=1) matters -> branch-free.
// Memory-bound elementwise op: single pass, float2 vectorized loads,
// fixed grid-stride loop tuned for the C500 (warp size 64, 104 SMs).
template<int BLOCK_SIZE>
__global__ void abs_hardsigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    const int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Vectorized body: pairs of elements
    const int64_t vtid = tid * 2;
    const int64_t vstride = stride * 2;
    const int64_t vsize = size & ~1LL;

    for (int64_t i = vtid; i < vsize; i += vstride) {
        float2 in = *reinterpret_cast<const float2*>(input + i);
        float2 out;
        out.x = fminf(fabsf(in.x) * (1.0f / 6.0f) + 0.5f, 1.0f);
        out.y = fminf(fabsf(in.y) * (1.0f / 6.0f) + 0.5f, 1.0f);
        *reinterpret_cast<float2*>(output + i) = out;
    }

    // Tail element
    if (size & 1) {
        int64_t i = size - 1;
        if (tid == 0) {
            output[i] = fminf(fabsf(input[i]) * (1.0f / 6.0f) + 0.5f, 1.0f);
        }
    }
}

extern "C" void abs_hardsigmoid_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;  // 4 warps of 64 threads
    // Fixed 1024-block grid: 262144 threads, covers 512K elements per stride
    // iteration. Avoids the fine-grid trap (one thread/element) that caps out
    // around 600 GB/s on this device.
    const int GRID = 1024;

    int64_t vsize = size & ~1LL;
    if (vsize > 0) {
        abs_hardsigmoid_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    } else if (size > 0) {
        // Tiny input: single block is enough
        abs_hardsigmoid_kernel<256><<<1, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    }
}

