#include <cuda_runtime.h>

// Fused: abs(x) then ReLU6 = min(max(|x|, 0.f), 6.f)
// Both ops are branch-free and cheap -> single-pass memory-bound kernel.
// Uses float2 vectorized loads and a fixed grid of 1024 blocks with
// grid-stride loops (the configuration measured fastest on MetaX C500).
template<int BLOCK_SIZE>
__global__ void fused_abs_relu6_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size)
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = (BLOCK_SIZE * 1024) * 2;  // grid stride in elements

    int aligned = size & ~1;

    // Vectorized body: process 2 floats per thread iteration.
    for (int i = tid * 2; i < aligned; i += stride) {
        float2 v = *reinterpret_cast<const float2*>(input + i);
        v.x = fminf(fmaxf(fabsf(v.x), 0.0f), 6.0f);
        v.y = fminf(fmaxf(fabsf(v.y), 0.0f), 6.0f);
        *reinterpret_cast<float2*>(output + i) = v;
    }

    // Scalar tail for odd-length tensors.
    for (int i = aligned + tid; i < size; i += (BLOCK_SIZE * 1024)) {
        output[i] = fminf(fmaxf(fabsf(input[i]), 0.0f), 6.0f);
    }
}

extern "C" void fused_abs_relu6_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream)
{
    const int blocks = 1024;

    switch (config) {
        case 0:
            fused_abs_relu6_kernel<256><<<blocks, 256, 0, stream>>>(
                output, input, size);
            break;
        case 1:
            fused_abs_relu6_kernel<512><<<blocks, 512, 0, stream>>>(
                output, input, size);
            break;
        case 2:
            fused_abs_relu6_kernel<128><<<blocks, 128, 0, stream>>>(
                output, input, size);
            break;
        default:
            fused_abs_relu6_kernel<256><<<blocks, 256, 0, stream>>>(
                output, input, size);
    }
}

