#include <cuda_runtime.h>

// Fused abs + ReLU6: y = min(max(|x|, 0), 6) = min(|x|, 6) for the 6-clamp.
// Math preserved exactly from model.py:
//   x = torch.abs(x)
//   x = nn.ReLU6()(x)   -> clamp(x, 0, 6)
// Since |x| >= 0, the lower clamp is a no-op, so y = min(|x|, 6).
//
// Memory-bound on this device: use float4 vectorized loads/stores with a
// fixed grid of blocks (104 SMs * 12 blocks to fill ~2 waves) and a
// grid-stride loop, instead of one thread per element.

template<int BLOCK_SIZE>
__global__ void fused_abs_relu6_kernel(
    float4* __restrict__ output,
    const float4* __restrict__ input,
    size_t num_quads          // number of float4 elements
) {
    const size_t tid = (size_t)blockIdx.x * (size_t)BLOCK_SIZE + (size_t)threadIdx.x;
    const size_t stride = (size_t)BLOCK_SIZE * (size_t)gridDim.x;

    for (size_t i = tid; i < num_quads; i += stride) {
        float4 v = input[i];  // coalesced 16-byte load

        float4 r;
        r.x = fminf(fabsf(v.x), 6.0f);
        r.y = fminf(fabsf(v.y), 6.0f);
        r.z = fminf(fabsf(v.z), 6.0f);
        r.w = fminf(fabsf(v.w), 6.0f);

        output[i] = r;        // coalesced 16-byte store
    }
}

// Scalar tail kernel for the (rare) case where numel is not 4-aligned.
__global__ void fused_abs_relu6_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size,
    size_t offset
) {
    const size_t tid = (size_t)blockIdx.x * (size_t)blockDim.x + (size_t)threadIdx.x;
    const size_t stride = (size_t)blockDim.x * (size_t)gridDim.x;

    for (size_t i = tid; i < size; i += stride) {
        const size_t idx = offset + i;
        output[idx] = fminf(fabsf(input[idx]), 6.0f);
    }
}

extern "C" void fused_abs_relu6_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const size_t num_quads = size / 4;
    const size_t tail = size - num_quads * 4;

    if (num_quads > 0) {
        const int BLOCK_SIZE = 256;              // 4 warps of 64 threads
        // Fixed grid: fill the 104 SMs roughly 2x without over-launching.
        // Each block here streams via grid-stride, so a bounded grid keeps
        // the launch overhead low and the per-SM work deep.
        const int MAX_BLOCKS = 104 * 12;
        int blocks = (int)((num_quads + (size_t)BLOCK_SIZE - 1) / (size_t)BLOCK_SIZE);
        if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;

        fused_abs_relu6_kernel<256><<<blocks, BLOCK_SIZE, 0, stream>>>(
            reinterpret_cast<float4*>(output),
            reinterpret_cast<const float4*>(input),
            num_quads
        );
    }

    if (tail > 0) {
        const size_t offset = num_quads * 4;
        const int BLOCK_SIZE = 256;
        int blocks = (int)((tail + BLOCK_SIZE - 1) / BLOCK_SIZE);
        if (blocks > 128) blocks = 128;
        fused_abs_relu6_scalar_kernel<<<blocks, BLOCK_SIZE, 0, stream>>>(
            output, input, tail, offset
        );
    }
}

