#include <cuda_runtime.h>

// Fused ReLU -> Sigmoid: y = 1 / (1 + exp(-relu(x))).
// Vectorized float2 loads with a grid-stride loop over a fixed grid of
// 256 blocks * 256 threads. This coarse grid matches the 104 SMs of the
// MetaX C500 (avoiding the one-thread-per-element trap that only reaches
// ~600 GB/s) while the grid-stride loop covers any tensor size.

template<int BLOCK_SIZE>
__global__ void fused_relu_sigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;
    const int vec_size = size >> 1;

    // Vectorized pass: 2 floats per thread via float2.
    int i = tid;
    while (i < vec_size) {
        float2 in = *reinterpret_cast<const float2*>(input + (i << 1));
        float2 out;
        out.x = 1.0f / (1.0f + __expf(-fmaxf(in.x, 0.0f)));
        out.y = 1.0f / (1.0f + __expf(-fmaxf(in.y, 0.0f)));
        *reinterpret_cast<float2*>(output + (i << 1)) = out;
        i += stride;
    }

    // Tail element (odd count only): handled by the first thread.
    if ((size & 1) && tid == 0) {
        float v = input[size - 1];
        output[size - 1] = 1.0f / (1.0f + __expf(-fmaxf(v, 0.0f)));
    }
}

extern "C" void fused_relu_sigmoid_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    const int NUM_BLOCKS = 256;  // fixed coarse grid; grid-stride covers N
    fused_relu_sigmoid_kernel<BLOCK_SIZE><<<NUM_BLOCKS, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

