// kernels/fused_gelu_tanh.cu
// Fused: tanh(gelu_tanh(x)) where
//   gelu_tanh(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
//
// One global-memory pass instead of three (gelu, intermediate, tanh).
// The workload (268M floats = 1 GiB) is deeply bandwidth-bound, so we use
// float2 vectorized loads/stores with a fixed-size grid-stride loop:
// fine per-element grids measured only ~1/2 the bandwidth of this pattern
// on MetaX C500.

#include <cuda_runtime.h>

__device__ __forceinline__ float gelu_kernel(float x) {
    const float kSqrt2OverPi = 0.7978845608028654f;
    const float kCoeff = 0.044715f;
    float x3 = x * x * x;
    float inner = kSqrt2OverPi * (x + kCoeff * x3);
    return 0.5f * x * (1.0f + tanhf(inner));
}

template<int BLOCK_SIZE>
__global__ void fused_gelu_tanh_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    // Persistent-style grid-stride over float2 elements.
    unsigned long long tid = (unsigned long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride = (unsigned long long)BLOCK_SIZE * gridDim.x;

    unsigned long long n2 = size >> 1;  // number of float2 pairs

    // Main vectorized body: both lanes in bounds.
    for (unsigned long long i = tid; i < n2; i += stride) {
        float2 v = *reinterpret_cast<const float2*>(input + (i << 1));
        float2 r;
        r.x = tanhf(gelu_kernel(v.x));
        r.y = tanhf(gelu_kernel(v.y));
        *reinterpret_cast<float2*>(output + (i << 1)) = r;
    }

    // Tail: odd element count handled by the last pair only.
    if ((size & 1ULL) != 0ULL) {
        unsigned long long last = size - 1ULL;
        // Have a subset of threads handle it; thread 0 of each block suffices,
        // but use the first alive thread to avoid multiple blocks racing on
        // identical work -- all would write the same value, so it is safe.
        if (tid < (unsigned long long)BLOCK_SIZE) {
            float v = input[last];
            output[last] = tanhf(gelu_kernel(v));
        }
    }
}

extern "C" void fused_gelu_tanh_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    if (size == 0ULL) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 lanes on C500
    // Fixed ~1024-block grid: 1024 * 256 = 262144 threads striding over data.
    // On the 104-SM C500 this keeps every SM fed without an over-fine grid.
    const int GRID = 1024;

    fused_gelu_tanh_kernel<256><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

