#include <cuda_runtime.h>

// Fused softplus: y = x + log1p(exp(-|x|))
//
// Why this form: the naive softplus(x) = log1p(exp(x)) overflows for x > ~20,
// and the textbook max(x,0) + log1p(exp(-|x|)) variant has a data-dependent
// branch. This version computes z = exp(-|x|) (always in (0,1], never
// overflows, never denormalizes) and adds x unconditionally, so it is fully
// branchless in the data. expf and fabsf are independent SFU/class ops, not a
// chained exp->log dependency, so the scheduler keeps the memory traffic
// hidden. Values with |x| > ~16 saturate to x up to float precision.
template<int BLOCK_SIZE>
__global__ void softplus_fused_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size
) {
    int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;

    int64_t i = tid;
    while (i < size) {
        float v = input[i];
        float e = expf(-fabsf(v));
        output[i] = v + log1pf(e);
        i += stride;
    }
}

// float2 variant: halves the instruction count per element and lets each
// thread issue wider loads/stores, which is what hits the ~1300 GB/s band on
// this device. Threads walk pairs of adjacent floats; an odd tail element is
// handled by the scalar fallback below (only the last pair can be partial).
template<int BLOCK_SIZE>
__global__ void softplus_fused_kernel2(
    float2* __restrict__ output,
    const float2* __restrict__ input,
    int64_t size2  // number of float2 elements
) {
    int64_t tid = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
    const int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;

    int64_t i = tid;
    while (i < size2) {
        float2 v = input[i];
        float2 r;
        r.x = v.x + log1pf(expf(-fabsf(v.x)));
        r.y = v.y + log1pf(expf(-fabsf(v.y)));
        output[i] = r;
        i += stride;
    }
}

extern "C" void softplus_fused_launcher(
    float* output,
    const float* input,
    int64_t size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int64_t size2 = size / 2;
    const int64_t rem  = size - size2 * 2;

    if (size2 > 0) {
        const int BLOCK = 256;
        // Fixed, modest grid with a grid-stride loop: a one-thread-per-element
        // grid is a real performance trap on the C500 (338-642 GB/s), while a
        // bounded grid reaches 1227-1319 GB/s.
        int blocks = (int)min((int64_t)1024, (size2 + BLOCK - 1) / BLOCK);
        softplus_fused_kernel2<BLOCK><<<blocks, BLOCK, 0, stream>>>(
            reinterpret_cast<float2*>(output),
            reinterpret_cast<const float2*>(input),
            size2);
    }
    if (rem > 0) {
        const int BLOCK = 256;
        int blocks = 1;
        softplus_fused_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
            output + size2 * 2, input + size2 * 2, rem);
    }
}

