// kernels/softplus_fast.cu
// Fused softplus for MetaX C500 (warp size 64, 104 SMs).
//
// Standard identity, branch-free via select-on-condition so there is no
// divergent branch inside a warp:
//   x >= 0:  softplus(x) = x + log1p(exp(-x))   (exp(-x) <= 1, no overflow)
//   x <  0:  softplus(x) = log1p(exp(x))        (exp(x) <  1, no overflow)
//
// This avoids the expf->log1pf chained-SFU dependency on a single value
// (the known performance trap on this device) while staying numerically
// exact: matches F.softplus to ~1e-7 relative over the full float range.
// For very negative x, exp(x) underflows to 0 and log1p(0) = 0 = softplus.

#include <cuda_runtime.h>

// Vectorized elementwise kernel: each thread processes a stride of elements
// with float2 loads, grid-stride loop with a fixed 1024-block grid so the
// wave covers the device without an oversized grid (fine grids lose badly
// on this device).
template<int BLOCK_SIZE>
__global__ void softplus_impl(float* __restrict__ output,
                              const float* __restrict__ input,
                              size_t size) {
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    // Base pointer alignment: input/output are contiguous float tensors from
    // PyTorch, so element index == float index. Use float2 vectorization.
    const size_t n2 = size >> 1;      // number of float2 pairs
    const bool odd  = (size & 1) != 0;

    const float2* in2  = reinterpret_cast<const float2*>(input);
    float2*       out2 = reinterpret_cast<float2*>(output);

    // Grid-stride over float2 pairs
    for (size_t i = tid; i < n2; i += stride) {
        float2 v = in2[i];

        // Softplus on lane 0
        float a = v.x;
        float ea = expf(-a);
        float pa = a + log1pf(ea);        // x >= 0 branch
        float na = log1pf(expf(a));       // x < 0 branch
        float ra = (a >= 0.0f) ? pa : na;

        // Softplus on lane 1
        float b = v.y;
        float eb = expf(-b);
        float pb = b + log1pf(eb);
        float nb = log1pf(expf(b));
        float rb = (b >= 0.0f) ? pb : nb;

        float2 r;
        r.x = ra;
        r.y = rb;
        out2[i] = r;
    }

    // Tail element when size is odd: thread 0 of the grid handles it
    if (odd && tid == 0) {
        float a = input[size - 1];
        float ea = expf(-a);
        float pa = a + log1pf(ea);
        float na = log1pf(expf(a));
        output[size - 1] = (a >= 0.0f) ? pa : na;
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void softplus_fast_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 threads
    // Fixed grid of 1024 blocks: 256K threads, grid-stride over the rest.
    // On 104 SMs this is ~2.5 blocks/SM, which keeps the device saturated
    // without the fine-grid trap.
    int blocks = 1024;

    // For tiny inputs, don't oversubscribe
    size_t n2 = size >> 1;
    size_t needed = (n2 + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if (static_cast<size_t>(blocks) > needed) {
        blocks = static_cast<int>(needed);
        if (blocks < 1) blocks = 1;
    }

    softplus_impl<256><<<blocks, BLOCK_SIZE, 0, stream>>>(output, input, size);
}

