// kernels/fused_div_sigmoid.cu
// Fused: x = x / 2.0; x = sigmoid(x)
// sigmoid(x) = 1.0f / (1.0f + expf(-x))
//
// Memory-bound elementwise chain: one fused pass reads N floats and writes N
// floats instead of 2N/2N for the unfused pair. Uses float2 vectorized loads
// with a fixed 1024-block grid-stride loop (coarse grid avoids the fine-grid
// throughput trap on this device).

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_div_sigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // float2 vectorized grid-stride loop
    int aligned_size = size & ~1;  // largest even count <= size
    int2 pos = make_int2(tid, 0);

    // Treat pairs: element index 2*tid + 2*k*stride
    int pair_stride = stride;      // pairs advanced per grid step
    int num_pairs = aligned_size >> 1;

    float2 in0;
    bool can_vectorize = ((reinterpret_cast<size_t>(input) & 7) == 0) &&
                         ((reinterpret_cast<size_t>(output) & 7) == 0);

    if (can_vectorize) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);

        for (int p = tid; p < num_pairs; p += pair_stride) {
            in0 = __ldg(&in2[p]);
            float2 res;
            float a = in0.x * 0.5f;
            float b = in0.y * 0.5f;
            res.x = 1.0f / (1.0f + __expf(-a));
            res.y = 1.0f / (1.0f + __expf(-b));
            out2[p] = res;
        }
        // Tail element (odd size)
        if (tid == 0 && (size & 1)) {
            float v = input[size - 1] * 0.5f;
            output[size - 1] = 1.0f / (1.0f + __expf(-v));
        }
    } else {
        // Scalar fallback for unaligned buffers
        for (int i = tid; i < size; i += stride) {
            float v = input[i] * 0.5f;
            output[i] = 1.0f / (1.0f + __expf(-v));
        }
    }
}

extern "C" void fused_div_sigmoid_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    // Fixed, coarse grid: 1024 blocks of 256 threads = 262144 lanes,
    // grid-stride loop covers any size. Avoids the fine-grid (one block per
    // tiny tile) throughput trap observed on this device.
    int grid = 1024;
    long long total_elems = (long long)size;
    long long needed = (total_elems + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if ((long long)grid > needed) {
        grid = (int)needed;
        if (grid < 1) grid = 1;
    }

    fused_div_sigmoid_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

