#include <cuda_runtime.h>

// Fused: out = sigmoid(x / 2.0)
// Memory-bound elementwise chain: single pass over input, float2 vectorized,
// fixed 1024-block grid-stride loop (matches the pattern that reaches
// ~1300 GB/s on the C500).
template<int BLOCK_SIZE>
__global__ void fused_div_sigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const float scale = 0.5f;
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized body: pairs of elements per thread iteration.
    int vec_size = size >> 1;
    for (int i = tid; i < vec_size; i += stride) {
        float2 v = *reinterpret_cast<const float2*>(input + (i << 1));
        float2 r;
        r.x = 1.0f / (1.0f + expf(-v.x * scale));
        r.y = 1.0f / (1.0f + expf(-v.y * scale));
        *reinterpret_cast<float2*>(output + (i << 1)) = r;
    }

    // Tail: odd element count handled by a single thread per block.
    if ((size & 1) != 0) {
        int last = size - 1;
        if (tid < blockDim.x && (tid == 0)) {
            float v = input[last];
            output[last] = 1.0f / (1.0f + expf(-v * scale));
        }
    }
}

extern "C" void fused_div_sigmoid_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK_SIZE = 256;
    const int MAX_BLOCKS = 1024;
    int pairs = (size + 1) >> 1;
    int blocks = (pairs + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;
    if (blocks < 1) blocks = 1;

    fused_div_sigmoid_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

