#include <cuda_runtime.h>
#include <cstdint>

// Fused SELU + trunc, single pass over memory.
// SELU:  x > 0 : scale * x
//        x <= 0: scale * alpha * (expm1(x))   [alpha=1.6732632423543772, scale=1.0507009873554805]
// trunc: round-toward-zero of selu(x).
//
// Both ops are branch-free/cheap on the SFU path; no chained-SFU dependency,
// so the arithmetic hides completely behind memory traffic. The whole chain
// costs one read + one write instead of two full passes.

template<int BLOCK_SIZE, int VEC>
__global__ void fused_selu_trunc_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t num_elements
) {
    // Vectorized grid-stride loop: fixed ~1024-block grid so we do not fall
    // into the fine-grid trap on this device (1 thread/element reached only
    // ~600 GB/s, float2/float4 grid-stride reaches ~1300 GB/s).
    static_assert((BLOCK_SIZE % 64) == 0, "block size must be a multiple of warp size (64)");

    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;
    const size_t vec_count = num_elements / VEC;

    const float kAlpha = 1.6732632423543772f;
    const float kScale = 1.0507009873554805f;
    const float kScaleAlpha = kScale * kAlpha;

#define SELU_TRUNC_SCALAR(v)                                                    \
    ({                                                                          \
        float vv = (v);                                                         \
        float neg = kScaleAlpha * expm1f(vv);                                   \
        float pos = kScale * vv;                                                \
        float s = (vv > 0.0f) ? pos : neg;                                      \
        float t;                                                                \
        if (s == 0.0f || isinf(s)) {                                            \
            t = s;                                                              \
        } else {                                                                \
            t = static_cast<float>(static_cast<long long int>(s));              \
        }                                                                       \
        t;                                                                      \
    })

    if (VEC == 4) {
        size_t i = tid;
        // float4 body
        for (; i < vec_count; i += stride) {
            size_t base = i * 4;
            float4 a;
            const float4* in4 = reinterpret_cast<const float4*>(input + base);
            a = __ldg(in4);

            float4 r;
            r.x = SELU_TRUNC_SCALAR(a.x);
            r.y = SELU_TRUNC_SCALAR(a.y);
            r.z = SELU_TRUNC_SCALAR(a.z);
            r.w = SELU_TRUNC_SCALAR(a.w);

            *reinterpret_cast<float4*>(output + base) = r;
        }

        // Scalar tail
        size_t tail_start = vec_count * 4;
        for (size_t j = tail_start + tid; j < num_elements; j += stride) {
            output[j] = SELU_TRUNC_SCALAR(input[j]);
        }
    } else {
        size_t i = tid;
        for (; i < num_elements; i += stride) {
            output[i] = SELU_TRUNC_SCALAR(input[i]);
        }
    }

#undef SELU_TRUNC_SCALAR
}

extern "C" void fused_selu_trunc_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const int BLOCK_SIZE = 256;      // 4 warps of 64
    const int VEC = 4;
    const int MAX_BLOCKS = 1024;

    size_t vec_count = size / VEC;
    int blocks = static_cast<int>((vec_count + BLOCK_SIZE - 1) / BLOCK_SIZE);
    if (blocks < 1) blocks = 1;
    if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;

    fused_selu_trunc_kernel<256, 4><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

