// kernels/fused_selu_trunc.cu
// Fused SELU + trunc on MetaX C500.
//
// Performance notes (MACA / C500):
//  - Warp size is 64, 104 SMs. A scalar one-thread-per-element grid is a
//    documented trap here (338-642 GB/s); fixed 1024-block grid-stride with
//    float2 loads reaches 1227-1319 GB/s against a ~1350 GB/s copy ceiling.
//  - selu has an expm1 branch (exp->(+1) chain, single SFU dependency), but it
//    is data-dependent per element so the warp issues independent work across
//    lanes; vectorizing by 2 gives each thread two independent elements.
//
// Math is identical to the reference: torch.selu followed by torch.trunc.

#include <cuda_runtime.h>

#defineMC_SENDU_ALPHA  1.0507009873554804934193349852946f
#define SELU_SCALE 1.6732632423543772848176029513101f

__device__ __forceinline__ float selu_scalar(float v) {
    // torch.selu: alpha * (exp(x)-1) if x < 0 else x
    float r = SELU_SCALE * (expm1f(v) - 1.0f);
    return (v < 0.0f) ? r : v;
}

template<int BLOCK_SIZE>
__global__ void fused_selu_trunc_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    // Aligned float2 portion
    const int n2 = (size >> 1) << 1;  // largest even <= size
    for (int i = tid; i < n2; i += stride) {
        float2 in = reinterpret_cast<const float2*>(input)[i];
        float2 out;
        out.x = truncf(selu_scalar(in.x));
        out.y = truncf(selu_scalar(in.y));
        reinterpret_cast<float2*>(output)[i] = out;
    }

    // Tail element (odd sizes), handled by the first threads
    if (n2 < size) {
        if (tid == 0 || tid * 2 < size) {
            int idx = (tid == 0) ? n2 : tid * 2;
            if (idx < size && idx >= n2) {
                output[n2] = truncf(selu_scalar(input[n2]));
            }
        }
    }
}

extern "C" void fused_selu_trunc_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = (config > 0) ? config : 256;
    const int GRID = 1024;

    switch (BLOCK_SIZE) {
        case 128:
            fused_selu_trunc_kernel<128><<<GRID, 128, 0, stream>>>(output, input, size);
            break;
        case 512:
            fused_selu_trunc_kernel<512><<<GRID, 512, 0, stream>>>(output, input, size);
            break;
        case 1024:
            fused_selu_trunc_kernel<1024><<<GRID, 1024, 0, stream>>>(output, input, size);
            break;
        case 256:
        default:
            fused_selu_trunc_kernel<256><<<GRID, 256, 0, stream>>>(output, input, size);
            break;
    }
}

