// x: (B, 2C, H, W) contiguous float (any dtype normalized to float32)
// out: (B, C, H, W)
torch::Tensor fused_cos_glu_forward(torch::Tensor x) {
    if (!x.is_cuda()) x = x.to(torch::kCUDA);
    if (x.dtype() != torch::kFloat32) x = x.to(torch::kFloat32);
    x = x.contiguous();

    TORCH_CHECK(x.dim() == 4, "x must be 4-D (B, 2C, H, W)");

    const long long B = x.size(0);
    const long long C2 = x.size(1);
    const long long H  = x.size(2);
    const long long W  = x.size(3);
    const long long C = C2 / 2;
    TORCH_CHECK(C2 % 2 == 0, "channel dim must be even for GLU");

    auto out = torch::empty({B, C, H, W}, x.options());

    const long long row_elems = H * W;                 // elements per (b,c) row
    const long long num_in  = x.numel();               // B*2C*H*W
    const long long num_out = out.numel();             // B*C*H*W

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    fused_cos_glu_launcher(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        num_in,
        num_out,
        C * row_elems,   // half_c: elements in the "a/b" half of one batch item
        row_elems,
        stream
    );

