// kernels/fused_cos_glu.cu
// Fused cos(x) followed by GLU over dim=1.
//
// Model:  x -> cos(x);  GLU: split channels in half (a, b),
//         out = a * sigmoid(b).
// Input (B, 2C, H, W) float32 contiguous; output (B, C, H, W).
//
// Both ops are pure elementwise with no reductions, so a single pass halves
// the DRAM traffic vs. two separate kernels. Vectorized float2 grid-stride
// loop with a fixed 1024-block grid (coarse grid is important on C500: a
// one-thread-per-element grid reached only ~0.5x the bandwidth).
//
// Indexing: the output is a *restride* of the input, so we linearize the
// output index and map it back to the input. For output element
//   k = b*(C*R) + c*R + r      (R = H*W, C = half the channels)
// the inputs needed are
//   a = x[b*(2C*R) + (c)*R + r]      (first half)
//   b = x[b*(2C*R) + (C + c)*R + r]  (second half)
// so a and b are exactly half_c = C*R apart in the linear input array.

#include <cuda_runtime.h>

template<int BLOCK>
__global__ void fused_cos_glu_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    long long num_out,
    long long half_c,
    long long row_elems)
{
    const long long base = (long long)blockIdx.x * (long long)BLOCK * 2 +
                           (long long)threadIdx.x * 2;
    const long long stride = (long long)blockDim.x * gridDim.x * 2LL;

    for (long long k = base; k < num_out; k += stride) {
        // Each thread handles two consecutive output elements.
        long long k0 = k;
        long long k1 = k + 1;

        // Decompose output index into (b, c, r) for the two elements.
        long long bin0 = k0 / half_c;
        long long rem0 = k0 - bin0 * half_c;      // c*R + r
        long long bin1 = k1 / half_c;
        long long rem1 = k1 - bin1 * half_c;

        long long ibase0 = bin0 * (half_c * 2);
        long long ibase1 = bin1 * (half_c * 2);

        long long c0 = rem0 / row_elems;
        long long r0 = rem0 - c0 * row_elems;
        long long c1 = rem1 / row_elems;
        long long r1 = rem1 - c1 * row_elems;

        float2 va, vb;
        va.x = in[ibase0 + c0 * row_elems + r0];
        va.y = in[ibase1 + c1 * row_elems + r1];   // likely same cache line as va.x
        vb.x = in[ibase0 + half_c + c0 * row_elems + r0];
        vb.y = in[ibase1 + half_c + c1 * row_elems + r1];

        // out = cos(a) * sigmoid(b)
        float2 res;
        res.x = cosf(va.x) / (1.0f + expf(-vb.x));
        res.y = cosf(va.y) / (1.0f + expf(-vb.y));

        *reinterpret_cast<float2*>(out + k) = res;
    }
}

extern "C" void fused_cos_glu_launcher(
    const float* __restrict__ in,
    float* __restrict__ out,
    long long num_in,
    long long num_out,
    long long half_c,
    long long row_elems,
    cudaStream_t stream)
{
    (void)num_in;
    const int BLOCK = 256;
    // Fixed, coarse grid: ~1M threads covers the whole tensor with a
    // grid-stride loop. Oversubscribing per-element was a measured trap.
    const int GRID = 1024;
    fused_cos_glu_kernel<BLOCK><<<GRID, BLOCK, 0, stream>>>(
        in, out, num_out, half_c, row_elems);
}

