#include <cuda_runtime.h>

// One persistent-ish block-grid, grid-stride over float2 pairs.
// Threads walk consecutive pairs so loads/stores are 8-byte aligned & coalesced.
template<int VEC>
__global__ void fused_cos_glu_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int num_pairs)   // pairs of floats = output elements
{
    const int stride = blockDim.x * gridDim.x;
    for (int idx = blockIdx.x * blockDim.x + threadIdx.x;
         idx < num_pairs;
         idx += stride)
    {
        const int a = idx << 1;           // index of first float in the pair
        const float x0 = in[a];           // gate  (a branch -> gate, b -> value)
        const float x1 = in[a + 1];

        // cos on both halves, then GLU split
        const float g = cosf(x0);
        const float v = cosf(x1);

        // GLU: a * sigmoid(b)
        const float s = 1.0f / (1.0f + expf(-v));

        out[idx] = g * s;
    }
}

extern "C" void fused_cos_glu_kernelLauncher(
    const float* __restrict__ in,
    float* __restrict__ out,
    int N,
    int half,
    cudaStream_t stream)
{
    const int threads = 256;
    const int blocks = 1024;
    fused_cos_glu_kernel<1><<<blocks, threads, 0, stream>>>(in, out, half);
}

