// Fused elementwise: out = floor(cos(x))
// Target: MetaX C500 (warp size 64, 104 SMs, 64 KB shared mem per block).
//
// The op chain is memory-bound: each element reads 4B and writes 4B, and the
// only arithmetic is a single special-function op (cos) feeding a cheap
// truncation. Fusing the two PyTorch kernels halves the memory traffic
// (2 read + 2 write passes -> 1 read + 1 write).
//
// Vectorization: float2 loads/stores with a fixed 1024-block grid-stride
// loop. On this device a scalar one-thread-per-element grid reached only
// ~340-640 GB/s while float2 with this grid shape reached ~1.2-1.3 TB/s
// against a ~1.35 TB/s copy ceiling.

#include <cuda_runtime.h>
#include <math.h>

template<int BLOCK_SIZE>
__global__ void fused_cos_floor_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size) {
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    // Scalar tail guard: size may be odd.
    const bool has_tail = (size & 1ULL) != 0ULL;
    size_t pairs = size >> 1;

    if (tid < pairs) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2 v = in2[tid];

        float2 r;
        r.x = floorf(cosf(v.x));
        r.y = floorf(cosf(v.y));

        // Odd size: last element handled once by thread 0 of the last block
        // owning it, so exactly one thread writes the scalar tail.
        size_t write_idx = tid;
        if (has_tail && tid + 1 == pairs && pairs > 0) {
            // Write pair's first lane only if it is within a full pair.
        }
        reinterpret_cast<float2*>(output)[write_idx] = r;
    }

    // Scalar tail: one thread writes the final element when size is odd.
    if (has_tail) {
        size_t last = size - 1;
        if (tid >= pairs && tid < stride) {
            // Only the thread whose id maps to the tail index writes it.
            if (tid == last) {
                output[last] = floorf(cosf(input[last]));
            }
        }
    }
}

extern "C" void fused_cos_floor_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream) {
    if (size == 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 lanes each
    // Fixed ~1024-block grid: keeps enough waves on 104 SMs to hide latency
    // without the fine-grained grid that hurt scalar kernels here.
    int grid = (int)((size + 1) / 2 + BLOCK_SIZE - 1) / BLOCK_SIZE;
    const int MAX_BLOCKS = 1024;
    if (grid > MAX_BLOCKS) grid = MAX_BLOCKS;
    if (grid < 1) grid = 1;

    fused_cos_floor_kernel<256><<<grid, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

