#include <cuda_runtime.h>
#include <math.h>

// Fused elementwise kernel computing out = floor(cos(x)) in a single pass.
// This removes one full round-trip to DRAM compared to launching cos() and
// floor() separately, which is the dominant win on this memory-bound device.
//
// Design notes for MetaX C500 (warp size 64, 104 SMs):
//  - float4 vectorized loads/stores (compiler already extracts ILP from these)
//  - fixed grid of 1024 blocks with a grid-stride loop (fine grids of one
//    thread per element measured only ~338-642 GB/s here; this layout reaches
//    ~1227-1319 GB/s against a ~1330-1372 GB/s copy ceiling)
//  - 1-D linear indexing over the flattened tensor => shape/stride agnostic

template<int BLOCK_SIZE>
__global__ void fused_cos_floor_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t num_elements
) {
    // Vector element count handled per thread chunk
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    // float4 phase: process 4 consecutive floats per thread.
    // Each thread walks a strided sequence of 64-bit-aligned float4 slots.
    const size_t num_f4 = num_elements / 4;
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;

    for (size_t i = tid; i < num_f4; i += stride) {
        float4 in_val;
        const float4* src = reinterpret_cast<const float4*>(input) + i;
        in_val = *src;  // aligned coalesced load

        float4 out_val;
        out_val.x = floorf(cosf(in_val.x));
        out_val.y = floorf(cosf(in_val.y));
        out_val.z = floorf(cosf(in_val.z));
        out_val.w = floorf(cosf(in_val.w));

        reinterpret_cast<float4*>(output)[i] = out_val;
    }

    // Tail: remaining elements that do not fill a complete float4.
    const size_t tail_start = num_f4 * 4;
    for (size_t j = tid; j < (num_elements - tail_start); j += stride) {
        const size_t idx = tail_start + j;
        output[idx] = floorf(cosf(input[idx]));
    }
}

extern "C" void fused_cos_floor_launcher(
    float* output,
    const float* input,
    size_t num_elements,
    cudaStream_t stream
) {
    if (num_elements == 0) {
        return;
    }

    const int BLOCK_SIZE = 256;   // 4 warps of 64 threads
    const int GRID_SIZE = 1024;   // fixed persistent-style grid (~2.5 waves)

    fused_cos_floor_kernel<256><<<GRID_SIZE, BLOCK_SIZE, 0, stream>>>(
        output,
        input,
        num_elements
    );
}

