// kernels/fused_gelu_hardswish.cu
// Fused elementwise: GELU (tanh approximation) followed by HardSwish.
// x -> 0.5*x*(1 + tanh(sqrt(2/pi)*(x + 0.044715*x^3)))
//   -> clamp(y+3, 0, 6) * y / 6
// Single pass: 1 read + 1 write instead of 3 full tensor round-trips.

#include <cuda_runtime.h>

namespace {

__device__ __forceinline__ float gelu_tanh_core(float x) {
    const float kSqrt2Pi = 0.7978845608028654f;  // sqrt(2/pi)
    const float kCoef    = 0.044715f;
    // x + 0.044715*x^3 == x*(1 + 0.044715*x^2)
    float x2 = x * x;
    float inner = kSqrt2Pi * x * (1.0f + kCoef * x2);
    float t = tanhf(inner);
    return 0.5f * x * (1.0f + t);
}

__device__ __forceinline__ float hardswish_core(float x) {
    // relu6(x+3) * x / 6, branch-free clamp
    float a = x + 3.0f;
    a = fminf(fmaxf(a, 0.0f), 6.0f);
    return a * x * 0.16666667f;
}

template<int BLOCK_SIZE>
__global__ void fused_gelu_hardswish_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // float2 vectorized grid-stride loop; fixed grid sized to ~fill the device
    // (104 SMs) rather than one thread per element, which is a perf trap here.
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_threads = blockDim.x * gridDim.x;

    const int n2 = size >> 1;
    int idx = tid;

    // Vectorized body: pairs of consecutive elements per thread iteration.
    for (; idx < n2; idx += total_threads) {
        int base = idx << 1;
        float2 in;
    #if defined(__MACA__) || 1
        // reinterpret_cast load keeps the compiler from lowering to ld.global.f32
        in = *reinterpret_cast<const float2*>(input + base);
    #endif
        float2 out;
        out.x = hardswish_core(gelu_tanh_core(in.x));
        out.y = hardswish_core(gelu_tanh_core(in.y));
        *reinterpret_cast<float2*>(output + base) = out;
    }

    // Scalar tail for odd element count.
    int scalar_idx = n2 + tid;
    if (scalar_idx < size) {
        float v = input[scalar_idx];
        output[scalar_idx] = hardswish_core(gelu_tanh_core(v));
    }
}

}  // namespace

extern "C" void fused_gelu_hardswish_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int SM_COUNT = 104;   // MetaX C500
    // config 0: 256 threads/block x 2048 blocks (~full-device grid, float2)
    // config 1: 128 threads/block x 2048 blocks
    // config 2: 512 threads/block x 1024 blocks
    switch (config) {
        case 1: {
            const int BLOCK = 128;
            int blocks = SM_COUNT * 16;
            fused_gelu_hardswish_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        case 2: {
            const int BLOCK = 512;
            int blocks = SM_COUNT * 8;
            fused_gelu_hardswish_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
        default: {
            const int BLOCK = 256;
            int blocks = SM_COUNT * 8;   // 832 blocks
            fused_gelu_hardswish_kernel<BLOCK><<<blocks, BLOCK, 0, stream>>>(
                output, input, size);
            break;
        }
    }
}

