// kernels/fused_gelu_hardswish.cu
// Fused GELU (tanh approximation) followed by HardSwish.
// Memory-bound elementwise chain: single pass over x, float2 vectorized loads,
// fixed 1024-block grid-stride loop sized for 104 SMs (warp size 64).
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__device__ __forceinline__ float gelu_core(float x) {
    // PyTorch approximate GELU: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
    const float c = 0.7978845608028654f;   // sqrt(2/pi)
    const float a = 0.044715f;
    float x2 = x * x;
    float x3 = x2 * x;
    float u  = c * (x + a * x3);
    float t  = tanhf(u);
    return 0.5f * x * (1.0f + t);
}

template<int BLOCK_SIZE>
__global__ void fused_gelu_hardswish_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size)
{
    const float scale = 1.0f / 6.0f;
    // Vectorized body: pairs of elements per thread.
    int tid  = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int step = gridDim.x * BLOCK_SIZE;

    int pairs = size >> 1;
    for (int i = tid; i < pairs; i += step) {
        int idx = i << 1;
        float2 v = *reinterpret_cast<const float2*>(input + idx);
        float2 r;
        r.x = gelu_core<BLOCK_SIZE>(v.x);
        r.y = gelu_core<BLOCK_SIZE>(v.y);
        // HardSwish: x * clamp(x + 3, 0, 6) / 6
        float h0 = r.x + 3.0f;
        h0 = h0 < 0.0f ? 0.0f : (h0 > 6.0f ? 6.0f : h0);
        float h1 = r.y + 3.0f;
        h1 = h1 < 0.0f ? 0.0f : (h1 > 6.0f ? 6.0f : h1);
        float2 o;
        o.x = r.x * h0 * scale;
        o.y = r.y * h1 * scale;
        *reinterpret_cast<float2*>(output + idx) = o;
    }

    // Tail: odd element count.
    if (tid + (pairs << 1) == size && (size & 1)) {
        int idx = size - 1;
        float x = input[idx];
        float g = gelu_core<BLOCK_SIZE>(x);
        float h = g + 3.0f;
        h = h < 0.0f ? 0.0f : (h > 6.0f ? 6.0f : h);
        output[idx] = g * h * scale;
    }
}

extern "C" void fused_gelu_hardswish_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream)
{
    const int blocks = 1024;
    switch (config) {
        case 0:
            fused_gelu_hardswish_kernel<256><<<blocks, 256, 0, stream>>>(output, input, size);
            break;
        case 1:
            fused_gelu_hardswish_kernel<128><<<blocks, 128, 0, stream>>>(output, input, size);
            break;
        case 2:
            fused_gelu_hardswish_kernel<512><<<blocks, 512, 0, stream>>>(output, input, size);
            break;
        default:
            fused_gelu_hardswish_kernel<256><<<blocks, 256, 0, stream>>>(output, input, size);
            break;
    }
}

