// kernels/fused_log_tanh.cu
// Fused: y = tanh(log(x))
//
// Design notes for MetaX C500 (warp size 64, 104 SMs):
//  - Single memory pass: read x once, write y once.
//  - float2 vectorized loads/stores with a fixed ~1024-block grid-stride
//    loop. Fine-grained grids (one thread per element) trap at low
//    throughput on this device; a coarse grid reaches the copy ceiling.
//  - Scalar tail handled separately for odd element counts.
//  - Domain guard: clamp the log argument to a tiny positive value so that
//    x == 0 (torch.rand can return exactly 0) maps to a large negative
//    log, whose tanh saturates to -1 ... matching torch's -inf -> -1 only
//    in the limit, but staying finite and within tolerance everywhere.
//    For x < 0 (outside log's domain) torch returns nan; we reproduce
//    that explicitly so the outputs agree elementwise.

#include <cuda_runtime.h>
#include <math.h>

__device__ __forceinline__ float stable_tanh(float z) {
    // tanh(z) = 1 - 2/(exp(2z) + 1), computed without overflow for |z| large.
    // For z very negative, exp(2z) underflows to 0 and the result is -1.
    // For z very positive, exp(2z) may overflow to +inf, giving 1 - 0 = 1.
    float w = expf(2.0f * z);
    return 1.0f - 2.0f / (w + 1.0f);
}

__device__ __forceinline__ float fused_log_tanh_scalar(float x) {
    // Explicitly propagate nan for non-positive x, same as torch.log.
    if (!(x > 0.0f)) {
        // covers x == 0 (-inf in torch) and x < 0 (nan in torch)
        if (x == 0.0f) {
            // log(0) = -inf, tanh(-inf) = -1
            return -1.0f;
        }
        return NAN; // nan propagates: log(negative) = nan, tanh(nan) = nan
    }
    float lx = logf(x);
    return stable_tanh(lx);
}

// Vectorized body: each thread handles one float2 per stride iteration.
__global__ void fused_log_tanh_vec2_kernel(
    float2* __restrict__ output,
    const float2* __restrict__ input,
    unsigned long long num_pairs
) {
    const unsigned long long tid =
        (unsigned long long)blockIdx.x * (unsigned long long)blockDim.x
        + (unsigned long long)threadIdx.x;
    const unsigned long long stride =
        (unsigned long long)blockDim.x * (unsigned long long)gridDim.x;

    for (unsigned long long i = tid; i < num_pairs; i += stride) {
        float2 v = input[i];
        float2 r;
        r.x = fused_log_tanh_scalar(v.x);
        r.y = fused_log_tanh_scalar(v.y);
        output[i] = r;
    }
}

// Scalar tail for the odd element (if any) and a fully scalar fallback.
__global__ void fused_log_tanh_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    const unsigned long long tid =
        (unsigned long long)blockIdx.x * (unsigned long long)blockDim.x
        + (unsigned long long)threadIdx.x;
    const unsigned long long stride =
        (unsigned long long)blockDim.x * (unsigned long long)gridDim.x;

    for (unsigned long long i = tid; i < size; i += stride) {
        output[i] = fused_log_tanh_scalar(input[i]);
    }
}

extern "C" void fused_log_tanh_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const unsigned long long num_pairs = size / 2ULL;
    const unsigned long long tail = size - num_pairs * 2ULL;

    if (num_pairs > 0) {
        const int block = 256;                 // 4 warps of 64
        // Coarse, fixed grid: ~1024 blocks covers the device (104 SMs)
        // and keeps the grid-stride loop vectors large.
        int grid = (int)((num_pairs + (unsigned long long)block - 1ULL)
                         / (unsigned long long)block);
        const int max_grid = 1024;
        if (grid > max_grid) grid = max_grid;

        fused_log_tanh_vec2_kernel<<<grid, block, 0, stream>>>(
            reinterpret_cast<float2*>(output),
            reinterpret_cast<const float2*>(input),
            num_pairs
        );
    }

    if (tail > 0) {
        // Handle the final element in-place; only one element can be left.
        const int block = 64;
        fused_log_tanh_scalar_kernel<<<1, block, 0, stream>>>(
            output + (long long)(num_pairs * 2ULL),
            input + (long long)(num_pairs * 2ULL),
            tail
        );
    }
}

