// kernels/fused_relu_clamp.cu
// Fused elementwise: relu(x) followed by Hardtanh(-1, 1).
// Mathematically collapses to the branch-free min(max(x, 0), 1),
// computed in a single memory pass with float2 vectorized loads/stores.
#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__global__ void fused_relu_clamp_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    // Vectorized body: each thread handles 2 floats per iteration.
    const size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    const size_t v_size = size >> 1;  // number of complete float2 pairs

    if (sizeof(float2) == 8 && ((reinterpret_cast<uintptr_t>(input) & 7u) == 0u)) {
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);

        for (size_t i = tid; i < v_size; i += stride) {
            float2 v = in2[i];
            v.x = fminf(fmaxf(v.x, 0.0f), 1.0f);
            v.y = fminf(fmaxf(v.y, 0.0f), 1.0f);
            out2[i] = v;
        }

        // Scalar tail for odd element counts
        if ((size & 1u) != 0u) {
            const size_t tail = size - 1;
            for (size_t i = tid; i <= tail; i += stride) {
                output[i] = fminf(fmaxf(input[i], 0.0f), 1.0f);
            }
        }
    } else {
        // Unaligned fallback
        for (size_t i = tid; i < size; i += stride) {
            output[i] = fminf(fmaxf(input[i], 0.0f), 1.0f);
        }
    }
}

extern "C" void fused_relu_clamp_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0u) return;

    // Fixed ~1024-block grid-stride loop: on this device a fine grid
    // (one block per small tile) caps out at ~600 GB/s, while a fixed
    // 1024-block grid with float2 reaches ~1300 GB/s.
    constexpr int BLOCK_SIZE = 256;   // 4 warps of 64 threads each
    constexpr int GRID_BLOCKS = 1024;

    // 512 elements per block-iteration (256 threads x float2)
    if (size >= 512u) {
        fused_relu_clamp_kernel<BLOCK_SIZE><<<GRID_BLOCKS, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    } else {
        // Small inputs: avoid overshooting the grid
        const int blocks = (static_cast<int>(size) + BLOCK_SIZE - 1) / BLOCK_SIZE;
        fused_relu_clamp_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, 0, stream>>>(
            output, input, size);
    }
}

