#include <cuda_runtime.h>

// relu(x) then hardtanh clamp to [-1, 1].
// One pass over memory: y = clamp(max(x, 0), -1, 1).
// Vectorized float2 loads with a fixed 1024-block grid-stride loop
// (256 threads * 2 elems * 1024 blocks) to keep all 104 SMs fed.
__global__ void fused_relu_hardtanh_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    const int aligned = (size / 2) * 2;

    // float2 body: coalesced 8-byte loads/stores
    for (int i = tid; i < aligned / 2; i += stride) {
        float2 in = *reinterpret_cast<const float2*>(input + 2 * i);
        float2 out;
        out.x = fminf(fmaxf(in.x, 0.0f), 1.0f);
        out.y = fminf(fmaxf(in.y, 0.0f), 1.0f);
        *reinterpret_cast<float2*>(output + 2 * i) = out;
    }

    // Scalar tail
    if (aligned < size) {
        for (int i = aligned + (tid % 2) * 0; i < size; i += stride * 2) {
            output[i] = fminf(fmaxf(input[i], 0.0f), 1.0f);
        }
        if (tid == 0 && (size & 1)) {
            // handled in loop above only if stride*2 reaches; cover remainder
        }
    }
}

extern "C" void fused_relu_hardtanh_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int threads = 256;
    const int blocks = 1024;
    fused_relu_hardtanh_kernel<<<blocks, threads, 0, stream>>>(
        output, input, size);
}

