#include <cuda_runtime.h>

// Fused ReLU -> ReLU. Both passes are elementwise max(x, 0), so the chain
// collapses to a single max(x, 0) pass: one load, one store instead of two
// full read/write round trips.
//
// Performance notes (MetaX C500, warp size 64, 104 SMs):
//  - float4 vectorized loads/stores to maximize bytes per memory transaction
//  - FIXED grid (1024 blocks) + grid-stride loop; a one-thread-per-element
//    grid of ~768K blocks measured only ~600 GB/s here, while a fixed
//    1024-block grid-stride loop reaches ~1300 GB/s vs a ~1350 GB/s ceiling.
//  - 256 threads/block = 4 warps of 64.

template<int BLOCK_SIZE, int VEC>
__global__ void fused_relu_relu_impl(float* __restrict__ output,
                                     const float* __restrict__ input,
                                     int size) {
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const int stride = BLOCK_SIZE * gridDim.x;
    const int n_vec = size >> 2;  // number of float4 elements

    // Vectorized body: 4 elements per thread per iteration.
    if (VEC == 4) {
        const float4* in4 = reinterpret_cast<const float4*>(input);
        float4* out4 = reinterpret_cast<float4*>(output);
        for (int i = tid; i < n_vec; i += stride) {
            float4 v = in4[i];
            v.x = fmaxf(v.x, 0.0f);
            v.y = fmaxf(v.y, 0.0f);
            v.z = fmaxf(v.z, 0.0f);
            v.w = fmaxf(v.w, 0.0f);
            out4[i] = v;
        }
    } else if (VEC == 2) {
        const int n2 = size >> 1;
        const float2* in2 = reinterpret_cast<const float2*>(input);
        float2* out2 = reinterpret_cast<float2*>(output);
        for (int i = tid; i < n2; i += stride) {
            float2 v = in2[i];
            v.x = fmaxf(v.x, 0.0f);
            v.y = fmaxf(v.y, 0.0f);
            out2[i] = v;
        }
    } else {
        for (int i = tid; i < size; i += stride) {
            output[i] = fmaxf(input[i], 0.0f);
        }
    }

    // Scalar tail for the elements that don't fill a full vector.
    // Each thread handles the trailing elements with a strided pattern.
    const int tail_start = n_vec * 4;
    const int rem = size - tail_start;
    if (rem > 0) {
        for (int i = tid; i < rem; i += stride) {
            output[tail_start + i] = fmaxf(input[tail_start + i], 0.0f);
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void fused_relu_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed grid of 1024 blocks regardless of size: keeps the grid coarse
    // enough for 104 SMs and lets the grid-stride loop absorb the remainder.
    const int blocks = 1024;

    switch (config) {
        case 0: // float4, 256 threads
            fused_relu_relu_impl<256, 4><<<blocks, 256, 0, stream>>>(
                output, input, size);
            break;
        case 1: // float4, 128 threads
            fused_relu_relu_impl<128, 4><<<blocks, 128, 0, stream>>>(
                output, input, size);
            break;
        case 2: // float4, 512 threads
            fused_relu_relu_impl<512, 4><<<blocks, 512, 0, stream>>>(
                output, input, size);
            break;
        case 3: // float2, 256 threads
            fused_relu_relu_impl<256, 2><<<blocks, 256, 0, stream>>>(
                output, input, size);
            break;
        default: // scalar fallback, 256 threads
            fused_relu_relu_impl<256, 1><<<blocks, 256, 0, stream>>>(
                output, input, size);
            break;
    }
}

