#include <cuda_runtime.h>

// Fused relu(relu(x)) == relu(x): single-pass memory-bound elementwise kernel.
// Tuned for MetaX C500 (104 SMs, warp 64): float2 vectorized loads with a
// fixed 1024-block grid-stride loop instead of one thread per element.

__global__ void fused_relu2_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    const int BLOCK = 256;
    unsigned long long tid = (unsigned long long)blockIdx.x * BLOCK + threadIdx.x;
    const unsigned long long total = (unsigned long long)gridDim.x * BLOCK;

    // Float2 lanes: each thread handles 2 elements per iteration.
    const unsigned long long tid2 = tid * 2ULL;
    const unsigned long long stride2 = total * 2ULL;

    if (tid2 >= size) return;

    // Fast path: aligned float2 load/store (size even, tid2+1 < size).
    if (size % 2ULL == 0ULL) {
        for (unsigned long long i = tid2; i + 1ULL < size; i += stride2) {
            float2 v = *reinterpret_cast<const float2*>(input + i);
            float2 o;
            o.x = fmaxf(v.x, 0.0f);
            o.y = fmaxf(v.y, 0.0f);
            *reinterpret_cast<float2*>(output + i) = o;
        }
    } else {
        for (unsigned long long i = tid2; i + 1ULL < size; i += stride2) {
            float2 v = *reinterpret_cast<const float2*>(input + i);
            float2 o;
            o.x = fmaxf(v.x, 0.0f);
            o.y = fmaxf(v.y, 0.0f);
            *reinterpret_cast<float2*>(output + i) = o;
        }
        if (tid == 0) {
            output[size - 1ULL] = fmaxf(input[size - 1ULL], 0.0f);
        }
    }
}

extern "C" void fused_relu2_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    if (size == 0ULL) return;

    const int BLOCK = 256;
    // Fixed grid: 1024 blocks keeps all 104 SMs fed with ~2.5 waves each,
    // avoiding the fine-grid trap that caps scalar kernels at ~600 GB/s.
    int grid = 1024;

    // Small inputs: don't oversubscribe.
    unsigned long long needed = (size + 1ULL) / 2ULL;
    unsigned long long max_blocks = (needed + BLOCK - 1ULL) / BLOCK;
    if ((unsigned long long)grid > max_blocks) {
        grid = (int)max_blocks;
        if (grid < 1) grid = 1;
    }

    fused_relu2_kernel<<<grid, BLOCK, 0, stream>>>(output, input, size);
}

