#include <cuda_runtime.h>

// Fused leaky_relu(x, 0.01) followed by relu(x):
//   leaky: x >= 0 ? x : 0.01*x
//   then : max(0, leaky)  ->  x >= 0 ? x : max(0, 0.01*x) = x > 0 ? x : 0
// Equivalent to relu on the leaky output. Single memory pass.
template<int BLOCK_SIZE, int VEC>
__global__ void fused_leaky_relu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size)
{
    constexpr int K = 8;                 // 8-way ILP per thread
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x;

    // Scalar tail path is not needed: size is a multiple of 4 (3.1M elements);
    // guard anyway for arbitrary sizes by clamping via scalar fallback loop.
    int64_t base = (int64_t)tid * VEC;
    int64_t vec_size = size / VEC;

    // Vectorized main loop with fixed grid-stride and ILP unroll.
    for (int64_t i = base; i + (K - 1) * (int64_t)stride < vec_size; i += (int64_t)K * stride) {
        float4 v[K];
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            v[k] = *reinterpret_cast<const float4*>(input + (i + (int64_t)k * stride) * VEC);
        }
        #pragma unroll
        for (int k = 0; k < K; ++k) {
            float4 o;
            o.x = fmaxf(v[k].x, 0.0f);
            o.y = fmaxf(v[k].y, 0.0f);
            o.z = fmaxf(v[k].z, 0.0f);
            o.w = fmaxf(v[k].w, 0.0f);
            *reinterpret_cast<float4*>(output + (i + (int64_t)k * stride) * VEC) = o;
        }
    }

    // Remainder: single-element grid-stride.
    for (int64_t i = base; i < vec_size; i += stride) {
        float4 v = *reinterpret_cast<const float4*>(input + i * VEC);
        float4 o;
        o.x = fmaxf(v.x, 0.0f);
        o.y = fmaxf(v.y, 0.0f);
        o.z = fmaxf(v.z, 0.0f);
        o.w = fmaxf(v.w, 0.0f);
        *reinterpret_cast<float4*>(output + i * VEC) = o;
    }

    // Scalar tail for elements past the vector boundary.
    for (int64_t i = vec_size * VEC + tid; i < size; i += (int64_t)BLOCK_SIZE * gridDim.x) {
        output[i] = fmaxf(input[i], 0.0f);
    }
}

// Scalar fallback kernel (config 1) for non-4-aligned sizes.
template<int BLOCK_SIZE>
__global__ void fused_leaky_relu_relu_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int64_t size)
{
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int64_t stride = (int64_t)BLOCK_SIZE * gridDim.x;
    for (int64_t i = tid; i < size; i += stride) {
        output[i] = fmaxf(input[i], 0.0f);
    }
}

extern "C" void fused_leaky_relu_relu_launcher(
    float* output,
    const float* input,
    int64_t size,
    int config,
    cudaStream_t stream)
{
    if (size <= 0) return;

    const int64_t NVEC = 4;  // float4
    int64_t vec_size = size / NVEC;

    if (config == 1 || vec_size == 0) {
        // Scalar path: fixed 1024-block grid-stride loop.
        const int BLOCK = 256;
        const int64_t GRID = 1024;
        int64_t total = (int64_t)BLOCK * GRID;
        int blocks = (int)((size + total - 1) / total);
        if (blocks < 1) blocks = 1;
        if (blocks > 1024) blocks = 1024;
        fused_leaky_relu_relu_scalar_kernel<256>
            <<<blocks, BLOCK, 0, stream>>>(output, input, size);
        return;
    }

    // Vectorized path: 256 threads/block, cap blocks so each thread handles
    // multiple vector elements via the grid-stride loop (avoids the
    // fine-grid trap observed on this device).
    const int BLOCK = 256;
    int blocks = 1024;
    int64_t total_threads = (int64_t)BLOCK * blocks;
    if ((int64_t)vec_size < total_threads) {
        blocks = (int)((vec_size + BLOCK - 1) / BLOCK);
        if (blocks < 1) blocks = 1;
    }
    fused_leaky_relu_relu_kernel<256, 4>
        <<<blocks, BLOCK, 0, stream>>>(output, input, size);
}

