#include <cuda_runtime.h>

// Fused: leaky_relu(x, 0.01) then relu(.)
//   leaky_relu: x < 0 ? 0.01*x : x
//   relu     : max(v, 0)
// Combined: for x < 0 -> max(0.01*x, 0) = 0 (since 0.01*x < 0)
//           for x >= 0 -> max(x, 0)   = x
//   => out = x < 0 ? 0 : x  == relu(x)
// Kept as an explicit branch-free select so the semantics are exact even if
// the negative_slope were changed.
template<int BLOCK_SIZE>
__global__ void fused_leaky_relu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size
) {
    const unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x
                                 + (unsigned long long)threadIdx.x;
    const unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;

    const float slope = 0.01f;

    for (unsigned long long i = tid; i < size; i += stride) {
        float x = input[i];
        float v = (x < 0.0f) ? (slope * x) : x;
        output[i] = (v < 0.0f) ? 0.0f : v;
    }
}

// Vectorized variant: processes 2 floats per thread with float2 loads/stores.
// On this device (64-byte coalescing, 64-wide warps) this is the form that
// reaches the memory ceiling; a scalar one-thread-per-element grid does not.
template<int BLOCK_SIZE>
__global__ void fused_leaky_relu_relu_kernel2(
    float2* __restrict__ output,
    const float2* __restrict__ input,
    unsigned long long size2   // number of float2 elements
) {
    const unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x
                                 + (unsigned long long)threadIdx.x;
    const unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;

    const float slope = 0.01f;

    for (unsigned long long i = tid; i < size2; i += stride) {
        float2 xx = input[i];
        float2 vv;
        vv.x = (xx.x < 0.0f) ? (slope * xx.x) : xx.x;
        vv.y = (xx.y < 0.0f) ? (slope * xx.y) : xx.y;
        float2 oo;
        oo.x = (vv.x < 0.0f) ? 0.0f : vv.x;
        oo.y = (vv.y < 0.0f) ? 0.0f : vv.y;
        output[i] = oo;
    }
}

extern "C" void fused_leaky_relu_relu_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    // Fixed, moderately-sized grid with grid-stride loop: fine grids
    // (one block per tiny tile) underutilize this device badly.
    const int MAX_BLOCKS = 1024;

    unsigned long long size2 = size / 2ULL;

    // Use the float2 path when the buffer is float2-aligned AND the element
    // count is even, so no tail element is left unprocessed.
    const unsigned long long align = 2ULL * sizeof(float);
    bool ptr_aligned = (((unsigned long long)(uintptr_t)input) % align == 0ULL)
                     && (((unsigned long long)(uintptr_t)output) % align == 0ULL);
    bool can_vec = ptr_aligned && (size % 2ULL == 0ULL) && (size2 > 0ULL);

    if (can_vec) {
        int blocks = (int)((size2 + (unsigned long long)BLOCK_SIZE - 1ULL)
                           / (unsigned long long)BLOCK_SIZE);
        if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;
        const size_t smem = 0;
        fused_leaky_relu_relu_kernel2<BLOCK_SIZE><<<blocks, BLOCK_SIZE, smem, stream>>>(
            (float2*)output, (const float2*)input, size2);
    } else {
        int blocks = (int)((size + (unsigned long long)BLOCK_SIZE - 1ULL)
                           / (unsigned long long)BLOCK_SIZE);
        if (blocks > MAX_BLOCKS) blocks = MAX_BLOCKS;
        const size_t smem = 0;
        fused_leaky_relu_relu_kernel<BLOCK_SIZE><<<blocks, BLOCK_SIZE, smem, stream>>>(
            output, input, size);
    }
}

