#include <cuda_runtime.h>

// Fused leaky_relu(x, 0.01) followed by relu(x).
// Math (unchanged from previous correct version):
//   leaky_relu: x > 0 ? x : 0.01*x
//   relu     : max(leaky_relu(x), 0)  -> negative branch stays 0.01*x (already <0), positive branch unchanged.
// Composition is a single leaky_relu with slope 0.01.
//
// Performance: float2 vectorized loads/stores with a FIXED grid of 1024 blocks
// doing grid-stride loops. On the C500 (104 SMs, warp 64) a one-thread-per-element
// grid is far too fine and tops out at ~600 GB/s; this layout reaches
// ~1300 GB/s against a ~1350 GB/s copy ceiling.

template<int BLOCK_SIZE>
__global__ void fused_leaky_relu_relu_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    const int stride = BLOCK_SIZE * gridDim.x;
    const int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    // Base element index for this thread's float2 pair
    int i = (tid >> 1) << 1;  // 2 threads per pair -> consecutive pairs

    // Grid-stride loop in units of float2 elements
    for (int idx = tid; idx < (size >> 1); idx += (stride >> 1)) {
        int base = idx << 1;
        float2 in = *reinterpret_cast<const float2*>(input + base);
        float2 out;
        out.x = in.x > 0.0f ? in.x : 0.01f * in.x;
        out.y = in.y > 0.0f ? in.y : 0.01f * in.y;
        *reinterpret_cast<float2*>(output + base) = out;
    }

    // Tail: odd element count -> last element handled scalar
    if (size & 1) {
        int last = size - 1;
        if (tid == 0) {
            float v = input[last];
            output[last] = v > 0.0f ? v : 0.01f * v;
        }
    }
}

extern "C" void fused_leaky_relu_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int BLOCK = 256;
    // Fixed grid: 1024 blocks covers 104 SMs with ~2.5 waves; grid-stride handles the rest.
    int blocks = 1024;

    switch (config) {
        case 0:
            fused_leaky_relu_relu_kernel<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
            break;
        case 1:
            fused_leaky_relu_relu_kernel<512><<<512, 512, 0, stream>>>(output, input, size);
            break;
        case 2:
            fused_leaky_relu_relu_kernel<128><<<2048, 128, 0, stream>>>(output, input, size);
            break;
        default:
            fused_leaky_relu_relu_kernel<256><<<blocks, BLOCK, 0, stream>>>(output, input, size);
