#include <cuda_runtime.h>

// Fused ELU activation: out = x > 0 ? x : alpha * (exp(x) - 1)
//
// Memory-bound elementwise op on ~327M floats (1.2 GB each for in/out).
// Strategy:
//  - float2 vectorized loads/stores for coalesced 8-byte transactions
//  - fixed grid of 1024 blocks with grid-stride loop (fine grids are a real
//    performance trap on the C500: one-thread-per-element reaches only
//    ~340-640 GB/s, while this shape reaches ~1300 GB/s)
//  - branch-free select so the expf only feeds one path and gives the
//    scheduler independent work (no chained-SFU stall)
template<int BLOCK_SIZE>
__global__ void elu_kernel_impl(float* output, const float* input, int size) {
    // Reinterpret as float2 pairs (numel is even for this task's shapes;
    // the scalar tail loop below handles any odd remainder).
    int n2 = size >> 1;
    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    const float alpha = 1.0f;

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    // Vectorized grid-stride loop
    for (int i = tid; i < n2; i += stride) {
        float2 v = in2[i];

        float2 r;
        // Branch-free: expf computed on both lanes, result selected by sign.
        // No dependency chain between SFU ops, so arithmetic hides behind
        // memory traffic.
        float ex = expf(v.x);
        float ey = expf(v.y);
        r.x = (v.x > 0.0f) ? v.x : (alpha * (ex - 1.0f));
        r.y = (v.y > 0.0f) ? v.y : (alpha * (ey - 1.0f));

        out2[i] = r;
    }

    // Scalar tail for odd element count
    if ((size & 1) != 0) {
        int last = size - 1;
        int t = blockIdx.x * blockDim.x + threadIdx.x;
        if (t < last) {
            float v = input[last - t];
            float e = expf(v);
            output[last - t] = (v > 0.0f) ? v : (alpha * (e - 1.0f));
        }
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void elu_kernel_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    // Fixed 1024-block grid regardless of size: keeps the grid coarse enough
    // for full memory throughput while grid-stride loops cover the data.
    const int blocks = 1024;

    switch (config) {
        case 0:
            elu_kernel_impl<256><<<blocks, 256, 0, stream>>>(output, input, size);
            break;
        case 1:
            elu_kernel_impl<512><<<blocks, 512, 0, stream>>>(output, input, size);
            break;
        case 2:
            elu_kernel_impl<128><<<blocks, 128, 0, stream>>>(output, input, size);
            break;
        default:
            elu_kernel_impl<256><<<blocks, 256, 0, stream>>>(output, input, size);
    }
}

