#include <cuda_runtime.h>

// Fused ELU: out = x > 0 ? x : alpha*(exp(x)-1)
// Memory-bound elementwise op: single pass, float2 vectorized loads,
// fixed grid of 1024 blocks with grid-stride loops (104 SMs on C500,
// warp size 64). Avoids the one-thread-per-element fine-grid trap.

template<int VEC, int THREADS>
__global__ void elu_fused_kernel(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 int size) {
    int tid = blockIdx.x * THREADS + threadIdx.x;
    int stride = (THREADS * VEC) * gridDim.x;

    // Float2 path: aligned pairs
    if (VEC == 2) {
        int n2 = size >> 1;
        for (int i = tid; i < n2; i += (THREADS * gridDim.x)) {
            float2 in = reinterpret_cast<const float2*>(input)[i];
            float2 out;
            out.x = in.x > 0.0f ? in.x : 1.0f * (expf(in.x) - 1.0f);
            out.y = in.y > 0.0f ? in.y : 1.0f * (expf(in.y) - 1.0f);
            reinterpret_cast<float2*>(output)[i] = out;
        }
        // tail element
        int tail = (n2 << 1) + (int)(blockIdx.x == 0 && threadIdx.x == 0);
        if (size & 1) {
            int last = size - 1;
            float v = input[last];
            output[last] = v > 0.0f ? v : (expf(v) - 1.0f);
        }
        (void)tail;
    }
}

extern "C" void elu_fused_launcher(
    float* output,
    const float* input,
    int size,
    cudaStream_t stream
) {
    const int THREADS = 256;
    const int BLOCKS  = 1024;

    if (size <= 0) return;

    // Odd-sized input: run scalar path only on the last element via a
    // separate tiny launch so the vector path stays aligned.
    int n2 = size >> 1;
    if (n2 > 0) {
        elu_fused_kernel<2, THREADS><<<BLOCKS, THREADS, 0, stream>>>(
            output, input, size);
    }
    if (size & 1) {
        int last = size - 1;
        float v;
        // single-element tail handled on host-side device call below
       cudaMemcpyAsync(&v, input + last, sizeof(float),
                        cudaMemcpyDeviceToHost, stream);
        float r = v > 0.0f ? v : (expf(v) - 1.0f);
        cudaMemcpyAsync(output + last, &r, sizeof(float),
                        cudaMemcpyHostToDevice, stream);
    }
}

