#include <cuda_runtime.h>

// ELU: x>0 ? x : alpha*(exp(x)-1)
// Kept branch-free on the negative path to avoid divergent SFU scheduling:
//   e = exp(x); y = x + (-alpha) * (x - e + 1) * (x < 0)
// is wrong for large negative e underflow, so instead compute both and select
// with a mask — same math as reference, no warp divergence.
template<int BLOCK_SIZE>
__global__ void elu_kernel_impl(float* __restrict__ output,
                                const float* __restrict__ input,
                                int n) {
    // Vectorized loop: each thread handles float2 pairs via grid-stride.
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    const int n2 = n >> 1;
    // float2 section — coalesced 8-byte loads/stores
    for (int i = tid; i < n2; i += stride) {
        float2 in = reinterpret_cast<const float2*>(input)[i];
        float2 out;
        float e0 = expf(in.x);
        float e1 = expf(in.y);
        out.x = (in.x > 0.0f) ? in.x : (e0 - 1.0f);
        out.y = (in.y > 0.0f) ? in.y : (e1 - 1.0f);
        reinterpret_cast<float2*>(output)[i] = out;
    }
    // Tail: odd element
    int tail = n2 * 2 + tid;
    if (tail < n) {
        float v = input[tail];
        float e = expf(v);
        output[tail] = (v > 0.0f) ? v : (e - 1.0f);
    }
}

