                                    const float* input,
                                    int n,
                                    int config,
                                    cudaStream_t stream) {
    // Fixed grid of 1024 blocks: avoids the one-thread-per-element trap that
    // reaches only ~600 GB/s on this 104-SM device, and keeps the grid
    // grid-stride for any size.
    const int blocks = 1024;
    const int threads = 256;
    switch (config) {
        case 0:
            elu_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, n);
            break;
        case 1:
            elu_kernel_impl<128><<<blocks, 128, 0, stream>>>(output, input, n);
            break;
        case 2:
            elu_kernel_impl<512><<<2048, 256, 0, stream>>>(output, input, n);
            break;
        default:
            elu_kernel_impl<256><<<blocks, threads, 0, stream>>>(output, input, n);
    }
}

