#include <cuda_runtime.h>

// Fused exp -> relu elementwise kernel.
// Memory-bound on this device: use float2 vectorized loads/stores with a
// fixed grid-stride loop so the 104 SMs stay fully filled.
template<int BLOCK_SIZE>
__global__ void fused_exp_relu_impl(float* __restrict__ output,
                                    const float* __restrict__ input,
                                    unsigned long long size) {
    const unsigned long long tid = (unsigned long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride = (unsigned long long)BLOCK_SIZE * gridDim.x;

    float2 reg;
    for (unsigned long long i = tid; i < size; i += stride) {
        reg = reinterpret_cast<const float2*>(input)[i];
        reg.x = __expf(reg.x);
        reg.y = __expf(reg.y);
        reg.x = reg.x > 0.0f ? reg.x : 0.0f;
        reg.y = reg.y > 0.0f ? reg.y : 0.0f;
        reinterpret_cast<float2*>(output)[i] = reg;
    }
}

extern "C" void fused_exp_relu_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    cudaStream_t stream
) {
    const int BLOCK_SIZE = 256;
    // Fixed grid: 1024 blocks of 256 threads = 262144 lanes, each handling
    // a float2. Plenty of grid-stride iterations for a 241M-element tensor.
    const int GRID = 1024;
    fused_exp_relu_impl<BLOCK_SIZE><<<GRID, BLOCK_SIZE, 0, stream>>>(
        output, input, size);
}

