#include <cuda_runtime.h>

// Fused exp(x) followed by ReLU: out = max(0, exp(x)).
// Memory-bound elementwise chain; single pass over memory.
// Uses float4 vectorized loads with a grid-stride loop, plus a scalar
// cleanup pass for the tail when numel is not a multiple of 4.

__device__ __forceinline__ float exp_relu(float v) {
    float e = __expf(v);
    return e > 0.0f ? e : 0.0f;   // expf > 0 always; keep branch cheap
}

// Vectorized body: each thread handles 4 floats per iteration.
__global__ void exp_relu_vec4_kernel(
    float4* __restrict__ output,
    const float4* __restrict__ input,
    int n4   // number of float4 elements
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = tid; i < n4; i += stride) {
        float4 in = input[i];
        float4 out;
        out.x = exp_relu(in.x);
        out.y = exp_relu(in.y);
        out.z = exp_relu(in.z);
        out.w = exp_relu(in.w);
        output[i] = out;
    }
}

// Scalar tail kernel for elements beyond the last full float4.
__global__ void exp_relu_scalar_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    int begin,
    int size
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;

    for (int i = begin + tid; i < size; i += stride) {
        output[i] = exp_relu(input[i]);
    }
}

extern "C" void fused_exp_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Number of complete float4 groups.
    int n4 = size >> 2;
    int rem = size - (n4 << 2);   // 0..3 leftover elements

    if (n4 > 0) {
        const int BLOCK = 256;
        // Fixed, moderate grid: grid-stride loop covers all work.
        int grid = (n4 + BLOCK - 1) / BLOCK;
        int max_grid = 1024;
        if (grid > max_grid) grid = max_grid;
        exp_relu_vec4_kernel<<<grid, BLOCK, 0, stream>>>(
            (float4*)output, (const float4*)input, n4);
    }

    if (rem > 0) {
        const int BLOCK = 128;
        int tail = rem;
        int grid = (tail + BLOCK - 1) / BLOCK;
        if (grid < 1) grid = 1;
        exp_relu_scalar_kernel<<<grid, BLOCK, 0, stream>>>(
            output, input, size - rem, size);
    }
}

