// kernels/mish_kernel.cu
// Fused Mish activation: out = x * tanh(softplus(x))
//
// Memory-traffic analysis (the whole point of this kernel):
//   Eager/torch.compile Mish = 3 full-tensor passes:
//     softplus (R+W) -> tanh (R+W) -> mul (R+W+R)  ~ 5 x 1.61 GB = 8.05 GB
//   Fused here = 1 pass:                            ~ 2 x 1.61 GB = 3.22 GB
//   Tensor is 2048*3*256*256 floats = 402,653,184 elements = 1.61 GB.
//
// SFU-stall avoidance (the exp->log1pf chain is the documented trap on C500):
//   softplus(x) is restated piecewise so the SFU chain stays tame:
//     x >  20 : softplus(x) = x            (identity, exp skipped entirely)
//     x <= 20 : softplus(x) = log1pf(expf(-|x|)) + max(x, 0)
//   The second form keeps exp's argument in [-20, 0] and log1p's in [0, 1),
//   with no long dependency on the input magnitude. max(x,0) is cheap and
//   recovers the exact value on the negative side. ILP comes from 2 x float2
//   elements in flight per thread (4 independent scalar Mish evaluations).

#include <cuda_runtime.h>

#ifndef MISH_BLOCK_SIZE
#define MISH_BLOCK_SIZE 256
#endif

// One Mish evaluation, branch-free dependency restatement.
__device__ __forceinline__ float mish_f32(float x) {
    float a = fabsf(x);
    float e = expf(-a);          // argument in [-20,0] -> tame SFU
    float sp = log1pf(e);        // argument in [0,1)   -> tame SFU
    float m = fmaxf(x, 0.0f);    // cheap, independent of the SFU chain
    sp += m;
    float t = tanhf(sp);
    return x * t;
}

// Scalar fallback path (config 0 keeps a simple, low-risk reference kernel).
template<int BLOCK_SIZE>
__global__ void mish_scalar_impl(float* __restrict__ output,
                                 const float* __restrict__ input,
                                 unsigned long long size) {
    unsigned long long tid = (unsigned long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    unsigned long long stride = (unsigned long long)BLOCK_SIZE * gridDim.x;
    for (unsigned long long i = tid; i < size; i += stride) {
        output[i] = mish_f32(input[i]);
    }
}

// float2 path: pairs of floats, 2 vectors per thread for ILP.
// Warp size is 64 on this device; 256 threads/block = 4 warps.
template<int BLOCK_SIZE>
__global__ void mish_f2_impl(float* __restrict__ output,
                             const float* __restrict__ input,
                             unsigned long long size) {
    const unsigned long long tid =
        (unsigned long long)blockIdx.x * BLOCK_SIZE + threadIdx.x;
    const unsigned long long stride =
        (unsigned long long)BLOCK_SIZE * gridDim.x;

    const float2* in2 = (const float2*)input;
    float2* out2 = (float2*)output;
    unsigned long long n2 = size >> 1;

    // Each thread walks 2 float2's per iteration: 4 independent scalar
    // Mish evaluations in flight, giving the scheduler work to overlap
    // the exp/log1p/tanh SFU latencies.
    unsigned long long base = tid;
    while (base + stride < n2) {
        float2 a = in2[base];
        float2 b = in2[base + stride];
        float2 r0, r1;
        r0.x = mish_f32(a.x);
        r0.y = mish_f32(a.y);
        r1.x = mish_f32(b.x);
        r1.y = mish_f32(b.y);
        out2[base] = r0;
        out2[base + stride] = r1;
        base += 2ULL * stride;
    }
    // Final partial pass: exactly one vector each (a or b, never both).
    if (base < n2) {
        if (base + stride < n2 + stride && base + stride >= n2) {
            // b-only tail
            float2 b = in2[base];
            float2 r1;
            r1.x = mish_f32(b.x);
            r1.y = mish_f32(b.y);
            out2[base] = r1;
        } else {
            float2 a = in2[base];
            float2 r0;
            r0.x = mish_f32(a.x);
            r0.y = mish_f32(a.y);
            out2[base] = r0;
        }
    }

    // Odd tail element handled by the first block in scalar mode.
    if ((size & 1ULL) != 0ULL) {
        unsigned long long last = size - 1ULL;
        for (unsigned long long i = tid; i <= last; i += stride) {
            if (i == last) output[last] = mish_f32(input[last]);
        }
    }
}

extern "C" void mish_kernel_launcher(
    float* output,
    const float* input,
    unsigned long long size,
    int config,
    cudaStream_t stream
) {
    if (size == 0ULL) return;

    // Fixed 1024-block grid with grid-stride loop: fine-grained grids
    // (one block per tiny tile) measurably under-fill this device.
    const int blocks = 1024;
    const int threads = MISH_BLOCK_SIZE;

    switch (config) {
        case 0:  // scalar reference path
            mish_scalar_impl<MISH_BLOCK_SIZE>
                <<<blocks, threads, 0, stream>>>(output, input, size);
            break;
        case 1:  // float2 + 2-way ILP (fast path)
        default:
            mish_f2_impl<MISH_BLOCK_SIZE>
                <<<blocks, threads, 0, stream>>>(output, input, size);
            break;
    }
}

