#include <cuda_runtime.h>

// Fused ReLU + HardSigmoid: y = clamp(x,0,6) / 6, applied to max(x, 0).
// Hardware: MetaX C500, warp size 64, 104 SMs, 64 KB shared mem per block.
// Strategy: single pass over memory, float4 vectorized loads/stores,
// fixed grid of blocks with grid-stride loop (no one-thread-per-element grid).

__device__ __forceinline__ float4 relu_hardsigmoid4(float4 v) {
    // ReLU: clamp to [0, +inf)
    v.x = fmaxf(v.x, 0.0f);
    v.y = fmaxf(v.y, 0.0f);
    v.z = fmaxf(v.z, 0.0f);
    v.w = fmaxf(v.w, 0.0f);
    // HardSigmoid: clamp(x, 0, 6) / 6  (PyTorch convention)
    const float inv6 = 0.16666667163372039794921875f; // 1/6 in float
    float4 r;
    r.x = fminf(fmaxf(v.x, 0.0f), 6.0f) * inv6;
    r.y = fminf(fmaxf(v.y, 0.0f), 6.0f) * inv6;
    r.z = fminf(fmaxf(v.z, 0.0f), 6.0f) * inv6;
    r.w = fminf(fmaxf(v.w, 0.0f), 6.0f) * inv6;
    return r;
}

template<int BLOCK_SIZE>
__global__ void fused_relu_hardsigmoid_kernel(
    float* __restrict__ output,
    const float* __restrict__ input,
    size_t size
) {
    // Vector element index for this thread
    size_t tid = static_cast<size_t>(blockIdx.x) * BLOCK_SIZE + threadIdx.x;
    const size_t stride = static_cast<size_t>(BLOCK_SIZE) * gridDim.x;

    const size_t n4 = size / 4;           // full float4 elements
    const size_t rem = size - n4 * 4;     // leftover scalar elements

    const float4* in4 = reinterpret_cast<const float4*>(input);
    float4* out4 = reinterpret_cast<float4*>(output);

    // Grid-stride loop over aligned float4 elements
    for (size_t i = tid; i < n4; i += stride) {
        float4 v = in4[i];               // 16-byte coalesced load
        out4[i] = relu_hardsigmoid4(v);  // 16-byte coalesced store
    }

    // Handle tail: scalar elements after the last full float4.
    // Threads with index < rem handle one scalar each; only the first
    // block's low threads participate to keep it simple and cheap.
    size_t tail_base = n4 * 4;
    if (tail_base + tid < size && tid < rem) {
        size_t idx = tail_base + tid;
        float v = input[idx];
        v = fmaxf(v, 0.0f);
        output[idx] = fminf(v, 6.0f) * 0.16666667163372039794921875f;
    }
}

extern "C" void fused_relu_hardsigmoid_launcher(
    float* output,
    const float* input,
    size_t size,
    cudaStream_t stream
) {
    if (size == 0) return;

    const int BLOCK_SIZE = 256;          // 4 warps of 64 threads
    // Fixed grid sized to fill the 104 SMs with several waves of work;
    // grid-stride loop covers the rest. Avoids a 256M-block grid.
    int blocks = 1024;

    // Small inputs: don't over-launch
    size_t n4 = size / 4;
    size_t needed = (n4 + BLOCK_SIZE - 1) / BLOCK_SIZE;
    if (static_cast<size_t>(blocks) > needed) {
        blocks = (needed > 0) ? static_cast<int>(needed) : 1;
    }
    if (blocks < 1) blocks = 1;

    fused_relu_hardsigmoid_kernel<256><<<blocks, BLOCK_SIZE, 0, stream>>>(
        output, input, size
    );
}

