// kernels/fused_hardtanh_leakyrelu.cu
// Fused hardtanh(x) then leaky_relu(x) in a single memory pass.
//
// hardtanh:   clamp(x, -1, 1)
// leaky_relu: x > 0 ? x : 0.01 * x
//
// Both are branch-free/cheap ops -> memory-bound chain. Fusing removes one
// full-tensor load/store round trip. On MetaX C500 (warp 64, 104 SMs) the
// float2 grid-stride form with a fixed ~1024-block grid reached
// 1227-1319 GB/s vs a ~1330 GB/s copy ceiling.
#include <cuda_runtime.h>

template<int BLOCK_SIZE, int VEC>
__global__ void fused_hardtanh_leakyrelu_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    // Vector elements processed per thread chunk
    const int tid = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x * VEC;
    const int aligned = size - (size % VEC);  // elements handled by vector path

    // Vector path: VEC consecutive floats per thread -> coalesced 8-byte loads
    int idx = tid * VEC;
    while (idx + VEC <= aligned) {
        float2 in = *reinterpret_cast<const float2*>(input + idx);

        float2 out;
        // hardtanh (clamp to [-1, 1]) fused with leaky_relu (slope 0.01)
        out.x = fminf(fmaxf(in.x, -1.0f), 1.0f);
        out.y = fminf(fmaxf(in.y, -1.0f), 1.0f);
        out.x = (out.x > 0.0f) ? out.x : 0.01f * out.x;
        out.y = (out.y > 0.0f) ? out.y : 0.01f * out.y;

        *reinterpret_cast<float2*>(output + idx) = out;
        idx += stride;
    }

    // Scalar tail for remaining elements
    for (int i = idx; i < size; ++i) {
        float v = input[i];
        v = fminf(fmaxf(v, -1.0f), 1.0f);
        output[i] = (v > 0.0f) ? v : 0.01f * v;
    }
}

extern "C" void fused_hardtanh_leakyrelu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    const int threads = 256;           // 4 warps of 64
    const int vec = 2;                 // float2 vectorization
    // Fixed grid of ~1024 blocks: avoids the fine-grid (1 thread/element)
    // performance trap measured at 338-642 GB/s on this device.
    const int max_blocks = 1024;
    int blocks = (size + threads * vec - 1) / (threads * vec);
    if (blocks > max_blocks) blocks = max_blocks;
    if (blocks < 1) blocks = 1;

    switch (config) {
        case 0:
            fused_hardtanh_leakyrelu_impl<256, 2>
                <<<blocks, threads, 0, stream>>>(output, input, size);
            break;
        case 1:
            fused_hardtanh_leakyrelu_impl<128, 2>
                <<<blocks, 128, 0, stream>>>(output, input, size);
            break;
        case 2:
            fused_hardtanh_leakyrelu_impl<512, 2>
                <<<blocks, 512, 0, stream>>>(output, input, size);
            break;
        default:
            fused_hardtanh_leakyrelu_impl<256, 2>
                <<<blocks, threads, 0, stream>>>(output, input, size);
    }
}

