// kernels/hardtanh_leaky_relu.cu
// Fused hardtanh(x) then leaky_relu(x) in a single memory pass.
//   hardtanh:  clamp(x, -1.0, 1.0)
//   leaky_relu: max(x, 0) + negative_slope * min(x, 0), negative_slope = 0.01
//
// Performance design (MetaX C500, warp size 64, 104 SMs):
//   - float2 vectorized loads/stores (coalesced 8-byte lanes)
//   - FIXED grid of 1024 blocks x 256 threads, grid-stride loop
//     (a one-thread-per-element grid is far finer than 104 SMs can fill
//      and measured only ~600 GB/s; this pattern reaches ~1300 GB/s)

#include <cuda_runtime.h>

template<int BLOCK_SIZE>
__device__ __forceinline__ float2 fused_op_float2(float2 v) {
    // hardtanh: clamp to [-1, 1]
    float a = v.x;
    float b = v.y;
    float t0 = fminf(fmaxf(a, -1.0f), 1.0f);
    float t1 = fminf(fmaxf(b, -1.0f), 1.0f);
    // leaky_relu with negative_slope = 0.01
    v.x = fmaxf(t0, 0.0f) + 0.01f * fminf(t0, 0.0f);
    v.y = fmaxf(t1, 0.0f) + 0.01f * fminf(t1, 0.0f);
    return v;
}

template<int BLOCK_SIZE>
__global__ void hardtanh_leaky_relu_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size           // number of float elements
) {
    // Vectorized element index
    int tid = blockIdx.x * BLOCK_SIZE + threadIdx.x;
    int stride = BLOCK_SIZE * gridDim.x;
    int nvec = size >> 1;  // number of float2 pairs

    float2* out2 = reinterpret_cast<float2*>(output);
    const float2* in2 = reinterpret_cast<const float2*>(input);

    // Grid-stride loop over aligned float2 pairs
    for (int i = tid; i < nvec; i += stride) {
        out2[i] = fused_op_float2<BLOCK_SIZE>(in2[i]);
    }

    // Handle the single odd element (if size is odd)
    int tail = tid;
    if (size & 1) {
        if (tail == 0) {
            int idx = size - 1;
            float v = input[idx];
            float t = fminf(fmaxf(v, -1.0f), 1.0f);
            output[idx] = fmaxf(t, 0.0f) + 0.01f * fminf(t, 0.0f);
        }
        // Advance the base index for any cleanup below
        tail += nvec;
    }
    (void)tail;
}

// Legacy scalar fallback path (config 0), used as a reference/backup.
__global__ void hardtanh_leaky_relu_scalar_impl(
    float* __restrict__ output,
    const float* __restrict__ input,
    int size
) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = tid; i < size; i += stride) {
        float v = input[i];
        float t = fminf(fmaxf(v, -1.0f), 1.0f);
        output[i] = fmaxf(t, 0.0f) + 0.01f * fminf(t, 0.0f);
    }
}

// C-interface launcher (no PyTorch dependencies)
extern "C" void hardtanh_leaky_relu_launcher(
    float* output,
    const float* input,
    int size,
    int config,
    cudaStream_t stream
) {
    if (size <= 0) return;

    // Fixed grid sized to fill the device: 104 SMs, ~256 threads/block.
    // A fixed 1024-block grid keeps the wave count constant and lets each
    // block process a grid-stride chunk, avoiding the tiny-grid trap.
    const int FIXED_BLOCKS = 1024;

    switch (config) {
        case 0:
            // scalar fallback (correct, but slower)
            hardtanh_leaky_relu_scalar_impl<<<FIXED_BLOCKS, 256, 0, stream>>>(
                output, input, size);
            break;
        case 1:
            hardtanh_leaky_relu_impl<256><<<FIXED_BLOCKS, 256, 0, stream>>>(
                output, input, size);
            break;
        case 2:
            // 128 threads/block still uses float2, finer strides
            hardtanh_leaky_relu_impl<128><<<2048, 128, 0, stream>>>(
                output, input, size);
            break;
        case 3:
            // 512 threads/block, float2
            hardtanh_leaky_relu_impl<512><<<512, 512, 0, stream>>>(
                output, input, size);
            break;
        default:
            hardtanh_leaky_relu_impl<256><<<FIXED_BLOCKS, 256, 0, stream>>>(
                output, input, size);
            break;
    }
}

