);

torch::Tensor prelu_fused_forward(torch::Tensor input, torch::Tensor weight) {
    if (!input.is_cuda()) input = input.to(torch::kCUDA);
    if (!weight.is_cuda()) weight = weight.to(torch::kCUDA);
    if (input.dtype() != torch::kFloat32) input = input.to(torch::kFloat32);
    if (weight.dtype() != torch::kFloat32) weight = weight.to(torch::kFloat32);
    if (!input.is_contiguous()) input = input.contiguous();
    if (!weight.is_contiguous()) weight = weight.contiguous();

    auto output = torch::empty_like(input);
    int C = (int)weight.numel();

    int numel = (int)input.numel();
    int dims = (int)input.dim();
    long strideC = 0, strideH = 0, strideW = 0;

    if (dims == 4) {
        strideC = input.stride(1);
        strideH = input.stride(2);
        strideW = input.stride(3);
    } else if (dims == 3) {
        strideC = input.stride(0);
        strideH = input.stride(1);
        strideW = input.stride(2);
    } else if (dims == 2) {
        strideC = input.stride(0);
        strideH = input.stride(1);
        strideW = 0;
    } else {
        strideC = numel;
        strideH = 0;
        strideW = 0;
    }

    if (C == 1) { strideC = numel; strideH = 0; strideW = 0; }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    prelu_fused_launcher(
        output.data_ptr<float>(),
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        numel,
        C,
        strideC,
        strideH,
        strideW,
        stream
    );
    return output;
}

