#include <cuda_runtime.h>
#include <math.h>

#define WARP 64

/* Fixed grid, grid-stride, float2 vector loads.
 * C500: 104 SMs, warp 64. 1024 blocks x 256 threads covers plenty of
 * elements per tile; float2 halves the instruction count for the same
 * bytes moved. ceilf/divf are SFU-free compared to expf/log1pf chains.
 */
__global__ void softplus_fused_k(
    float* __restrict__ output,
    const float* __restrict__ input,
    unsigned long long size)
{
    const unsigned long long tid = (unsigned long long)blockIdx.x * blockDim.x + threadIdx.x;
    const unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;

    const unsigned long long size2 = size >> 1;
    const unsigned long long base = tid << 1;

    /* vector body */
    for (unsigned long long i = base; i < size2; i += (stride << 1)) {
        float2 v;
